import { useSSO, useSignIn } from "@clerk/clerk-expo";
import * as Linking from "expo-linking";
import { useRouter } from "expo-router";
import * as WebBrowser from "expo-web-browser";
import React from "react";
import {
  ActivityIndicator,
  Image,
  KeyboardAvoidingView,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";

// IMPORTANT: Must be called at module level for Expo Go
WebBrowser.maybeCompleteAuthSession();

const MerchantLoginScreen = () => {
  const { signIn, setActive, isLoaded } = useSignIn();
  const router = useRouter();
  const linking = Linking.useLinkingURL();
  const LinkRedirectUrl = Linking.createURL("oauth-native-callback", {
    scheme: "dexapos",
  });

  // Native OAuth flow - works in Expo Go
  const { startSSOFlow } = useSSO();

  const [emailAddress, setEmailAddress] = React.useState("");
  const [password, setPassword] = React.useState("");
  const [isLoading, setIsLoading] = React.useState(false);
  const [isGoogleLoading, setIsGoogleLoading] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  // Simple email validation
  const isValidEmail = (email: string) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  };

  // Google OAuth Sign-In - Browser-based, works in Expo Go
  const signInWithGoogle = async () => {
    setIsGoogleLoading(true);
    setError(null);

    try {
      const { createdSessionId, setActive: setActiveSession } =
        await startSSOFlow({
          strategy: "oauth_google",
          redirectUrl: LinkRedirectUrl,
        });

      if (createdSessionId) {
        await setActiveSession!({ session: createdSessionId });
        router.replace("/store-select");
      }
    } catch (err: any) {
      console.log("OAuth error:", err);
      // Don't show error for user cancellation
      if (!err?.message?.includes("cancel")) {
        setError("Google sign-in failed. Please try again.");
      }
    } finally {
      setIsGoogleLoading(false);
    }
  };

  // Email/Password Sign-In
  const handleLogin = async () => {
    if (!isLoaded) return;

    const trimmedEmail = emailAddress.trim().toLowerCase();

    if (!trimmedEmail) {
      setError("Please enter your email address");
      return;
    }

    if (!isValidEmail(trimmedEmail)) {
      setError("Please enter a valid email address");
      return;
    }

    if (!password) {
      setError("Please enter your password");
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const signInAttempt = await signIn.create({
        identifier: trimmedEmail,
        password,
      });

      if (signInAttempt.status === "complete") {
        await setActive({ session: signInAttempt.createdSessionId });
        router.replace("/store-select");
      } else {
        console.error(JSON.stringify(signInAttempt, null, 2));
        // console.log(signInAttempt)
        setError("Sign-in incomplete. Please try again.");
      }
    } catch (err: any) {
      console.error("Sign-in error:", JSON.stringify(err, null, 2));
      if (err.errors && err.errors.length > 0) {
        const errorCode = err.errors[0].code;
        if (errorCode === "form_identifier_not_found") {
          setError("No account found with this email. Please sign up first.");
        } else if (errorCode === "form_password_incorrect") {
          setError("Incorrect password. Please try again.");
        } else if (errorCode === "form_param_format_invalid") {
          setError("Please enter a valid email address.");
        } else {
          setError(
            err.errors[0].longMessage ||
              err.errors[0].message ||
              "Invalid email or password"
          );
        }
      } else {
        setError("An error occurred during sign-in. Please try again.");
      }
    } finally {
      setIsLoading(false);
    }
  };

  const isFormLoading = isLoading || isGoogleLoading;

  return (
    <View className="w-full">
      <Text className="text-3xl font-semibold text-white text-center mb-8">
        Merchant Login
      </Text>

      {error && (
        <View className="bg-red-500/20 border border-red-500 rounded-xl p-4 mb-4">
          <Text className="text-red-400 text-center">{error}</Text>
        </View>
      )}

      {/* Google Sign-In Button - Browser-based OAuth */}
      <TouchableOpacity
        onPress={signInWithGoogle}
        disabled={isFormLoading}
        className={`w-full p-4 rounded-xl items-center justify-center flex-row mb-6 ${
          isFormLoading ? "bg-neutral-600" : "bg-white"
        }`}
      >
        {isGoogleLoading ? (
          <ActivityIndicator color="#4285F4" size="small" />
        ) : (
          <>
            <Image
              source={{
                uri: "https://developers.google.com/identity/images/g-logo.png",
              }}
              className="w-6 h-6 mr-3"
              resizeMode="contain"
            />
            <Text className="text-neutral-800 text-xl font-semibold">
              Continue with Google
            </Text>
          </>
        )}
      </TouchableOpacity>

      {/* Divider */}
      <View className="flex-row items-center mb-6">
        <View className="flex-1 h-[1px] bg-neutral-600" />
        <Text className="text-neutral-400 mx-4 text-lg">or</Text>
        <View className="flex-1 h-[1px] bg-neutral-600" />
      </View>

      <KeyboardAvoidingView behavior="padding" className="mb-4">
        <Text className="text-xl font-medium text-white mb-2">Email</Text>
        <TextInput
          className="w-full p-4 h-16 border text-white border-neutral-200 rounded-xl text-xl"
          placeholder="john@gmail.com"
          placeholderTextColor="#9CA3AF"
          keyboardType="email-address"
          autoCapitalize="none"
          value={emailAddress}
          onChangeText={setEmailAddress}
          editable={!isFormLoading}
        />
      </KeyboardAvoidingView>

      <View className="mb-4">
        <Text className="text-xl font-medium text-white mb-2">Password</Text>
        <KeyboardAvoidingView behavior="position">
          <TextInput
            className="w-full p-4 h-16 border text-white border-neutral-200 rounded-xl text-xl"
            placeholderTextColor="#9CA3AF"
            placeholder="••••••••"
            secureTextEntry
            value={password}
            onChangeText={setPassword}
            editable={!isFormLoading}
          />
        </KeyboardAvoidingView>
      </View>

      <TouchableOpacity className="self-end mb-6">
        <Text className="text-lg font-semibold text-white">
          Forgot Password
        </Text>
      </TouchableOpacity>

      <TouchableOpacity
        onPress={handleLogin}
        disabled={isFormLoading || !emailAddress || !password}
        className={`w-full p-4 rounded-xl items-center ${
          isFormLoading || !emailAddress || !password
            ? "bg-blue-400"
            : "bg-blue-600"
        }`}
      >
        {isLoading ? (
          <ActivityIndicator color="white" size="small" />
        ) : (
          <Text className="text-white text-xl font-bold">Login</Text>
        )}
      </TouchableOpacity>

      <View className="flex-row justify-center mt-6 gap-2">
        <Text className="text-neutral-400 text-lg">Don't have an account?</Text>
        <TouchableOpacity onPress={() => router.push("/sign-up" as any)}>
          <Text className="text-blue-400 text-lg font-semibold">Sign up</Text>
        </TouchableOpacity>
      </View>
    </View>
  );
};

export default MerchantLoginScreen;

import PinDisplay from "@/components/auth/PinDisplay";
import PinNumpad, { NumpadInput } from "@/components/auth/PinNumpad";
import { Dialog, DialogContent } from "@/components/ui/dialog";
import { useLoading } from "@/contexts/LoadingContext";
import { useSupabaseClient } from "@/hooks/useSupabaseClient";
import { useTimeClock } from "@/hooks/useTimeclock";
import { getDeviceId } from "@/lib/deviceId";
import { getDeviceName } from "@/lib/deviceName";
import { EmployeeProfile, useEmployeeStore } from "@/stores/useEmployeeStore";
import { useStoreSettingsStore } from "@/stores/useStoreSettingsStore";
import { useTimeclockStore } from "@/stores/useTimeclockStore";
import { PosStaffLoginResponse } from "@/types/station";
import { useFocusEffect, useLocalSearchParams, useRouter } from "expo-router";
import { Lock } from "lucide-react-native";
import { useCallback, useEffect, useMemo, useState } from "react";
import { Text, TouchableOpacity, View } from "react-native";
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSequence,
  withTiming,
} from "react-native-reanimated";

const MAX_PIN_LENGTH = 4;

const PinLoginScreen = () => {
  const router = useRouter();
  const { forceTakeover } = useLocalSearchParams<{ forceTakeover?: string }>();
  const [pin, setPin] = useState("");
  const [deviceId, setDeviceId] = useState<string>("");
  const supabase = useSupabaseClient();

  // Clear PIN when screen comes into focus
  useFocusEffect(
    useCallback(() => {
      setPin("");
    }, [])
  );

  const { showLoading, hideLoading, isLoading } = useLoading();
  const {
    findEmployeeByPin,
    getEmployeeByStaffId,
    setActiveSession,
    clockIn: employeeClockIn,
  } = useEmployeeStore();
  const selectedStore = useStoreSettingsStore((state) => state.selectedStore);
  const selectedStation = useStoreSettingsStore(
    (state) => state.selectedStation
  );
  const setStationSessionId = useStoreSettingsStore(
    (state) => state.setStationSessionId
  );
  const { getSession, clockIn: timeclockClockIn } = useTimeclockStore();

  const timeClock = useTimeClock();

  const canSubmit = useMemo(
    () =>
      pin.length === MAX_PIN_LENGTH &&
      !isLoading &&
      !!deviceId &&
      !!selectedStore &&
      !!selectedStation,
    [pin, isLoading, deviceId, selectedStore, selectedStation]
  );

  // Get device ID on mount (synchronous with MMKV)
  useEffect(() => {
    console.log("getDeviceId", getDeviceId());
    setDeviceId(getDeviceId());
  }, []);

  // Redirect to station select if no station is selected
  useEffect(() => {
    if (!selectedStation && selectedStore) {
      router.replace("/station-select");
    }
  }, [selectedStation, selectedStore, router]);

  // Animation values for shake effect
  const shakeX = useSharedValue(0);

  const [dialog, setDialog] = useState<{
    visible: boolean;
    title: string;
    message: string;
    variant: "success" | "warning" | "error";
  }>({ visible: false, title: "", message: "", variant: "success" });
  const showDialog = (
    title: string,
    message: string,
    variant: "success" | "warning" | "error"
  ) => setDialog({ visible: true, title, message, variant });
  const hideDialog = () => setDialog((d) => ({ ...d, visible: false }));

  const triggerShakeAnimation = () => {
    shakeX.value = withSequence(
      withTiming(-10, { duration: 100 }),
      withTiming(10, { duration: 100 }),
      withTiming(-10, { duration: 100 }),
      withTiming(10, { duration: 100 }),
      withTiming(0, { duration: 100 })
    );
  };

  const handleKeyPress = (input: NumpadInput) => {
    if (typeof input === "number") {
      if (pin.length < MAX_PIN_LENGTH) {
        setPin((prevPin) => prevPin + input.toString());
      }
    } else {
      switch (input) {
        case "backspace":
          setPin((prevPin) => prevPin.slice(0, -1));
          break;
        case "clear":
          setPin("");
          break;
      }
    }
  };

  const handleLogin = async () => {
    if (!canSubmit || !selectedStore || !selectedStation) {
      showDialog(
        !selectedStore
          ? "No Store Selected"
          : !selectedStation
            ? "No Station Selected"
            : "Invalid PIN",
        !selectedStore
          ? "Please select a store first."
          : !selectedStation
            ? "Please select a station first."
            : `Please enter a ${MAX_PIN_LENGTH}-digit PIN to sign in.`,
        "error"
      );
      return;
    }

    showLoading("Signing in...");

    try {
      const deviceName = getDeviceName();

      // Call the new combined RPC for station + clock in
      console.log("Calling pos_staff_login with:", {
        p_location_id: selectedStore.id,
        p_pin_code: pin,
        p_station_id: selectedStation.id,
        p_device_id: deviceId,
        p_device_name: deviceName,
        p_auto_clock_in: true,
        p_force_takeover: forceTakeover === "true",
      });
      const { data, error } = await supabase.rpc("pos_staff_login", {
        p_location_id: selectedStore.id,
        p_pin_code: pin,
        p_station_id: selectedStation.id,
        p_device_id: deviceId,
        p_device_name: deviceName,
        p_auto_clock_in: true,
        p_force_takeover: forceTakeover === "true",
      });

      // console.log("pos_staff_login response:", data, error);

      if (error) throw error;

      const response = data as PosStaffLoginResponse;

      if (!response.success) {
        hideLoading();

        if (response.error_code === "STATION_IN_USE") {
          showDialog(
            "Station In Use",
            response.current_session
              ? `This station is currently being used by ${response.current_session.staff_name}. Please select a different station or use the Take Over option.`
              : "This station is currently in use.",
            "warning"
          );
          setPin("");
          return;
        }

        triggerShakeAnimation();
        showDialog(
          "Sign In Failed",
          response.error || "Unable to sign in.",
          "error"
        );
        setPin("");
        return;
      }

      // Store session ID for later logout
      if (response.session?.session_id) {
        setStationSessionId(response.session.session_id);
      }

      let employee: EmployeeProfile | null = null;

      // Get employee from local store using staff profile ID
      if (response.staff?.staff_profile_id) {
        employee =
          getEmployeeByStaffId(response.staff.staff_profile_id) || null;
      }

      if (employee) {
        // Sync local session state
        const existingSession = getSession(employee.id);
        if (!existingSession) {
          employeeClockIn(employee.id);
          timeclockClockIn(employee.id);
        }
        setActiveSession(employee);
      }

      hideLoading();

      if (!employee) {
        // Staff found in database but not synced locally - still allow login
        console.warn(
          "Staff profile not found locally:",
          response.staff?.staff_profile_id
        );
      }

      setPin("");
      router.replace("/home");
    } catch (error: any) {
      hideLoading();
      triggerShakeAnimation();
      const errorMessage =
        error?.message?.includes("PIN") || error?.message?.includes("pin")
          ? "The PIN you entered is incorrect."
          : "Unable to sign in. Please try again.";
      showDialog("Sign In Failed", errorMessage, "error");
      setPin("");
    }
  };

  const handleClockIn = async () => {
    if (!canSubmit || !selectedStore) {
      showDialog(
        !selectedStore ? "No Store Selected" : "Invalid PIN",
        !selectedStore
          ? "Please select a store first."
          : `Please enter a ${MAX_PIN_LENGTH}-digit PIN.`,
        "error"
      );
      return;
    }

    showLoading("Clocking in...");

    try {
      // Use server for clock in (handles both online and offline via the hook)
      await timeClock.clockIn(pin, selectedStore.id, deviceId);
      // Success toast is handled by the hook
      hideLoading();
      setPin("");
    } catch (error) {
      hideLoading();
      triggerShakeAnimation();
      showDialog(
        "Clock In Failed",
        "Unable to clock in. Please try again.",
        "error"
      );
      setPin("");
    }
  };

  const handleClockOut = async () => {
    if (!canSubmit || !selectedStore) {
      showDialog(
        !selectedStore ? "No Store Selected" : "Invalid PIN",
        !selectedStore
          ? "Please select a store first."
          : `Please enter a ${MAX_PIN_LENGTH}-digit PIN.`,
        "error"
      );
      return;
    }

    showLoading("Clocking out...");

    try {
      // Use server for clock out (handles both online and offline via the hook)
      await timeClock.clockOut(pin, selectedStore.id, deviceId);
      // Success toast is handled by the hook
      hideLoading();
      setPin("");
    } catch (error) {
      hideLoading();
      triggerShakeAnimation();
      showDialog(
        "Clock Out Failed",
        "Unable to clock out. Please try again.",
        "error"
      );
      setPin("");
    }
  };

  const handleOpenTimeclock = async () => {
    if (!canSubmit || !selectedStore) {
      showDialog(
        !selectedStore ? "No Store Selected" : "Invalid PIN",
        !selectedStore
          ? "Please select a store first."
          : `Please enter a ${MAX_PIN_LENGTH}-digit PIN to open the timeclock.`,
        "error"
      );
      return;
    }

    showLoading("Verifying...");

    try {
      let employee: EmployeeProfile | null = null;

      // Try server-side verification first (works online, queues offline)
      const result = await timeClock.signIn(pin, selectedStore.id, deviceId);

      if (result?.staff_id) {
        // Server returned employee ID - get local employee record
        employee = getEmployeeByStaffId(result.staff_id) || null;
      } else if (result?.queued) {
        // Request was queued (offline) - verify locally
        employee = await findEmployeeByPin(pin);
      }

      hideLoading();

      if (!employee) {
        triggerShakeAnimation();
        showDialog("Invalid PIN", "The PIN you entered is incorrect.", "error");
        setPin("");
        return;
      }

      // Check for manager-level roles
      const managerRoles = [
        "merchant.manager",
        "merchant.admin",
        "merchant.owner",
      ];
      if (!managerRoles.includes(employee.role)) {
        showDialog(
          "Permission Denied",
          "Only managers can access the timeclock.",
          "error"
        );
        setPin("");
        return;
      }

      setPin("");
      router.push("/timeclock");
    } catch (error) {
      hideLoading();
      triggerShakeAnimation();
      showDialog(
        "Verification Failed",
        "Unable to verify PIN. Please try again.",
        "error"
      );
      setPin("");
    }
  };

  // Animated style for shake effect
  const shakeStyle = useAnimatedStyle(() => {
    return {
      transform: [{ translateX: shakeX.value }],
    };
  });

  return (
    <>
      <Animated.View style={shakeStyle} className="w-full m-auto">
        <Text className="text-3xl font-semibold text-white text-center mb-8">
          Enter Your PIN
        </Text>

        <PinDisplay pinLength={pin.length} maxLength={MAX_PIN_LENGTH} />

        <View className="w-full mt-4">
          <PinNumpad onKeyPress={handleKeyPress} />
        </View>

        <View className="flex-row gap-4 mt-6 items-stretch">
          <TouchableOpacity
            onPress={handleLogin}
            disabled={!canSubmit}
            className={`flex-1 min-w-0 p-4 bg-[#2D2D2D] border border-gray-700 rounded-xl items-center justify-center ${
              !canSubmit && "opacity-50"
            }`}
          >
            <Text className="text-blue-400 text-xl font-bold">SIGN IN</Text>
          </TouchableOpacity>

          <TouchableOpacity
            onPress={handleClockIn}
            disabled={!canSubmit}
            className={`flex-1 min-w-0 p-4 bg-[#2D2D2D] border border-gray-700 rounded-xl items-center justify-center ${
              !canSubmit && "opacity-50"
            }`}
          >
            <Text className="text-green-400 text-xl font-bold">CLOCK IN</Text>
          </TouchableOpacity>

          <TouchableOpacity
            onPress={handleClockOut}
            disabled={!canSubmit}
            className={`flex-1 min-w-0 p-4 bg-[#2D2D2D] border border-gray-700 rounded-xl items-center justify-center ${
              !canSubmit && "opacity-50"
            }`}
          >
            <Text className="text-red-400 text-xl font-bold">CLOCK OUT</Text>
          </TouchableOpacity>
        </View>

        <TouchableOpacity
          onPress={handleOpenTimeclock}
          className="self-center mt-6 p-4 bg-[#2D2D2D] border border-gray-700 rounded-xl items-center justify-center flex-row"
        >
          <Text className="text-lg font-semibold text-white mr-2">
            Open Timeclock
          </Text>
          <Lock color="white" size={20} />
        </TouchableOpacity>
      </Animated.View>

      <Dialog open={dialog.visible} onOpenChange={hideDialog}>
        <DialogContent className="min-w-xl w-[500px] ">
          <View
            className="min-w-xl w-full rounded-2xl p-6"
            style={{
              backgroundColor: "#2b2b2b",
              borderWidth: 1,
              borderColor:
                dialog.variant === "success"
                  ? "#059669"
                  : dialog.variant === "warning"
                    ? "#F59E0B"
                    : "#EF4444",
            }}
          >
            <Text
              className={`text-2xl font-semibold mb-2 ${
                dialog.variant === "success"
                  ? "text-green-400"
                  : dialog.variant === "warning"
                    ? "text-yellow-400"
                    : "text-red-400"
              }`}
            >
              {dialog.title}
            </Text>
            <Text className="text-xl text-gray-200 mb-6">{dialog.message}</Text>
            <TouchableOpacity
              onPress={hideDialog}
              className="self-end px-5 py-2.5 rounded-lg"
              style={{
                backgroundColor:
                  dialog.variant === "success"
                    ? "#065F46"
                    : dialog.variant === "warning"
                      ? "#92400E"
                      : "#7F1D1D",
              }}
            >
              <Text className="text-white text-lg font-medium">OK</Text>
            </TouchableOpacity>
          </View>
        </DialogContent>
      </Dialog>
    </>
  );
};

export default PinLoginScreen;

import { useOAuth, useSignUp } from "@clerk/clerk-expo";
import { useRouter } from "expo-router";
import * as WebBrowser from "expo-web-browser";
import React from "react";
import {
    ActivityIndicator,
    Image,
    KeyboardAvoidingView,
    Text,
    TextInput,
    TouchableOpacity,
    View,
} from "react-native";

// IMPORTANT: Must be called at module level for Expo Go
WebBrowser.maybeCompleteAuthSession();

export default function SignUpScreen() {
    const { isLoaded, signUp, setActive } = useSignUp();
    const router = useRouter();

    // Native OAuth flow - works in Expo Go
    const { startOAuthFlow } = useOAuth({ strategy: "oauth_google" });

    const [emailAddress, setEmailAddress] = React.useState("");
    const [password, setPassword] = React.useState("");
    const [confirmPassword, setConfirmPassword] = React.useState("");
    const [pendingVerification, setPendingVerification] = React.useState(false);
    const [code, setCode] = React.useState("");
    const [isLoading, setIsLoading] = React.useState(false);
    const [isGoogleLoading, setIsGoogleLoading] = React.useState(false);
    const [error, setError] = React.useState<string | null>(null);

    // Simple email validation
    const isValidEmail = (email: string) => {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email);
    };

    // Google OAuth Sign-Up - Browser-based, works in Expo Go
    const signUpWithGoogle = async () => {
        setIsGoogleLoading(true);
        setError(null);

        try {
            const { createdSessionId, setActive: setActiveSession } =
                await startOAuthFlow();

            if (createdSessionId) {
                await setActiveSession!({ session: createdSessionId });
                router.replace("/store-select");
            }
        } catch (err: any) {
            console.log("OAuth error:", err);
            // Don't show error for user cancellation
            if (!err?.message?.includes("cancel")) {
                setError("Google sign-up failed. Please try again.");
            }
        } finally {
            setIsGoogleLoading(false);
        }
    };

    // Email/Password Sign-Up
    const onSignUpPress = async () => {
        if (!isLoaded) return;

        const trimmedEmail = emailAddress.trim().toLowerCase();

        if (!trimmedEmail) {
            setError("Please enter your email address");
            return;
        }

        if (!isValidEmail(trimmedEmail)) {
            setError("Please enter a valid email address");
            return;
        }

        if (password !== confirmPassword) {
            setError("Passwords do not match");
            return;
        }

        if (password.length < 8) {
            setError("Password must be at least 8 characters");
            return;
        }

        setIsLoading(true);
        setError(null);

        try {
            await signUp.create({
                emailAddress: trimmedEmail,
                password,
            });

            await signUp.prepareEmailAddressVerification({ strategy: "email_code" });
            setPendingVerification(true);
        } catch (err: any) {
            console.error("Sign-up error:", JSON.stringify(err, null, 2));
            if (err.errors && err.errors.length > 0) {
                const errorCode = err.errors[0].code;
                if (errorCode === "form_identifier_exists") {
                    setError("An account with this email already exists. Please sign in.");
                } else if (errorCode === "form_param_format_invalid") {
                    setError("Please enter a valid email address.");
                } else if (errorCode === "form_password_pwned") {
                    setError("This password has been compromised. Please choose a different one.");
                } else {
                    setError(err.errors[0].longMessage || err.errors[0].message || "Sign-up failed.");
                }
            } else {
                setError("An error occurred during sign-up. Please try again.");
            }
        } finally {
            setIsLoading(false);
        }
    };

    // Verify email code
    const onVerifyPress = async () => {
        if (!isLoaded) return;

        setIsLoading(true);
        setError(null);

        try {
            const signUpAttempt = await signUp.attemptEmailAddressVerification({ code });

            if (signUpAttempt.status === "complete") {
                await setActive({ session: signUpAttempt.createdSessionId });
                router.replace("/store-select");
            } else {
                console.error(JSON.stringify(signUpAttempt, null, 2));
                setError("Verification incomplete. Please try again.");
            }
        } catch (err: any) {
            console.error("Verification error:", JSON.stringify(err, null, 2));
            if (err.errors && err.errors.length > 0) {
                setError(err.errors[0].message || "Invalid verification code");
            } else {
                setError("Verification failed. Please try again.");
            }
        } finally {
            setIsLoading(false);
        }
    };

    const isFormLoading = isLoading || isGoogleLoading;

    // Verification screen
    if (pendingVerification) {
        return (
            <View className="w-full">
                <Text className="text-3xl font-semibold text-white text-center mb-4">
                    Verify Your Email
                </Text>
                <Text className="text-neutral-400 text-center mb-8">
                    We've sent a verification code to {emailAddress}
                </Text>

                {error && (
                    <View className="bg-red-500/20 border border-red-500 rounded-xl p-4 mb-4">
                        <Text className="text-red-400 text-center">{error}</Text>
                    </View>
                )}

                <KeyboardAvoidingView behavior="padding" className="mb-6">
                    <Text className="text-xl font-medium text-white mb-2">
                        Verification Code
                    </Text>
                    <TextInput
                        className="w-full p-4 h-16 border text-white border-neutral-200 rounded-xl text-xl text-center tracking-widest"
                        value={code}
                        placeholder="Enter 6-digit code"
                        placeholderTextColor="#9CA3AF"
                        keyboardType="number-pad"
                        onChangeText={setCode}
                        maxLength={6}
                        editable={!isLoading}
                    />
                </KeyboardAvoidingView>

                <TouchableOpacity
                    onPress={onVerifyPress}
                    disabled={isLoading || code.length < 6}
                    className={`w-full p-4 rounded-xl items-center ${isLoading || code.length < 6 ? "bg-green-400" : "bg-green-600"
                        }`}
                >
                    {isLoading ? (
                        <ActivityIndicator color="white" size="small" />
                    ) : (
                        <Text className="text-white text-xl font-bold">Verify Email</Text>
                    )}
                </TouchableOpacity>

                <TouchableOpacity
                    onPress={() => setPendingVerification(false)}
                    className="mt-4"
                >
                    <Text className="text-neutral-400 text-center">← Back to sign up</Text>
                </TouchableOpacity>
            </View>
        );
    }

    // Sign-up form
    return (
        <View className="w-full">
            <Text className="text-3xl font-semibold text-white text-center mb-8">
                Create Account
            </Text>

            {error && (
