    if (!selectedStore?.id) {
      alert("No store selected");
      return;
    }
    try {
      if (id) {
        await updateInventoryItem(id, data, selectedStore.id);
      } else {
        await addInventoryItem(data, selectedStore.id);
      }
    } catch (e) {
      console.error("Failed to save item:", e);
