      ? parseInt(bulkReorderThreshold)
      : undefined;
    selectedMenuIds.forEach((id) => {
      updateMenuItem(id, {
        stockQuantity: stockQty,
        reorderThreshold: threshold,
      });
    });
    setBulkStockModalOpen(false);
    setBulkStockQuantity("");
    setBulkReorderThreshold("");
