            <View className="flex-row gap-2">
              <TouchableOpacity
                onPress={() => handleBulkSetAvailability(true)}
                className="px-3 py-2 bg-green-600 rounded-lg"
              >
                <Text className="text-white text-base font-semibold">
                  Set On
                </Text>
              </TouchableOpacity>
              <TouchableOpacity
                onPress={() => handleBulkSetAvailability(false)}
                className="px-3 py-2 bg-yellow-600 rounded-lg"
              >
                <Text className="text-white text-base font-semibold">
                  Set Off
                </Text>
              </TouchableOpacity>
              <TouchableOpacity
                onPress={handleOpenBulkStockModal}
                className="px-3 py-2 bg-blue-600 rounded-lg"
              >
                <Text className="text-white text-base font-semibold">
                  Update Stock
                </Text>
              </TouchableOpacity>
              <TouchableOpacity
                onPress={clearSelection}
                className="px-3 py-2 bg-gray-600 rounded-lg"
              >
                <Text className="text-white text-base font-semibold">
                  Clear
                </Text>
              </TouchableOpacity>
            </View>
          </View>
        )}

        <InventoryItemFormModal
          isOpen={modalMode === "add" || modalMode === "edit"}
          onClose={handleCloseModal}
          onSave={handleSaveItem}
          vendors={vendors}
          initialData={selectedItem}
        />
        <ConfirmationModal
          isOpen={isDeleteConfirmOpen}
          onClose={() => setDeleteConfirmOpen(false)}
          onConfirm={handleConfirmDelete}
          title="Delete Item"
          description={`Delete "${selectedItem?.name}"?`}
          confirmText="Delete"
          variant="destructive"
        />

        <Modal
          visible={isStockModalOpen}
          transparent
          animationType="fade"
          onRequestClose={handleCloseStockModal}
        >
          <KeyboardAvoidingView
            behavior={Platform.OS === "ios" ? "padding" : "height"}
            className="flex-1"
          >
            <View className="flex-1 bg-black/50 justify-center items-center px-4">
              <View className="bg-[#303030] rounded-xl p-4 w-full max-w-sm">
                <Text className="text-xl font-bold text-white mb-3">
                  Update Stock - {selectedMenuItem?.name}
                </Text>
                <View className="mb-3">
                  <Text className="text-base text-gray-300 mb-1.5">
                    Stock Quantity
                  </Text>
                  <TextInput
                    value={stockQuantity}
                    onChangeText={setStockQuantity}
                    placeholder="Enter quantity"
                    keyboardType="numeric"
                    className="bg-[#212121] border border-gray-600 rounded-lg px-3 py-2 text-white text-base h-16"
                  />
                </View>
                <View className="mb-4">
                  <Text className="text-base text-gray-300 mb-1.5">
                    Reorder Threshold
                  </Text>
                  <TextInput
                    value={reorderThreshold}
                    onChangeText={setReorderThreshold}
                    placeholder="Enter threshold"
                    keyboardType="numeric"
                    className="bg-[#212121] border border-gray-600 rounded-lg px-3 py-2 text-white text-base h-16"
                  />
                </View>
                <View className="flex-row gap-2">
                  <TouchableOpacity
                    onPress={handleCloseStockModal}
                    className="flex-1 py-2 px-3 bg-gray-600 rounded-lg"
                  >
                    <Text className="text-white text-base font-semibold text-center">
                      Cancel
                    </Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    onPress={handleSaveStock}
                    className="flex-1 py-2 px-3 bg-blue-600 rounded-lg"
                  >
                    <Text className="text-white text-base font-semibold text-center">
                      Save
                    </Text>
                  </TouchableOpacity>
                </View>
              </View>
            </View>
          </KeyboardAvoidingView>
        </Modal>

        {/* --- MODAL 2: BULK INVENTORY STOCK UPDATE --- */}
        <Modal
          visible={isBulkInventoryStockModalOpen}
          transparent
          animationType="fade"
          onRequestClose={handleCloseBulkInventoryStockModal}
        >
          <KeyboardAvoidingView
            behavior={Platform.OS === "ios" ? "padding" : "height"}
            className="flex-1"
          >
            <View className="flex-1 bg-black/50 justify-center items-center px-4">
              <View className="bg-[#303030] rounded-xl p-4 w-full max-w-sm">
                <Text className="text-xl font-bold text-white mb-3">
                  Update Stock ({selectedInventoryIds.length} items)
                </Text>
                <View className="mb-3">
                  <Text className="text-base text-gray-300 mb-1.5">
                    Stock Quantity
                  </Text>
                  <TextInput
                    value={bulkInventoryStockQuantity}
                    onChangeText={setBulkInventoryStockQuantity}
                    placeholder="(Optional)"
                    keyboardType="numeric"
                    className="bg-[#212121] border border-gray-600 rounded-lg px-3 py-2 text-white text-base h-16"
                  />
                </View>
                <View className="mb-4">
                  <Text className="text-base text-gray-300 mb-1.5">
                    Reorder Threshold
                  </Text>
                  <TextInput
                    value={bulkInventoryReorderThreshold}
                    onChangeText={setBulkInventoryReorderThreshold}
                    placeholder="(Optional)"
                    keyboardType="numeric"
                    className="bg-[#212121] border border-gray-600 rounded-lg px-3 py-2 text-white text-base h-16"
                  />
                </View>
                <View className="flex-row gap-2">
                  <TouchableOpacity
                    onPress={handleCloseBulkInventoryStockModal}
                    className="flex-1 py-2 px-3 bg-gray-600 rounded-lg"
                  >
                    <Text className="text-white text-base font-semibold text-center">
                      Cancel
                    </Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    onPress={handleSaveBulkInventoryStock}
                    className="flex-1 py-2 px-3 bg-blue-600 rounded-lg"
                  >
                    <Text className="text-white text-base font-semibold text-center">
                      Save
                    </Text>
                  </TouchableOpacity>
                </View>
              </View>
            </View>
          </KeyboardAvoidingView>
        </Modal>

        {/* --- MODAL 3: BULK MENU STOCK UPDATE --- */}
        <Modal
          visible={isBulkStockModalOpen}
          transparent
          animationType="fade"
          onRequestClose={handleCloseBulkStockModal}
        >
          <KeyboardAvoidingView
            behavior={Platform.OS === "ios" ? "padding" : "height"}
            className="flex-1"
          >
            <View className="flex-1 bg-black/50 justify-center items-center px-4">
              <View className="bg-[#303030] rounded-xl p-4 w-full max-w-sm">
                <Text className="text-xl font-bold text-white mb-3">
                  Update Stock ({selectedMenuIds.length} items)
                </Text>
                <View className="mb-3">
                  <Text className="text-base text-gray-300 mb-1.5">
                    Stock Quantity
                  </Text>
                  <TextInput
                    value={bulkStockQuantity}
                    onChangeText={setBulkStockQuantity}
                    placeholder="(Optional)"
                    keyboardType="numeric"
                    className="bg-[#212121] border border-gray-600 rounded-lg px-3 py-2 text-white text-base h-16"
                  />
                </View>
                <View className="mb-4">
                  <Text className="text-base text-gray-300 mb-1.5">
                    Reorder Threshold
                  </Text>
                  <TextInput
                    value={bulkReorderThreshold}
                    onChangeText={setBulkReorderThreshold}
                    placeholder="(Optional)"
                    keyboardType="numeric"
                    className="bg-[#212121] border border-gray-600 rounded-lg px-3 py-2 text-white text-base h-16"
                  />
                </View>
                <View className="flex-row gap-2">
                  <TouchableOpacity
                    onPress={handleCloseBulkStockModal}
                    className="flex-1 py-2 px-3 bg-gray-600 rounded-lg"
                  >
                    <Text className="text-white text-base font-semibold text-center">
                      Cancel
                    </Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    onPress={handleSaveBulkStock}
                    className="flex-1 py-2 px-3 bg-blue-600 rounded-lg"
                  >
                    <Text className="text-white text-base font-semibold text-center">
                      Save
                    </Text>
                  </TouchableOpacity>
                </View>
              </View>
            </View>
          </KeyboardAvoidingView>
        </Modal>

        <AddInventoryItemSheet ref={addItemSheetRef} />
      </View>
      <MenuSearchSheet
        ref={menuSearchSheetRef}
        menuItems={menuItems}
        selectedIds={selectedMenuIds}
        onToggle={(itemId) => {
          toggleSelectMenuItem(itemId);
        }}
      />
      <InventorySearchSheet
        ref={invSearchSheetRef}
        inventoryItems={inventoryItems}
        vendors={vendors}
        selectedIds={selectedInventoryIds}
        onToggle={toggleSelectInventoryItem}
        onToggleAll={handleToggleAllInventory}
        onClear={clearInventorySelection}
        onBulkUpdate={handleOpenBulkInventoryStockModal}
        onEdit={handleOpenEditModal}
        onDelete={handleOpenDeleteConfirm}
      />
    </BottomSheetModalProvider>
  );
};

export default InventoryScreen;

import { InventoryItem } from "@/lib/types";
import { useInventoryStore } from "@/stores/useInventoryStore";
import BottomSheet, {
  BottomSheetBackdrop,
  BottomSheetFlatList,
} from "@gorhom/bottom-sheet";
import { useLocalSearchParams, useRouter } from "expo-router";
import {
  AlertTriangle,
  ArrowLeft,
  CheckCircle,
  Edit,
  History,
  Minus,
  Plus,
  Save,
  X,
} from "lucide-react-native";
import React, { useEffect, useMemo, useState } from "react";
import {
  KeyboardAvoidingView, // <--- Imported
  Modal,
  Platform, // <--- Imported
  ScrollView,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";

interface InventoryTransaction {
  id: string;
  itemId: string;
  type:
    | "PO_RECEIPT"
    | "SALES_CONSUMPTION"
    | "SPOILAGE_WASTE"
    | "INTERNAL_TRANSFER"
    | "COUNT_CORRECTION"
    | "NOTE";
  quantityChange: number;
  resultingQuantity: number;
  reason: string;
  notes?: string;
  timestamp: string;
  userId: string;
  reference?: string;
}

const IngredientItemScreen = () => {
  const { itemId } = useLocalSearchParams();
  const router = useRouter();
  const { inventoryItems, updateInventoryItem, vendors } = useInventoryStore();
  const [showError, setShowError] = useState({
    title: "",
    description: "",
    show: false,
  });
  const [item, setItem] = useState<InventoryItem | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [editStockTrackingMode, setEditStockTrackingMode] = useState<
    "in_stock" | "out_of_stock" | "quantity"
  >("in_stock");
  const [isLogUsageModalOpen, setIsLogUsageModalOpen] = useState(false);
  const [isAddStockModalOpen, setIsAddStockModalOpen] = useState(false);
  const [inventoryHistory, setInventoryHistory] = useState<
    InventoryTransaction[]
  >([]);

  // Bottom sheet refs
  const historySheetRef = React.useRef<BottomSheet>(null);
  const snapPoints = useMemo(() => ["90%"], []);

  // Edit form state
  const [editForm, setEditForm] = useState({
    name: "",
    sku: "",
    category: "",
    defaultVendor: "",
    unitOfMeasure: "",
    stockQuantity: "",
    reorderThreshold: "",
    cost: "",
  });

  // Log usage form state
  const [logUsageForm, setLogUsageForm] = useState({
    quantityUsed: "",
    reason: "",
    customReason: "",
    notes: "",
  });

  // Add stock form state
  const [addStockForm, setAddStockForm] = useState({
    quantityAdded: "",
    reason: "",
    notes: "",
  });
  // Custom note entry for history sheet
  const [historyNote, setHistoryNote] = useState("");

  useEffect(() => {
    if (itemId && inventoryItems.length > 0) {
      const foundItem = inventoryItems.find((i) => i.id === itemId);
      if (foundItem) {
        setItem(foundItem);
        setEditForm({
          name: foundItem.name,
          sku: "",
          category: foundItem.category,
          defaultVendor: foundItem.vendorId || "",
          unitOfMeasure: foundItem.unit,
          stockQuantity: foundItem.stockQuantity?.toString() || "",
          reorderThreshold: foundItem.reorderThreshold?.toString() || "",
          cost: foundItem.cost?.toString() || "",
        });
        setEditStockTrackingMode(
          (foundItem as any).stockTrackingMode || "in_stock"
        );
        generateMockHistory(foundItem.id);
      }
    }
  }, [itemId, inventoryItems]);

  const generateMockHistory = (id: string) => {
    const mockHistory: InventoryTransaction[] = [
      {
        id: "1",
        itemId: id,
        type: "PO_RECEIPT",
        quantityChange: 100,
        resultingQuantity: 100,
        reason: "Initial stock from purchase order",
        timestamp: "2024-01-10T09:00:00Z",
        userId: "user1",
        reference: "PO-2024-001",
      },
      {
        id: "2",
        itemId: id,
        type: "SALES_CONSUMPTION",
        quantityChange: -15,
        resultingQuantity: 85,
        reason: "Used in menu item preparation",
        notes: "Used in 15 menu items",
        timestamp: "2024-01-12T14:30:00Z",
        userId: "user2",
      },
      {
        id: "3",
        itemId: id,
        type: "SPOILAGE_WASTE",
        quantityChange: -5,
        resultingQuantity: 80,
        reason: "Spoilage/Waste",
        notes: "Expired items removed",
        timestamp: "2024-01-14T11:15:00Z",
        userId: "user1",
      },
      {
        id: "4",
        itemId: id,
        type: "COUNT_CORRECTION",
        quantityChange: 3,
        resultingQuantity: 83,
        reason: "Count correction",
        notes: "Found additional units during inventory count",
        timestamp: "2024-01-16T16:45:00Z",
        userId: "user3",
      },
    ];
    setInventoryHistory(mockHistory);
  };

  const handleSave = () => {
    if (!item) return;

    const roundedStockQuantity =
      editForm.stockQuantity !== ""
        ? Number(parseFloat(editForm.stockQuantity).toFixed(2))
        : item.stockQuantity;
    // Only persist quantity fields when mode is quantity
    const quantityFields =
      editStockTrackingMode === "quantity"
        ? {
            stockQuantity: roundedStockQuantity,
            reorderThreshold: editForm.reorderThreshold
              ? parseInt(editForm.reorderThreshold)
              : item.reorderThreshold,
          }
        : {
            stockQuantity: undefined,
            reorderThreshold: undefined,
          };
    const updatedItem = {
      ...item,
      name: editForm.name,
      category: editForm.category,
      vendorId: editForm.defaultVendor || null,
      unit: editForm.unitOfMeasure as any,
      ...(quantityFields as any),
      stockTrackingMode: editStockTrackingMode,
      cost: editForm.cost ? parseFloat(editForm.cost) : item.cost,
    };

    updateInventoryItem(item.id, updatedItem);
    setItem(updatedItem);
    setIsEditing(false);
  };

  const handleLogUsage = () => {
    if (!item || !logUsageForm.quantityUsed || !logUsageForm.reason) return;
    if (editStockTrackingMode !== "quantity") {
      setShowError({
        title: "This item is not set to track stock by quantity.",
        description:
          "Please set the stock tracking mode to quantity to log usage.",
        show: true,
      });
      return;
    } // Only applicable when tracking by quantity
    const quantityChange = -parseFloat(logUsageForm.quantityUsed);
    const newQuantity = Number(
      ((item.stockQuantity || 0) + quantityChange).toFixed(2)
    );

    const newTransaction: InventoryTransaction = {
      id: Date.now().toString(),
      itemId: item.id,
      type: (logUsageForm.reason === "CUSTOM"
        ? "COUNT_CORRECTION"
        : logUsageForm.reason) as any,
      quantityChange,
      resultingQuantity: newQuantity,
      reason:
        logUsageForm.reason === "CUSTOM" && logUsageForm.customReason.trim()
          ? logUsageForm.customReason.trim()
          : logUsageForm.reason,
      notes: logUsageForm.notes,
      timestamp: new Date().toISOString(),
      userId: "current_user",
    };

    updateInventoryItem(item.id, {
      ...item,
      stockQuantity: newQuantity,
    });
    setInventoryHistory((prev) => [newTransaction, ...prev]);
    setLogUsageForm({
      quantityUsed: "",
      reason: "",
      customReason: "",
      notes: "",
    });
    setIsLogUsageModalOpen(false);
    setItem((prev) => (prev ? { ...prev, stockQuantity: newQuantity } : null));
  };

  const handleAddStock = () => {
    if (!item || !addStockForm.quantityAdded || !addStockForm.reason) return;
    if (editStockTrackingMode !== "quantity") return; // Only applicable when tracking by quantity

    const quantityChange = parseFloat(addStockForm.quantityAdded);
    const newQuantity = Number(
      ((item.stockQuantity || 0) + quantityChange).toFixed(2)
    );

    const newTransaction: InventoryTransaction = {
      id: Date.now().toString(),
      itemId: item.id,
      type: addStockForm.reason as any,
      quantityChange,
      resultingQuantity: newQuantity,
      reason: addStockForm.reason,
      notes: addStockForm.notes,
      timestamp: new Date().toISOString(),
      userId: "current_user",
    };

    updateInventoryItem(item.id, {
      ...item,
      stockQuantity: newQuantity,
    });
    setInventoryHistory((prev) => [newTransaction, ...prev]);
    setAddStockForm({ quantityAdded: "", reason: "", notes: "" });
    setIsAddStockModalOpen(false);
    setItem((prev) => (prev ? { ...prev, stockQuantity: newQuantity } : null));
  };

  const getTransactionTypeLabel = (type: string) => {
    switch (type) {
      case "PO_RECEIPT":
        return "PO Receipt";
      case "SALES_CONSUMPTION":
        return "Sales/Consumption";
      case "SPOILAGE_WASTE":
        return "Spoilage/Waste";
      case "INTERNAL_TRANSFER":
        return "Internal Transfer";
      case "COUNT_CORRECTION":
        return "Count Correction";
      case "NOTE":
        return "Note";
      default:
        return type;
    }
  };

  const getTransactionTypeColor = (type: string) => {
    switch (type) {
      case "PO_RECEIPT":
        return "bg-green-600";
      case "SALES_CONSUMPTION":
        return "bg-blue-600";
      case "SPOILAGE_WASTE":
        return "bg-red-600";
      case "INTERNAL_TRANSFER":
        return "bg-yellow-600";
      case "COUNT_CORRECTION":
        return "bg-purple-600";
      default:
        return "bg-gray-600";
    }
  };

  const getVendorName = (vendorId?: string | null) => {
    if (!vendorId) return "No vendor";
    const vendor = vendors.find((v) => v.id === vendorId);
    return vendor ? vendor.name : "Unknown vendor";
  };

  const renderBackdrop = useMemo(
    () => (props: any) => (
      <BottomSheetBackdrop
        {...props}
        appearsOnIndex={0}
        disappearsOnIndex={-1}
        opacity={0.7}
      />
    ),
    []
  );

  if (!item) {
    return (
      <View className="flex-1 justify-center items-center bg-[#212121]">
        <Text className="text-white text-lg">Item not found</Text>
      </View>
    );
  }

  return (
    <View className="flex-1 bg-[#212121]">
      <KeyboardAvoidingView
        behavior={Platform.OS === "ios" ? "padding" : "height"}
        className="flex-1"
      >
        {/* Header */}
        <View className="flex-row items-center justify-between p-2 border-b border-gray-700">
          <TouchableOpacity
            onPress={() => router.back()}
            className="flex-row items-center"
          >
            <ArrowLeft color="#9CA3AF" size={20} />
            <Text className="text-white text-lg ml-2">Back</Text>
          </TouchableOpacity>
          <TouchableOpacity
            onPress={() => setIsEditing(!isEditing)}
            className="flex-row items-center bg-blue-600 px-3 py-1 rounded-lg"
          >
            {isEditing ? (
              <>
                <Save color="white" size={18} />
                <Text className="text-white ml-2">Save</Text>
              </>
            ) : (
              <>
                <Edit color="white" size={18} />
                <Text className="text-white ml-2">Edit</Text>
              </>
            )}
          </TouchableOpacity>
        </View>

        <ScrollView className="flex-1 p-2">
          {/* Item Overview */}
          <View className="bg-[#303030] rounded-xl p-3 mb-2">
            <View className="flex-row items-center justify-between mb-4">
              <Text className="text-lg font-bold text-white">{item.name}</Text>
              <View className="flex-row items-center">
                {item.stockQuantity !== undefined &&
                item.reorderThreshold !== undefined &&
                item.stockQuantity <= item.reorderThreshold ? (
                  <AlertTriangle color="#F87171" size={20} />
                ) : (
                  <CheckCircle color="#10B981" size={20} />
                )}
              </View>
            </View>

            <View className="flex-row justify-between mb-2">
              <Text className="text-gray-300">Current Stock:</Text>
              {((item as any).stockTrackingMode || editStockTrackingMode) ===
              "quantity" ? (
                <Text className="text-white font-semibold">
                  {item.stockQuantity ?? 0} {item.unit}
                </Text>
              ) : ((item as any).stockTrackingMode || editStockTrackingMode) ===
                "in_stock" ? (
                <Text className="text-green-400 font-semibold">In Stock</Text>
              ) : (
                <Text className="text-red-400 font-semibold">Out of Stock</Text>
              )}
            </View>

            {((item as any).stockTrackingMode || editStockTrackingMode) ===
              "quantity" && (
              <View className="flex-row justify-between mb-2">
                <Text className="text-gray-300">Reorder Threshold:</Text>
                <Text className="text-white font-semibold">
                  {item.reorderThreshold || "Not set"}
                </Text>
              </View>
            )}

            <View className="flex-row justify-between mb-2">
              <Text className="text-gray-300">Cost per Unit:</Text>
              <Text className="text-white font-semibold">
                ${item.cost?.toFixed(2) || "0.00"}
              </Text>
            </View>

            <View className="flex-row justify-between mb-2">
              <Text className="text-gray-300">Vendor:</Text>
              <Text className="text-white font-semibold">
                {getVendorName(item.vendorId)}
              </Text>
            </View>

            <View className="flex-row justify-between">
              <Text className="text-gray-300">Category:</Text>
              <Text className="text-white font-semibold">{item.category}</Text>
            </View>
          </View>

          {/* Quick Actions */}
          <View className="bg-[#303030] rounded-xl p-3 mb-2">
            <Text className="text-lg font-bold text-white mb-3">
              Quick Actions
            </Text>
            <View className="flex-row gap-2">
              <TouchableOpacity
                onPress={() => setIsLogUsageModalOpen(true)}
                className="flex-1 bg-red-600 py-2 px-3 rounded-lg flex-row items-center justify-center"
              >
                <Minus color="white" size={18} />
                <Text className="text-white ml-2 font-semibold">Log Usage</Text>
              </TouchableOpacity>

              <TouchableOpacity
                onPress={() => setIsAddStockModalOpen(true)}
                className="flex-1 bg-green-600 py-2 px-3 rounded-lg flex-row items-center justify-center"
              >
                <Plus color="white" size={18} />
                <Text className="text-white ml-2 font-semibold">Add Stock</Text>
              </TouchableOpacity>
            </View>

            <TouchableOpacity
              onPress={() => historySheetRef.current?.expand()}
              className="w-full bg-gray-600 py-2 px-3 rounded-lg flex-row items-center justify-center mt-2"
            >
              <History color="white" size={18} />
              <Text className="text-white ml-2 font-semibold">
                View History
              </Text>
            </TouchableOpacity>
          </View>

          {/* Item Details Form */}
          <View className="bg-[#303030] rounded-xl p-3">
            <Text className="text-lg font-bold text-white mb-3">
              Item Details
            </Text>

            {/* Stock Tracking Options */}
            <View className="mb-4">
              <Text className="text-gray-300 mb-2">Stock Tracking</Text>
              <View className="flex-row gap-2">
                <TouchableOpacity
                  disabled={!isEditing}
                  onPress={() => setEditStockTrackingMode("in_stock")}
