                  <Text className="text-white font-semibold">Delivered At</Text>
                  <Text className="text-white">
                    {new Date(po.deliveryLoggedAt).toLocaleString()}
                  </Text>
                </View>
                {po.discrepancyNotes && (
                  <View className="mb-2">
                    <Text className="text-white font-semibold mb-1">Notes</Text>
