}

import ItemForm from "@/components/menu/ItemForm";
import { useToast } from "@/contexts/ToastContext";
import { useSupabaseClient } from "@/hooks/useSupabaseClient";
import { MenuItemType } from "@/lib/types";
import { MenuService } from "@/services/menuService";
import { useMenuStore } from "@/stores/useMenuStore";
import { useStoreSettingsStore } from "@/stores/useStoreSettingsStore";
import { useRouter } from "expo-router";
import React, { useState } from "react";
import { Alert, View } from "react-native";

const AddMenuItemScreen: React.FC = () => {
  const { addMenuItem, categories } = useMenuStore();
  const { selectedStore } = useStoreSettingsStore();
  const supabase = useSupabaseClient();
  const { show } = useToast();
  const router = useRouter();
  const [isSaving, setIsSaving] = useState(false);

  const handleSubmit = async (
    data: Omit<MenuItemType, "id">
  ): Promise<boolean> => {
    setIsSaving(true);
    try {
      // Validate store selection
      if (!selectedStore) {
        Alert.alert("Error", "No store selected. Please select a store first.");
        return false;
      }

      const merchantId = selectedStore.merchant_id;

      // Create menu item in backend
      const { data: createdItem, error } = await MenuService.createMenuItem(
        supabase,
        {
          merchantId,
          locationId: selectedStore.id,
          name: data.name,
          description: data.description,
          price: data.price,
          cashPrice: data.cashPrice,
          image: data.image,
          mealTypes: data.meal,
          allergens: data.allergens || [],
          availability: data.availability,
          stockTrackingMode: undefined, // TODO: Add field to form
        }
      );

      if (error) {
        console.error("Failed to create menu item:", error);
        show({
          title: "Error",
          message:
            error.message || "Failed to create menu item. Please try again.",
          type: "error",
        });
        return false;
      }

      // Add item to categories if selected (only sync to backend for categories with valid UUIDs)
      const isValidUUID = (id: string) => {
        const uuidRegex =
          /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
        return uuidRegex.test(id);
      };

      if (data.category && data.category.length > 0 && createdItem?.id) {
        const categoryNames = Array.isArray(data.category)
          ? data.category
          : [data.category];
        for (const categoryName of categoryNames) {
          const category = categories.find((c) => c.name === categoryName);
          // Only call backend for categories with valid UUIDs (local categories from backend)
          if (category?.id && isValidUUID(category.id)) {
            await MenuService.addItemToCategory(supabase, {
              categoryId: category.id,
              menuItemId: createdItem.id,
              merchantId,
              displayOrder: 0,
              isFeatured: false,
            });
          }
        }
      }

      // Assign modifier groups if selected
      if (
        data.modifierGroupIds &&
        data.modifierGroupIds.length > 0 &&
        createdItem?.id
      ) {
        for (let i = 0; i < data.modifierGroupIds.length; i++) {
          const modifierId = data.modifierGroupIds[i];
          await MenuService.assignModifierToItem(supabase, {
            menuItemId: createdItem.id,
            modifierGroupId: modifierId,
            displayOrder: i,
          });
        }
      }

      // 4. Save Recipe Ingredients (New)
      if (data.recipe && data.recipe.length > 0 && createdItem?.id) {
        await MenuService.upsertMenuItemRecipe(
          supabase,
          createdItem.id,
          data.recipe.map((r) => ({
            inventoryItemId: r.inventoryItemId,
            quantity: r.quantity,
          }))
        );
      }

      // Also update local store for immediate UI feedback - use backend ID
      addMenuItem({
        ...data,
        id: createdItem?.id,
        location_id: selectedStore.id,
      } as any);

      show({
        title: "Item Created",
        message: `Successfully added "${data.name}" to the menu.`,
        type: "success",
      });
      return true;
    } catch (error) {
      console.error(error);
      show({
        title: "Error",
        message: "An unexpected error occurred. Please try again.",
        type: "error",
      });
      return false;
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <View className="flex-1 bg-[#212121]">
      <ItemForm
        onSubmit={handleSubmit}
        isSaving={isSaving}
        title="Add New Menu Item"
        submitButtonLabel="Save Item"
      />
    </View>
  );
};

export default AddMenuItemScreen;

import UnsavedChangesDialog from "@/components/ui/UnsavedChangesDialog";
import { useToast } from "@/contexts/ToastContext";
import { useSupabaseClient } from "@/hooks/useSupabaseClient";
import { useUnsavedChanges } from "@/hooks/useUnsavedChanges";
import { ModifierOption } from "@/lib/types";
import { MenuService } from "@/services/menuService";
import { useMenuStore } from "@/stores/useMenuStore";
import { useStoreSettingsStore } from "@/stores/useStoreSettingsStore";
import { router, useLocalSearchParams } from "expo-router";
import { ArrowLeft, Plus, Save, Trash2 } from "lucide-react-native";
import React, { useEffect, useRef, useState } from "react";
import {
  Alert,
  KeyboardAvoidingView,
  Modal,
  ScrollView,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";

// Form data interface
interface ModifierFormData {
  name: string;
  type: "required" | "optional";
  selectionType: "single" | "multiple";
  maxSelections?: number;
  description?: string;
  options: ModifierOption[];
}

// Error interface
interface FormErrors {
  name?: string;
  options?: string;
  maxSelections?: string;
}

const AddModifierScreen: React.FC = () => {
  const { addModifierGroup } = useMenuStore();
  const { selectedStore } = useStoreSettingsStore();
  const supabase = useSupabaseClient();
  const { show } = useToast();

  const [formData, setFormData] = useState<ModifierFormData>({
    name: "",
    type: "optional",
    selectionType: "single",
    maxSelections: undefined,
    description: "",
    options: [],
  });

  const [errors, setErrors] = useState<FormErrors>({});
  const [showConfirmation, setShowConfirmation] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const [hasChanges, setHasChanges] = useState(false);
  const hasSavedRef = useRef(false);

  const { isDialogVisible, handleCancel, handleDiscard } = useUnsavedChanges(
    hasChanges && !hasSavedRef.current
  );

  useEffect(() => {
    // Check if the form is different from its initial state
    const isPristine =
      !formData.name.trim() &&
      !formData.description?.trim() &&
      formData.options.length === 0;
    setHasChanges(!isPristine);
  }, [formData]);

  // Handle form validation
  const validateForm = (): boolean => {
    const newErrors: FormErrors = {};

    if (!formData.name.trim()) {
      newErrors.name = "Modifier name is required";
    }

    if (formData.options.length === 0) {
      newErrors.options = "Please add at least one option";
    }

    if (formData.options.some((option) => option.name.trim() === "")) {
      newErrors.options = "Option name is required";
    }

    const hasDefault = formData.options.some((option) => option.isDefault);
    if (
      formData.type === "required" &&
      formData.selectionType === "single" &&
      !hasDefault
    ) {
      newErrors.options = "One option must be set as default for this type.";
    }

    if (
      formData.selectionType === "multiple" &&
      formData.maxSelections &&
      formData.maxSelections < 1
    ) {
      newErrors.maxSelections = "Max selections must be at least 1";
    }

    setErrors(newErrors);

    // Show a single toast for the first error found
    if (Object.keys(newErrors).length > 0) {
      const firstErrorMessage = Object.values(newErrors)[0];
      show({
        title: "Validation Error",
        message:
          firstErrorMessage || "Please review the form for required fields.",
        type: "error",
      });
    }

    return Object.keys(newErrors).length === 0;
  };

  // Handle save
  const handleSave = () => {
    if (!validateForm()) {
      return;
    }
    setShowConfirmation(true);
  };

  const params = useLocalSearchParams<{ returnTab?: string }>();

  const confirmSave = async () => {
    setIsSaving(true);
    setShowConfirmation(false);

    try {
      // Validate store selection
      if (!selectedStore) {
        Alert.alert("Error", "No store selected. Please select a store first.");
        setIsSaving(false);
        return;
      }

      const merchantId = selectedStore.merchant_id;
      const locationId = selectedStore.id;

      // Transform form data to backend format
      const isRequired = formData.type === "required";
      const minSelections = isRequired ? 1 : 0;
      const maxSelections =
        formData.selectionType === "single"
          ? 1
          : formData.maxSelections || null;

      // Create modifier group in backend
      const { data: createdGroup, error } =
        await MenuService.createModifierGroup(supabase, {
          merchantId,
          locationId,
          name: formData.name.trim(),
          description: formData.description?.trim() || undefined,
          isRequired,
          minSelections,
          maxSelections: maxSelections ?? undefined,
        });

      if (error) {
        console.error("Failed to create modifier group:", error);
        show({
          title: "Error",
          message:
            error.message ||
            "Failed to create modifier group. Please try again.",
          type: "error",
        });
        setIsSaving(false);
        return;
      }

      // Create modifier items (options) in backend
      const optionsWithBackendIds = [];
      if (createdGroup?.id && formData.options.length > 0) {
        for (let i = 0; i < formData.options.length; i++) {
          const option = formData.options[i];
          const { data: createdOption, error: itemError } =
            await MenuService.createModifierItem(supabase, {
              modifierGroupId: createdGroup.id,
              name: option.name.trim(),
              priceModifier: option.price,
              displayOrder: i,
              isActive: true,
              isDefault: option.isDefault,
              merchantId: merchantId,
            });

          if (itemError) {
            console.error("Failed to create modifier item:", itemError);
            // Continue creating others, but log error
          }

          optionsWithBackendIds.push({
            ...option,
            name: option.name.trim(),
            // Use backend ID if available, otherwise keep temp ID (though this shouldn't happen on success)
            id: createdOption?.id || option.id,
          });
        }
      }

      // Also update local store for immediate UI feedback
      const modifierGroupData = {
        name: formData.name.trim(),
        type: formData.type,
        selectionType: formData.selectionType,
        maxSelections: formData.maxSelections,
        description: formData.description?.trim() || undefined,
        options: optionsWithBackendIds,
        location_id: locationId,
        id: createdGroup.id,
      };
      addModifierGroup(modifierGroupData);

      show({
        title: "Modifier Group Saved",
        message: `Successfully created "${modifierGroupData.name}".`,
        type: "success",
      });

      hasSavedRef.current = true;
      setHasChanges(false);

      await new Promise((resolve) => setTimeout(resolve, 100)); // Short delay for state update

      const tab =
        typeof params.returnTab === "string" ? params.returnTab : undefined;
      if (tab) {
        router.replace({ pathname: "/menu", params: { tab } });
      } else {
        router.back();
      }
    } catch (error) {
      console.error(error);
      show({
        title: "Save Failed",
        message: "An error occurred while saving. Please try again.",
        type: "error",
      });
    } finally {
      setIsSaving(false);
    }
  };

  // Add new option
  const addOption = () => {
    const newOption: ModifierOption = {
      id: `option_${Date.now()}`,
      name: "",
      price: 0,
      isDefault: false,
    };
    setFormData((prev) => ({
      ...prev,
      options: [...prev.options, newOption],
    }));
  };

  // Update option
  const updateOption = (
    index: number,
    field: keyof ModifierOption,
    value: string | number | boolean
  ) => {
    setFormData((prev) => ({
      ...prev,
      options: prev.options.map((option, i) =>
        i === index ? { ...option, [field]: value } : option
      ),
    }));
  };

  // Remove option
  const removeOption = (index: number) => {
    setFormData((prev) => ({
      ...prev,
      options: prev.options.filter((_, i) => i !== index),
    }));
  };

  // Toggle default selection for an option
  const toggleDefaultOption = (index: number) => {
    setFormData((prev) => {
      const newOptions = [...prev.options];

      // If single choice, unset all other defaults first
      if (prev.selectionType === "single") {
        newOptions.forEach((option, i) => {
          if (i !== index) {
            option.isDefault = false;
          }
        });
      }

      // Toggle the selected option's default status
      newOptions[index].isDefault = !newOptions[index].isDefault;

      return {
        ...prev,
        options: newOptions,
      };
    });
  };

  return (
    <KeyboardAvoidingView className="flex-1 bg-[#212121]" behavior="padding">
      {/* Header */}
      <View className="flex-row items-center justify-between p-4 border-b border-gray-700 bg-[#303030]">
        <TouchableOpacity
          onPress={() => router.back()}
          className="flex-row items-center"
        >
          <ArrowLeft size={20} color="#9CA3AF" />
          <Text className="text-xl text-white font-medium ml-1.5">
            Back to Modifiers
          </Text>
        </TouchableOpacity>

        <TouchableOpacity
          onPress={handleSave}
          disabled={isSaving}
          className="flex-row items-center bg-blue-600 px-4 py-2 rounded-lg"
        >
          <Save size={20} color="white" />
          <Text className="text-xl text-white font-medium ml-1.5">
            {isSaving ? "Saving..." : "Save Modifier"}
          </Text>
        </TouchableOpacity>
      </View>

      <ScrollView className="flex-1 p-4">
        <Text className="text-2xl font-bold text-white mb-4">
          Add Modifier Group
        </Text>

        {/* Modifier Name */}
        <View className="mb-4">
          <Text className="text-xl font-semibold text-white mb-2">
            Modifier Name
          </Text>
          <TextInput
            className="bg-[#303030] border border-gray-600 rounded-lg px-4 py-3 text-lg text-white h-16"
            placeholder="e.g., Size, Toppings, Sauce"
            placeholderTextColor="#9CA3AF"
            value={formData.name}
            onChangeText={(text) =>
              setFormData((prev) => ({ ...prev, name: text }))
            }
          />
          {errors.name && (
            <Text className="text-base text-red-400 mt-1">{errors.name}</Text>
          )}
        </View>

        {/* Modifier Type */}
        <View className="mb-4">
          <Text className="text-xl font-semibold text-white mb-2">Type</Text>
          <View className="flex-row gap-3">
            <TouchableOpacity
              onPress={() =>
                setFormData((prev) => ({ ...prev, type: "optional" }))
              }
              className={`flex-1 px-4 py-3 rounded-lg border ${
                formData.type === "optional"
                  ? "bg-blue-600 border-blue-500"
                  : "bg-[#303030] border-gray-600"
              }`}
            >
              <Text
                className={`text-xl font-medium text-center ${
                  formData.type === "optional" ? "text-white" : "text-gray-300"
                }`}
              >
                Optional
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              onPress={() =>
                setFormData((prev) => ({ ...prev, type: "required" }))
              }
              className={`flex-1 px-4 py-3 rounded-lg border ${
                formData.type === "required"
                  ? "bg-red-600 border-red-500"
                  : "bg-[#303030] border-gray-600"
              }`}
            >
              <Text
                className={`text-xl font-medium text-center ${
                  formData.type === "required" ? "text-white" : "text-gray-300"
                }`}
              >
                Required
              </Text>
            </TouchableOpacity>
          </View>
        </View>

        {/* Selection Type */}
        <View className="mb-4">
          <Text className="text-xl font-semibold text-white mb-2">
            Selection Type
          </Text>
          <View className="flex-row gap-3">
            <TouchableOpacity
              onPress={() =>
                setFormData((prev) => ({ ...prev, selectionType: "single" }))
              }
              className={`flex-1 px-4 py-3 rounded-lg border ${
                formData.selectionType === "single"
                  ? "bg-green-600 border-green-500"
                  : "bg-[#303030] border-gray-600"
              }`}
            >
              <Text
                className={`text-xl font-medium text-center ${
                  formData.selectionType === "single"
                    ? "text-white"
                    : "text-gray-300"
                }`}
              >
                Single Choice
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              onPress={() =>
                setFormData((prev) => ({ ...prev, selectionType: "multiple" }))
              }
              className={`flex-1 px-4 py-3 rounded-lg border ${
                formData.selectionType === "multiple"
                  ? "bg-green-600 border-green-500"
                  : "bg-[#303030] border-gray-600"
              }`}
            >
              <Text
                className={`text-xl font-medium text-center ${
                  formData.selectionType === "multiple"
                    ? "text-white"
                    : "text-gray-300"
                }`}
              >
                Multiple Choice
              </Text>
            </TouchableOpacity>
          </View>
        </View>

        {formData.selectionType === "multiple" && (
          <View className="mb-4">
            <Text className="text-xl font-semibold text-white mb-2">
              Max Selections (Optional)
            </Text>
            <TextInput
              className="bg-[#303030] border border-gray-600 rounded-lg px-4 py-3 text-lg text-white h-16"
              placeholder="Leave empty for unlimited"
              placeholderTextColor="#9CA3AF"
              value={formData.maxSelections?.toString() || ""}
              onChangeText={(text) =>
                setFormData((prev) => ({
                  ...prev,
                  maxSelections: text ? parseInt(text) : undefined,
                }))
              }
              keyboardType="numeric"
            />
            {errors.maxSelections && (
              <Text className="text-base text-red-400 mt-1">
                {errors.maxSelections}
              </Text>
            )}
          </View>
        )}

        {/* Description */}
        <View className="mb-4">
          <Text className="text-xl font-semibold text-white mb-2">
            Description (Optional)
          </Text>
          <TextInput
            className="bg-[#303030] border border-gray-600 rounded-lg px-4 py-3 text-lg text-white h-16"
            placeholder="e.g., Choose up to 3 toppings"
            placeholderTextColor="#9CA3AF"
            value={formData.description}
            onChangeText={(text) =>
              setFormData((prev) => ({ ...prev, description: text }))
            }
            multiline
            numberOfLines={2}
          />
        </View>

        {/* Options */}
        <View className="mb-8">
          <View className="flex-row items-center justify-between mb-3">
            <View>
              <Text className="text-xl font-semibold text-white">Options</Text>
              <Text className="text-base text-gray-400">
                {formData.selectionType === "single"
                  ? "Set one as default"
                  : "Set multiple as default"}
