            }`}
          >
            <Text
              className={`text-lg font-medium ${
                menu.isActive && isAvailable ? "text-green-400" : "text-red-400"
              }`}
            >
              {menu.isActive
                ? isAvailable
                  ? "Available Now"
                  : "Unavailable Now"
                : "Inactive"}
            </Text>
          </View>
        </View>

        <View className="flex-row items-center gap-2">
          <TouchableOpacity
            onPress={() => onToggleMenuActive(menu.id)}
            disabled={!isEditable}
            className={`p-2 bg-[#212121] rounded border ${
