                  ))}
                  {modifierGroup.items.length > 3 && (
                    <View className="bg-[#212121] p-3 rounded border border-gray-700 items-center">
                      <Text className="text-lg text-gray-400">
                        +{modifierGroup.items.length - 3} more items use this
                        modifier
                      </Text>
                    </View>
                  )}
                </View>
              </View>
            </View>
          ))}
        </View>
      </ScrollView>
    </View>
  );

  const renderSchedulesContent = () => (
    <View className="flex-1 p-4 bg-[#212121]">
      <View className="flex-row items-center justify-between mb-4">
        <Text className="text-2xl font-bold text-white">Schedules</Text>
        <View className="flex-row bg-[#303030] border border-gray-600 rounded-lg p-1">
          <TouchableOpacity
            onPress={() => setScheduleViewType("menus")}
            className={`px-4 py-2 rounded-md ${
              scheduleViewType === "menus" ? "bg-blue-600" : ""
            }`}
          >
            <Text
              className={`text-lg font-medium ${
                scheduleViewType === "menus" ? "text-white" : "text-gray-300"
              }`}
            >
              Menus
            </Text>
          </TouchableOpacity>
          <TouchableOpacity
            onPress={() => setScheduleViewType("categories")}
            className={`px-4 py-2 rounded-md ${
              scheduleViewType === "categories" ? "bg-blue-600" : ""
            }`}
          >
            <Text
              className={`text-lg font-medium ${
                scheduleViewType === "categories"
                  ? "text-white"
                  : "text-gray-300"
              }`}
            >
              Categories
            </Text>
          </TouchableOpacity>
        </View>
      </View>
      <ScrollView className="flex-1">
        <View className="gap-3">
          {scheduleViewType === "menus"
            ? menus.map((menu) => (
                <View
                  key={menu.id}
                  className="bg-[#303030] rounded-lg border border-gray-700 p-4"
                >
                  <View className="flex-row items-center justify-between mb-1.5">
                    <Text className="text-xl text-white font-semibold">
                      {menu.name}
                    </Text>
                    <View
                      className={`px-2.5 py-1.5 rounded-full ${
                        menu.isActive && menu.isAvailableNow
                          ? "bg-green-900/30 border border-green-500"
                          : "bg-red-900/30 border border-red-500"
                      }`}
                    >
                      <Text
                        className={`text-lg ${
                          menu.isActive && menu.isAvailableNow
                            ? "text-green-400"
                            : "text-red-400"
                        }`}
                      >
                        {menu.isActive
                          ? menu.isAvailableNow
                            ? "Available Now"
                            : "Unavailable Now"
                          : "Inactive"}
                      </Text>
                    </View>
                  </View>
                  {(menu.schedules ?? []).length === 0 ? (
                    <View>
                      <Text className="text-lg text-gray-400">
                        Always available (no schedule rules)
                      </Text>
                    </View>
                  ) : (
                    <View className="gap-1.5">
                      {menu.schedules!.map((r) => (
                        <View
                          key={r.id}
                          className="flex-row justify-between bg-[#212121] p-3 rounded border border-gray-700"
                        >
                          <Text className="text-lg text-gray-200">
                            {r.name || r.id}
                          </Text>
                          <Text className="text-lg text-gray-400">
                            {(r.days || []).join(", ")} •{" "}
                            {formatTimeDisplay(r.startTime)} -{" "}
                            {formatTimeDisplay(r.endTime)}
                          </Text>
                        </View>
                      ))}
                    </View>
                  )}
                  <View className="mt-2.5">
                    <TouchableOpacity
                      onPress={() =>
                        router.push(`/menu/edit-menu?id=${menu.id}`)
                      }
                      className="self-start px-3 py-2 rounded-lg bg-blue-600"
                    >
                      <Text className="text-lg text-white">Edit Schedules</Text>
                    </TouchableOpacity>
                  </View>
                </View>
              ))
            : storeCategories.map((category) => (
                <View
                  key={category.id}
                  className="bg-[#303030] rounded-lg border border-gray-700 p-4"
                >
                  <View className="flex-row items-center justify-between mb-1.5">
                    <Text className="text-xl text-white font-semibold">
                      {category.name}
                    </Text>
                    <View
                      className={`px-2.5 py-1.5 rounded-full ${
                        category.isActive &&
                        isCategoryAvailableNow(category.name)
                          ? "bg-green-900/30 border border-green-500"
                          : "bg-red-900/30 border border-red-500"
                      }`}
                    >
                      <Text
                        className={`text-lg ${
                          category.isActive &&
                          isCategoryAvailableNow(category.name)
                            ? "text-green-400"
                            : "text-red-400"
                        }`}
                      >
                        {category.isActive
                          ? isCategoryAvailableNow(category.name)
                            ? "Available Now"
                            : "Unavailable Now"
                          : "Inactive"}
                      </Text>
                    </View>
                  </View>
                  {(category.schedules ?? []).length === 0 ? (
                    <View>
                      <Text className="text-lg text-gray-400">
                        Always available (no schedule rules)
                      </Text>
                    </View>
                  ) : (
                    <View className="gap-1.5">
                      {category.schedules!.map((r) => (
                        <View
                          key={r.id}
                          className="flex-row justify-between bg-[#212121] p-3 rounded border border-gray-700"
                        >
                          <Text className="text-lg text-gray-200">
                            {r.name || r.id}
                          </Text>
                          <Text className="text-lg text-gray-400">
                            {(r.days || []).join(", ")} •{" "}
                            {formatTimeDisplay(r.startTime)} -{" "}
                            {formatTimeDisplay(r.endTime)}
                          </Text>
                        </View>
                      ))}
                    </View>
                  )}
                  <View className="mt-2.5">
                    <TouchableOpacity
                      onPress={() =>
                        router.push(`/menu/edit-category?id=${category.id}`)
                      }
                      className="self-start px-3 py-2 rounded-lg bg-blue-600"
                    >
                      <Text className="text-lg text-white">Edit Schedules</Text>
                    </TouchableOpacity>
                  </View>
                </View>
              ))}
        </View>
      </ScrollView>
    </View>
  );

  const renderContent = () => {
    switch (activeTab) {
      case "menus":
        return renderMenusContent();
      case "categories":
        return renderCategoriesContent();
      case "items":
        return renderItemsContent();
      case "modifiers":
        return renderModifiersContent();
      case "schedules":
        return renderSchedulesContent();
      default:
        return null;
    }
  };

  return (
    <View className="flex-1 bg-[#212121]">
      {renderContent()}
      <PriceEditBottomSheet
        ref={priceEditRef}
        onSave={(itemId, newPrice) => {
          // Refresh menu data after price update
          // The price will be reflected on next sync
          console.log(`Price updated for item ${itemId}: $${newPrice}`);
        }}
        onReset={(itemId) => {
          console.log(`Price reset for item ${itemId}`);
        }}
      />

      {/* Delete Confirmation Modal */}
      <ConfirmationModal
        isOpen={showDeleteModal}
        onClose={() => {
          setShowDeleteModal(false);
          setItemToDelete(null);
        }}
        onConfirm={confirmDeleteItem}
        title="Delete Item"
        description={`Are you sure you want to delete '${itemToDelete?.name}'?`}
        confirmText="Delete"
        variant="destructive"
      />
    </View>
  );
};

// Menu Item Card Component
interface MenuItemCardProps {
  item: MenuItemType;
  onEdit: (item: MenuItemType) => void;
  onDelete: (item: MenuItemType) => void;
  onToggleAvailability: (id: string) => void;
  onPriceEdit?: (item: MenuItemType) => void;
  editDisabled?: boolean;
}

const MenuItemCard: React.FC<MenuItemCardProps> = ({
  item,
  onEdit,
  onDelete,
  onToggleAvailability,
  onPriceEdit,
  editDisabled = false,
}) => {
  return (
    <TouchableOpacity
      onPress={() => onPriceEdit?.(item)}
      activeOpacity={onPriceEdit ? 0.7 : 1}
      className="bg-[#303030] max-h-48 rounded-lg border border-gray-700 p-3"
    >
      <View className="flex-row items-start gap-3">
        <View className="h-full aspect-square rounded-lg border border-gray-600">
          {getImageSource(item.image) ? (
            <Image
              source={
                typeof getImageSource(item.image) === "string"
                  ? MENU_IMAGE_MAP[item.image as keyof typeof MENU_IMAGE_MAP]
                  : getImageSource(item.image)
              }
              className="w-full h-full rounded-lg object-cover"
            />
          ) : (
            <View className="w-full h-full rounded-lg bg-gray-100 items-center justify-center">
              <Utensils color="#9ca3af" size={24} />
            </View>
          )}
        </View>
        <View className="flex-1">
          <View className="flex-row items-center gap-2 mb-1.5">
            <Text className="text-lg font-semibold text-white">
              {item.name}
            </Text>
          </View>

          {item.description && (
            <Text className="text-gray-300 text-xs mb-1.5 flex-1">
              {item.description.length > 40
                ? item.description.substring(0, 40) + "..."
                : item.description}
            </Text>
          )}

          <View className="flex-row gap-4">
            <Text className="text-xs text-gray-400">
              Price: ${item.price.toFixed(2)}
            </Text>
          </View>

          {item.customPricing && item.customPricing.length > 0 && (
            <View className="mt-1.5">
              <Text className="text-[10px] text-yellow-400 mb-1">
                Custom Pricing:{" "}
                {item.customPricing.filter((p) => p.isActive).length} active
                rules
              </Text>
              <View className="flex-row flex-wrap gap-1">
                {item.customPricing.slice(0, 2).map((pricing) => (
                  <View
                    key={pricing.id}
                    className="bg-yellow-900/30 border border-yellow-500 px-1.5 py-0.5 rounded"
                  >
                    <Text className="text-[10px] text-yellow-400">
                      {pricing.categoryName}: ${pricing.price.toFixed(2)}
                    </Text>
                  </View>
                ))}
                {item.customPricing.length > 2 && (
                  <View className="bg-gray-600/30 border border-gray-500 px-1.5 py-0.5 rounded">
                    <Text className="text-[10px] text-gray-400">
                      +{item.customPricing.length - 2} more
                    </Text>
                  </View>
                )}
              </View>
            </View>
          )}

          <View className="flex-row gap-2 mt-1.5">
            {item.meal.map((meal, index) => (
              <View
                key={index}
                className="bg-blue-900/30 border border-blue-500 px-1.5 py-0.5 rounded"
              >
                <Text className="text-[10px] text-blue-400">{meal}</Text>
              </View>
            ))}
          </View>
        </View>

        <View className="flex-col gap-y-1.5 ml-2">
          <TouchableOpacity
            onPress={editDisabled ? undefined : () => onEdit(item)}
            disabled={editDisabled}
            className={`p-1.5 rounded ${
              editDisabled
                ? "bg-gray-600/30 border border-gray-600 opacity-50"
                : "bg-blue-900/30 border border-blue-500"
            }`}
          >
            <Edit size={20} color={editDisabled ? "#6B7280" : "#60A5FA"} />
          </TouchableOpacity>

          <TouchableOpacity
            onPress={editDisabled ? undefined : () => onDelete(item)}
            disabled={editDisabled}
            className={`p-1.5 rounded ${
              editDisabled
                ? "bg-gray-600/30 border border-gray-600 opacity-50"
                : "bg-red-900/30 border border-red-500"
            }`}
          >
            <Trash2 size={20} color={editDisabled ? "#6B7280" : "#F87171"} />
          </TouchableOpacity>
          <TouchableOpacity
            onPress={
              editDisabled ? undefined : () => onToggleAvailability(item.id)
            }
            disabled={editDisabled}
            className={`p-1.5 ${editDisabled ? "opacity-50" : ""}`}
          >
            {item.availability !== false ? (
              <Eye size={20} color={editDisabled ? "#6B7280" : "#10B981"} />
            ) : (
              <EyeOff size={20} color={editDisabled ? "#6B7280" : "#EF4444"} />
            )}
          </TouchableOpacity>
        </View>
      </View>
    </TouchableOpacity>
  );
};

export default MenuPage;

import AttachedModifierPanel from "@/components/bill/AttachedModifierPanel";
import BillSection from "@/components/bill/BillSection";
import MoreOptionsBottomSheet from "@/components/bill/MoreOptionsBottomSheet";
import MenuSection from "@/components/menu/MenuSection";
import OrderBadge from "@/components/order/OrderBadge";
import OrderLineItemsModal from "@/components/order/OrderLineItemsModal";
import OrderLineSection from "@/components/order/OrderLineSection";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/contexts/ToastContext"; // New Import
import { OrderProfile } from "@/lib/types";
import { useOrderStore } from "@/stores/useOrderStore";
import { BottomSheetMethods } from "@gorhom/bottom-sheet/lib/typescript/types";
import React, { useEffect, useMemo, useRef, useState } from "react";
import { FlatList, Text, View } from "react-native";

const OrderProcessing = () => {
  // FIXED: Use individual selectors to prevent subscribing to entire ordersById
  const activeOrderId = useOrderStore((s) => s.activeOrderId);
  const setActiveOrder = useOrderStore((s) => s.setActiveOrder);
  const startNewOrder = useOrderStore((s) => s.startNewOrder);
  const updateOrderStatus = useOrderStore((s) => s.updateOrderStatus);
  const markAllItemsAsReady = useOrderStore((s) => s.markAllItemsAsReady);
  const archiveOrder = useOrderStore((s) => s.archiveOrder);

  // FIXED: Subscribe to orderIds (stable array) and lookup orders when needed
  // This prevents infinite loops from Object.values() creating new arrays
  const orderIds = useOrderStore((s) => s.orderIds);
  const ordersById = useOrderStore((s) => s.ordersById);

  // Compute orders array from IDs - only recalculates when orderIds or ordersById change
  const orders = useMemo(
    () => orderIds.map((id) => ordersById[id]).filter(Boolean),
    [orderIds, ordersById]
  );

  const [isAccordionOpen, setIsAccordionOpen] = useState(false);
  const [isItemsModalOpen, setItemsModalOpen] = useState(false);
  const [selectedOrderId, setSelectedOrderId] = useState<string | null>(null);
  const moreOptionsSheetRef = useRef<BottomSheetMethods>(null);
  const discountSheetRef = useRef<BottomSheetMethods>(null);

  useEffect(() => {
    // OPTIMIZED: Use memoized find helpers with O(1) lookup when possible
    // Find an existing empty draft order (not assigned to table, no items)
    const emptyDraft = orders.find(
      (o) =>
        o.service_location_id === null &&
        o.order_status === "draft" &&
        o.items.length === 0
    );

    // Find any global draft order (not assigned to table)
    const globalDraft = orders.find(
      (o) => o.service_location_id === null && o.order_status === "draft"
    );

    if (!activeOrderId) {
      if (emptyDraft) {
        // Reuse existing empty draft
        setActiveOrder(emptyDraft.id);
      } else if (globalDraft) {
        // Use global draft with items
        setActiveOrder(globalDraft.id);
      } else {
        // Create new draft only if none exist
        const newOrder = startNewOrder();
        setActiveOrder(newOrder.id);
      }
      return;
    }

    // If activeOrderId exists, do not override it here. This allows "Retrieve to Pay"
    // to set a non-global order as active without being reset by this effect.
    // OPTIMIZED: Use O(1) lookup instead of orders.find()
    const currentActive = ordersById[activeOrderId];
    if (!currentActive) {
      if (emptyDraft) {
        setActiveOrder(emptyDraft.id);
      } else if (globalDraft) {
        setActiveOrder(globalDraft.id);
      } else {
        const newOrder = startNewOrder();
        setActiveOrder(newOrder.id);
      }
    }
  }, [orders, activeOrderId, ordersById, setActiveOrder, startNewOrder]);

  // State to hold the orders that are actually displayed
  const filteredOrders = useMemo(() => {
    // Show orders that are in a "kitchen" state (preparing) or unpaid
    // EXCLUDE Dine In orders - they belong on Tables view
    const kitchenOrders = orders.filter(
      (o) =>
        // Exclude Dine In orders entirely
        o.order_type !== "Dine In" &&
        o.order_type !== "dine_in" &&
        // Condition 1: Any "preparing" order with items (Takeaway, Delivery only)
        ((o.order_status === "preparing" && o.items.length > 0) ||
          // Condition 2: Unpaid orders that need payment
          ((o.paid_status === "Unpaid" || o.paid_status === "Pending" || o.paid_status === "Partial") &&
            o.order_status !== "completed" &&
            o.order_status !== "draft" &&
            o.order_status !== "void"))
    );

    return kitchenOrders;
  }, [orders]);

  const reversedFilteredOrders = useMemo(() => {
    return filteredOrders.slice().reverse();
  }, [filteredOrders]);

  const handleViewItems = (orderId: string) => {
    setSelectedOrderId(orderId);
    setItemsModalOpen(true);
  };

  const handleMarkReady = (order: OrderProfile) => {
    // First, mark the order as ready
    markAllItemsAsReady(order.id);
    console.log("we are readying", order.order_type, order.paid_status);

    // Then, check if it's a Takeaway order and archive it
    // Note: archiveOrder now handles inventory deduction automatically
    if (order.order_type === "Takeaway" && order.paid_status === "Paid") {
      // A small delay can improve UX, ensuring the user sees the status change before it disappears.
      setTimeout(() => {
        archiveOrder(order.id);
      }, 500); // 0.5 second delay
    }
  };

  const handleRetrieve = (orderId: string) => {
    setActiveOrder(orderId);
  };

  // Placeholder functions for MoreOptionsBottomSheet
  const { show } = useToast();

  const handleCloseCheck = () => {
    show({
      title: "Close Check",
      message:
        "Close Check functionality for Order Processing not yet implemented.",
      type: "success",
    });
  };

  const handleApplyDiscount = () => {
    show({
      title: "Apply Discount",
      message:
        "Apply Discount functionality for Order Processing not yet implemented.",
      type: "success",
    });
  };

  const handleApplyVoucher = () => {
    show({
      title: "Apply Voucher",
      message:
        "Apply Voucher functionality for Order Processing not yet implemented.",
      type: "success",
    });
  };

  return (
    <View className="flex-1 flex-col bg-[#212121]">
      {/* AttachedModifierPanel - Renders over menu area for inline editing */}
      {/* <AttachedModifierPanel /> */}

      <View className="flex-1 flex-row">
        <BillSection
          moreOptionsSheetRef={
            moreOptionsSheetRef as React.RefObject<BottomSheetMethods>
          }
          discountSheetRef={
            discountSheetRef as React.RefObject<BottomSheetMethods>
          }
        />

        <View className="flex-1 py-4 px-2 pt-0 bg-[#323232] rounded-tl-3xl ">
          <Accordion
            type="single"
            collapsible
            onValueChange={(value: string | undefined) =>
              setIsAccordionOpen(!!value)
            }
          >
            <AccordionItem value="orders">
              <AccordionTrigger className="py-3">
                <View className="flex-row items-center gap-x-2">
                  <Text className="text-2xl font-bold text-white">
                    Order Line
                  </Text>
                  {filteredOrders?.length > 0 && (
                    <Badge className="ml-2 bg-blue-600 rounded-md justify-center items-center p-1 h-8 w-8">
                      <Text className="text-base font-bold text-white">
                        {filteredOrders.length}
                      </Text>
                    </Badge>
                  )}
                </View>
              </AccordionTrigger>
              <AccordionContent>
                <OrderLineSection />
              </AccordionContent>
            </AccordionItem>
          </Accordion>

          <View
            className={
              !isAccordionOpen && filteredOrders.length > 0
                ? "opacity-100"
                : "opacity-0"
            }
            style={
              !isAccordionOpen && filteredOrders.length > 0
                ? { height: "auto" }
                : { height: 0 }
            }
          >
            <FlatList
              horizontal
              data={reversedFilteredOrders}
              keyExtractor={(item) => item.id}
              className="mt-2 max-h-16" // Adjusted height
              contentContainerStyle={{ paddingHorizontal: 4, gap: 8 }}
              showsHorizontalScrollIndicator={false}
              renderItem={({ item }) => (
                <OrderBadge
                  order={item}
                  onMarkReady={() => handleMarkReady(item)}
                  onViewItems={() => handleViewItems(item.id)}
                  onRetrieve={() => handleRetrieve(item.id)}
                />
              )}
            />
          </View>

          <MenuSection />
        </View>
      </View>
      <MoreOptionsBottomSheet
        ref={moreOptionsSheetRef as React.RefObject<BottomSheetMethods>}
        discountSheetRef={
          discountSheetRef as React.RefObject<BottomSheetMethods>
        }
      />

      <OrderLineItemsModal
        isOpen={isItemsModalOpen}
        onClose={() => setItemsModalOpen(false)}
        orderId={selectedOrderId}
      />
    </View>
  );
};

export default OrderProcessing;

