                            title: "Warning",
                            message: "Menu item not found for this order item. Modifier replacement may not work.",
                            type: "error",
                        });
                    }
                } else {
                    setSelectedOrderItemMenuItem(null);
                    setReplaceModifierSelections({});
                }

