const ScheduleDetailScreen = () => {
  const { periodId, applyTemplateId } = useLocalSearchParams();
  const {
    schedulePeriods,
    weeklySchedules,
    ptoRequests,
    swapRequests,
    dropRequests,
  } = useScheduleStore();
  const { templates } = useScheduleTemplateStore(); // Get templates

  const approvedPtoRequests = useMemo(
    () => ptoRequests.filter((r) => r.status === "approved"),
    [ptoRequests]
  );

  const pendingPtoRequestsCount = useMemo(
    () => ptoRequests.filter((r) => r.status === "pending").length,
    [ptoRequests]
  );

  const pendingSwapRequestsCount = useMemo(
    () =>
      swapRequests.filter(
        (r) => r.status === "pending-manager" || r.status === "pending-peer"
      ).length,
    [swapRequests]
  );

  const pendingDropRequestsCount = useMemo(
    () => dropRequests.filter((r) => r.status === "pending").length,
    [dropRequests]
  );

  const currentSchedule = useMemo(() => {
    const period = schedulePeriods.find((p) => p.id === periodId);
    if (period) return { schedule: period, type: "period" as const };
    const weekly = weeklySchedules.find((w) => w.id === periodId);

    if (weekly) return { schedule: weekly, type: "week" as const };
    return null;
  }, [periodId, schedulePeriods, weeklySchedules]);

  if (!currentSchedule) {
    return (
      <Text className="text-white">
        Loading schedule or schedule not found...
      </Text>
    );
  }

  const initialTemplateId = Array.isArray(applyTemplateId)
    ? applyTemplateId[0]
    : applyTemplateId;

  return (
    <ScheduleDetail
      currentSchedule={currentSchedule}
      approvedPtoRequests={approvedPtoRequests}
      pendingSwapRequestsCount={pendingSwapRequestsCount}
      pendingPtoRequestsCount={pendingPtoRequestsCount}
      pendingDropRequestsCount={pendingDropRequestsCount}
      applyTemplateId={initialTemplateId}
    />
  );
};

export default ScheduleDetailScreen;

import EditWeeklyScheduleModal from "@/components/scheduling/EditWeeklyScheduleModal";
import PeriodWizard, { PeriodData } from "@/components/scheduling/PeriodWizard";
import QuickScheduleModal from "@/components/scheduling/QuickScheduleModal";
import SchedulePeriodCard from "@/components/scheduling/SchedulePeriodCard";
import WeeklyScheduleCard from "@/components/scheduling/WeeklyScheduleCard";
import ConfirmationModal from "@/components/settings/reset-application/ConfirmationModal";
import { SchedulePeriod, WeeklySchedule } from "@/lib/types";
import { useScheduleStore } from "@/stores/useScheduleStore";
import { addDays, format } from "date-fns";
import { useRouter } from "expo-router";
import { Plus } from "lucide-react-native";
import React, { useEffect, useMemo, useState } from "react";
import { FlatList, Text, TouchableOpacity, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

const ScheduleManagerDashboard = () => {
  const router = useRouter();
  const {
    getDashboardSchedulePeriods,
    getDashboardWeeklySchedules,
    addWeeklySchedule,
    addSchedulePeriod,
    updateSchedulePeriod,
    updateWeeklySchedule,
    findOrCreateDraft,
    compareSchedules,
    discardDraft,
    deleteSchedule, // Added deleteSchedule
    schedulePeriods: allSchedulePeriods,
    weeklySchedules: allWeeklySchedules,
  } = useScheduleStore();
  const [isWizardOpen, setWizardOpen] = useState(false);
  const [editingPeriod, setEditingPeriod] = useState<PeriodData | null>(null);
  const [isQuickScheduleModalOpen, setIsQuickScheduleModalOpen] =
    useState(false);
  const [isEditWeeklyModalOpen, setIsEditWeeklyModalOpen] = useState(false);
  const [editingWeeklySchedule, setEditingWeeklySchedule] =
    useState<WeeklySchedule | null>(null);

  // State for delete confirmation
  const [isDeleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
  const [deletingSchedule, setDeletingSchedule] = useState<{
    id: string;
    type: "period" | "week";
  } | null>(null);

  useEffect(() => {
    const allSchedules = [...allSchedulePeriods, ...allWeeklySchedules];
    const draftEdits = allSchedules.filter((s) => s.status === "draft-edit");

    draftEdits.forEach((draft) => {
      if (draft.originalScheduleId) {
        const { added, updated, removed } = compareSchedules(
          draft.originalScheduleId,
          draft.id
        );
        if (added === 0 && updated === 0 && removed === 0) {
          discardDraft(draft.id, (draft as any).type);
        }
      }
    });
  }, []);

  const schedulePeriods = useMemo(
    () => getDashboardSchedulePeriods(),
    [getDashboardSchedulePeriods, allSchedulePeriods]
  );
  const weeklySchedules = useMemo(
    () => getDashboardWeeklySchedules(),
    [getDashboardWeeklySchedules, allWeeklySchedules]
  );

  const handleAddNew = () => {
    setEditingPeriod(null);
    setWizardOpen(true);
  };

  const handleEdit = (period: PeriodData) => {
    setEditingPeriod(period);
    setWizardOpen(true);
  };

  const handleWizardComplete = (data: PeriodData) => {
    if (editingPeriod) {
      updateSchedulePeriod(editingPeriod.id!, data);
    } else {
      addSchedulePeriod(
        data as Omit<
          SchedulePeriod,
          "id" | "createdAt" | "updatedAt" | "shifts"
        >
      );
    }
    setWizardOpen(false);
    setEditingPeriod(null);
  };

  const handlePressSchedule = (schedule: SchedulePeriod | WeeklySchedule) => {
    if (schedule.status === "draft" || schedule.status === "draft-edit") {
      router.push(`/scheduling/${schedule.id}`);
    } else {
      const draftId = findOrCreateDraft(schedule.id, (schedule as any).type);
      router.push(`/scheduling/${draftId}`);
    }
  };

  const handleCreateWeeklySchedule = (startDate: string) => {
    const endDate = format(addDays(new Date(startDate), 6), "yyyy-MM-dd");
    const name = `Week of ${format(new Date(startDate), "MMM dd")} - ${format(
      new Date(endDate),
      "MMM dd, yyyy"
    )}`;

    const newWeeklySchedule: Omit<
      WeeklySchedule,
      "id" | "createdAt" | "updatedAt" | "shifts"
    > = {
      name,
      startDate,
      endDate,
      status: "draft",
      createdBy: "Manager",
      type: "weekly",
    };

    const newId = addWeeklySchedule(newWeeklySchedule);
    router.push(`/scheduling/${newId}`);
    setIsQuickScheduleModalOpen(false);
  };

  const handleEditWeekly = (schedule: WeeklySchedule) => {
    setEditingWeeklySchedule(schedule);
    setIsEditWeeklyModalOpen(true);
  };

  const handleUpdateWeeklySchedule = (startDate: string) => {
    if (editingWeeklySchedule) {
      const endDate = format(addDays(new Date(startDate), 6), "yyyy-MM-dd");
      const name = `Week of ${format(new Date(startDate), "MMM dd")} - ${format(new Date(endDate), "MMM dd, yyyy")}`;
      updateWeeklySchedule(editingWeeklySchedule.id, {
        startDate,
        endDate,
        name,
      });
      setIsEditWeeklyModalOpen(false);
      setEditingWeeklySchedule(null);
    }
  };

  // Delete Handlers
  const handleDeletePress = (
    scheduleId: string,
    scheduleType: "period" | "week"
  ) => {
    setDeletingSchedule({ id: scheduleId, type: scheduleType });
    setDeleteConfirmOpen(true);
  };

  const confirmDelete = () => {
    if (deletingSchedule) {
      deleteSchedule(deletingSchedule.id, deletingSchedule.type);
    }
    setDeleteConfirmOpen(false);
    setDeletingSchedule(null);
  };

  return (
    <SafeAreaView edges={["top"]} className="flex-1 bg-[#212121]">
      <View className="p-4 flex-1">
        {/* Header */}
        <View className="flex-row items-center justify-between mb-6">
          <Text className="text-2xl font-bold text-white">
            Schedule Manager
          </Text>
          <View className="flex-row items-center gap-2">
            <TouchableOpacity
              onPress={() => setIsQuickScheduleModalOpen(true)}
              className="flex-row items-center gap-2 px-4 py-2 bg-blue-600 rounded-xl"
            >
              <Plus size={18} color="#FFFFFF" />
              <Text className="text-white font-bold">New Week</Text>
            </TouchableOpacity>
            <TouchableOpacity
              onPress={handleAddNew}
              className="flex-row items-center gap-2 px-4 py-2 bg-blue-600 rounded-xl"
            >
              <Plus size={18} color="#FFFFFF" />
              <Text className="text-white font-bold">New Period</Text>
            </TouchableOpacity>
          </View>
        </View>

        {/* Schedule Periods List (Top Section) */}
        <View className="mb-6">
          <Text className="text-xl font-bold text-white mb-4">
            Schedule Periods
          </Text>
          <FlatList
            horizontal
            data={schedulePeriods}
            keyExtractor={(item) => item.id!}
            renderItem={({ item }) => (
              <SchedulePeriodCard
                period={item as PeriodData} // Cast to PeriodData for now, will update PeriodWizard later
                onEdit={() => handleEdit(item as PeriodData)}
                onDelete={() => handleDeletePress(item.id!, "period")} // Added onDelete
                onPressSchedule={() => handlePressSchedule(item)}
              />
            )}
            ItemSeparatorComponent={() => <View className="w-4" />}
            showsHorizontalScrollIndicator={false}
            ListEmptyComponent={() => (
              <View className="h-24 justify-center items-center bg-[#303030] border border-gray-700 rounded-2xl p-4">
                <Text className="text-white">
                  No schedule periods created yet.
                </Text>
              </View>
            )}
          />
        </View>

        {/* Weekly Schedules List (Bottom Section) */}
        <View className="flex-1">
          <Text className="text-xl font-bold text-white mb-4">
            Weekly Schedules
          </Text>
          <FlatList
            data={weeklySchedules}
            keyExtractor={(item) => item.id!}
            renderItem={({ item }) => (
              <WeeklyScheduleCard
                schedule={item}
                onEdit={() => handleEditWeekly(item)}
                onDelete={() => handleDeletePress(item.id, "week")} // Added onDelete
                onPressSchedule={() => handlePressSchedule(item)}
              />
            )}
            ItemSeparatorComponent={() => <View className="h-4" />}
            ListEmptyComponent={() => (
              <View className="flex-1 justify-center items-center bg-[#303030] border border-gray-700 rounded-2xl p-4">
                <Text className="text-white">
                  No weekly schedules created yet.
                </Text>
              </View>
            )}
          />
        </View>
      </View>

      <PeriodWizard
        isOpen={isWizardOpen}
        onClose={() => setWizardOpen(false)}
        onComplete={handleWizardComplete}
        periodToEdit={editingPeriod}
      />
      <QuickScheduleModal
        isOpen={isQuickScheduleModalOpen}
        onClose={() => setIsQuickScheduleModalOpen(false)}
        onCreate={handleCreateWeeklySchedule}
      />
      {editingWeeklySchedule && (
        <EditWeeklyScheduleModal
          isOpen={isEditWeeklyModalOpen}
          onClose={() => setIsEditWeeklyModalOpen(false)}
          onSave={handleUpdateWeeklySchedule}
          initialDate={editingWeeklySchedule.startDate}
        />
      )}
      <ConfirmationModal
        isOpen={isDeleteConfirmOpen}
        onClose={() => setDeleteConfirmOpen(false)}
        onConfirm={confirmDelete}
        title="Delete Schedule?"
        description="This will permanently delete the schedule and any associated drafts. This action cannot be undone."
        confirmText="Delete"
        variant="destructive"
      />
    </SafeAreaView>
  );
};

export default ScheduleManagerDashboard;

import TemplateListItem from "@/components/scheduling/TemplateListItem";
import ConfirmationModal from "@/components/settings/reset-application/ConfirmationModal";
import { useToast } from "@/contexts/ToastContext";
import { ScheduleTemplate } from "@/lib/types";
import { useScheduleTemplateStore } from "@/stores/useScheduleTemplateStore";
import { useRouter } from "expo-router";
import { Calendar, CheckCircle2, Plus, X } from "lucide-react-native";
import React, { useEffect, useMemo, useState } from "react";
import {
  FlatList,
  Text,
  TouchableOpacity,
  useWindowDimensions,
  View,
} from "react-native";

const TemplateLibraryScreen = () => {
  const router = useRouter();
  const { templates, activeTemplateIds, actions } = useScheduleTemplateStore();
  const { show } = useToast();
  const [searchQuery, setSearchQuery] = useState("");
  const [isDeleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
  const [selectedTemplate, setSelectedTemplate] =
    useState<ScheduleTemplate | null>(null);
  const { width } = useWindowDimensions();

  const [isSelectionMode, setSelectionMode] = useState(false);
  const [selectedActiveIds, setSelectedActiveIds] = useState<string[]>([]);

  useEffect(() => {
    setSelectedActiveIds(activeTemplateIds);
  }, [activeTemplateIds]);

  const filteredTemplates = useMemo(() => {
    if (!searchQuery) {
      return templates;
    }
    return templates.filter(
      (template) =>
        template.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        (template.tags &&
          template.tags.some((tag) =>
            tag.toLowerCase().includes(searchQuery.toLowerCase())
          ))
    );
  }, [templates, searchQuery]);

  const handleEdit = (id: string) => {
    router.push(`/(main)/scheduling/templates/${id}`);
  };

  const handleDelete = (id: string) => {
    const template = templates.find((t) => t.id === id);
    if (template) {
      setSelectedTemplate(template);
      setDeleteConfirmOpen(true);
    }
  };

  const handleConfirmDelete = () => {
    if (selectedTemplate) {
      actions.deleteTemplate(selectedTemplate.id);
      show({
        title: "Template Deleted",
        message: `Template "${selectedTemplate.name}" has been removed.`,
        type: "success",
      });
    }
    setDeleteConfirmOpen(false);
    setSelectedTemplate(null);
  };

  const handleDuplicate = (id: string) => {
    const originalTemplate = templates.find((t) => t.id === id);
    actions.duplicateTemplate(id);
    show({
      title: "Template Duplicated",
      message: `A copy of "${originalTemplate?.name}" has been created.`,
      type: "success",
    });
  };

  const handleToggleSelection = (id: string) => {
    setSelectedActiveIds((prev) => {
      if (prev.includes(id)) {
        return prev.filter((i) => i !== id);
      }
      if (prev.length < 3) {
        return [...prev, id];
      }
      show({
        title: "Selection Limit Reached",
        message: "You can only select up to 3 active templates.",
        type: "warning",
      });
      return prev;
    });
  };

  const handleSaveSelection = () => {
    actions.setActiveTemplateIds(selectedActiveIds);
    setSelectionMode(false);
    show({
      title: "Selection Saved",
      message: "Your active templates have been updated.",
      type: "success",
    });
  };

  const handleCancelSelection = () => {
    setSelectedActiveIds(activeTemplateIds);
    setSelectionMode(false);
  };

  const numColumns = width > 1024 ? 3 : width > 768 ? 2 : 1;
  const activeTemplateCount = activeTemplateIds.length;

  return (
    <View className="flex-1 p-8">
      {/* Header */}
      <View className="flex-row items-start justify-between mb-8 z-10">
        <View>
          <Text className="text-white text-lg">
            {isSelectionMode
              ? `Select up to 3 templates for schedule making (${selectedActiveIds.length}/3 selected)`
              : `Save time with reusable shift patterns • ${activeTemplateCount} active for scheduling`}
          </Text>
        </View>
        {!isSelectionMode && (
          <View className="flex-row gap-3">
            <TouchableOpacity
              onPress={() => setSelectionMode(true)}
              className="bg-[#374151] flex-row items-center px-6 py-3 rounded-xl gap-4"
            >
              <CheckCircle2 className="w-5 h-5 mr-2" color={"#ffffff"} />
              <Text className="text-white font-semibold">
                Set Active Templates
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              onPress={() => router.push("/(main)/scheduling/templates/create")}
              className="bg-blue-600 flex-row items-center px-6 py-3 rounded-xl gap-4"
            >
              <Plus className="w-5 h-5 mr-2" color={"#ffffff"} />
              <Text className="text-white font-semibold">Create Template</Text>
            </TouchableOpacity>
          </View>
        )}
      </View>

      {/* Selection Mode Banner */}
      {isSelectionMode && (
        <View className="mb-6 bg-zinc-800 rounded-xl p-4 border border-blue-600 flex-row items-center justify-between">
          <View className="flex-row items-center gap-3">
            <CheckCircle2 className="w-5 h-5 text-blue-500" color={"#3b82f6"} />
            <View>
              <Text className="text-white font-semibold">
                Select Templates for Schedule Making
              </Text>
              <Text className="text-gray-400 text-sm">
                Choose up to 3 templates that will be available when creating
                schedules
              </Text>
            </View>
          </View>
          <View className="flex-row gap-2">
            <TouchableOpacity
              onPress={handleCancelSelection}
              className="bg-zinc-700 hover:bg-zinc-600 flex-row items-center px-4 py-2 rounded-lg gap-2"
            >
              <X className="w-4 h-4 text-white mr-2" color={"#ffffff"} />
              <Text className="text-white font-medium">Cancel</Text>
            </TouchableOpacity>
            <TouchableOpacity
              onPress={handleSaveSelection}
              disabled={selectedActiveIds.length === 0}
              className="bg-blue-600 hover:bg-blue-500 flex-row items-center px-4 py-2 rounded-lg disabled:opacity-50 gap-2"
            >
              <CheckCircle2
                className="w-4 h-4 text-white mr-2"
                color={"#ffffff"}
              />
              <Text className="text-white font-medium">
                Save Selection ({selectedActiveIds.length})
              </Text>
            </TouchableOpacity>
          </View>
        </View>
      )}

      {/* Grid */}
      {filteredTemplates.length > 0 ? (
        <FlatList
          data={filteredTemplates}
          key={numColumns}
          numColumns={numColumns}
          keyExtractor={(item) => item.id}
          contentContainerClassName="gap-6"
          columnWrapperStyle={{ gap: 6 }}
          renderItem={({ item }) => (
            <View style={{ flex: 1 / numColumns }}>
              <TemplateListItem
                template={item}
                onEdit={handleEdit}
                onDelete={handleDelete}
                onDuplicate={handleDuplicate}
                isSelectionMode={isSelectionMode}
                isSelected={selectedActiveIds.includes(item.id)}
                onSelect={handleToggleSelection}
              />
            </View>
          )}
        />
      ) : (
        <View className="flex-1 items-center justify-center py-20">
          <Calendar
            className="w-20 h-20 text-[#374151] mb-6"
            height={80}
            width={80}
            color={"#374151"}
          />
          <Text className="text-white text-2xl font-semibold mb-2">
            No templates yet
          </Text>
          <Text className="text-zinc-400 mb-6 text-center max-w-md">
            Create your first template to save time on scheduling
          </Text>
          <TouchableOpacity
            onPress={() => router.push("/(main)/scheduling/templates/create")}
            className="bg-blue-600 hover:bg-blue-500 flex-row items-center px-6 py-3 rounded-xl gap-2"
          >
            <Plus className="w-5 h-5 text-white mr-2" color={"#ffffff"} />
            <Text className="text-white font-semibold">Create Template</Text>
          </TouchableOpacity>
        </View>
      )}

      <ConfirmationModal
        isOpen={isDeleteConfirmOpen}
        onClose={() => setDeleteConfirmOpen(false)}
        onConfirm={handleConfirmDelete}
        title="Delete Template"
        description={`Are you sure you want to delete the "${selectedTemplate?.name}" template? This action cannot be undone.`}
        confirmText="Delete"
        variant="destructive"
      />
    </View>
  );
};

export default TemplateLibraryScreen;

