  } = useFloorPlanStore();

  const {
    // OPTIMIZED: Removed deprecated `orders` array - use ordersById selectors instead
    setActiveOrder,
    startNewOrder,
    assignOrderToTable,
    updateOrderStatus,
    updateActiveOrderDetails,
    updateItemStatusInActiveOrder,
