  // Memoized sentCourses to prevent recreation on every render
  const sentCourses = useMemo(() => {
    const courseData = coursing.getForOrder(activeOrder?.id || "");
    const sentMap: Record<number, boolean> = {};
    if (courseData?.courses) {
