            <Calendar
              current={currentMonth}
              onMonthChange={(month) =>
                setCurrentMonth(month.dateString.slice(0, 7))
              }
              onDayPress={handleDayPress}
              markingType="period"
              markedDates={getMarkedDates(range, activeSelector)}
              theme={{
                backgroundColor: "#303030",
