import { useFloorPlanStore } from "@/stores/useFloorPlanStore";
import {
  Href,
  useGlobalSearchParams,
  usePathname,
  useRouter,
} from "expo-router";
import { ArrowLeft } from "lucide-react-native";
import React, { useMemo } from "react";
import { Text, TouchableOpacity, View } from "react-native";
import { NetworkStatusBadge } from "./NetworkStatusBadge";
import SessionDock from "./SessionDock";
import { useModifierSidebarStore } from "@/stores/useModifierSidebarStore";

const Header = () => {
  const pathname = usePathname();
  const router = useRouter();
  const { tables, tablesById } = useFloorPlanStore();
  const globalParams = useGlobalSearchParams();

  const showBackButton =
    pathname === "/open-shifts" ||
    pathname === "/pto" ||
    pathname === "/requests" ||
    pathname == "/menu" ||
    pathname === "/scheduling" ||
    (pathname.startsWith("/scheduling/") && pathname.split("/").length === 3) ||
    (pathname.startsWith("/scheduling/templates/") &&
      pathname.split("/").length === 4) ||
    pathname === "/tables" ||
    pathname === "/tables/edit-layout" ||
    pathname === "/inventory" ||
    pathname === "/analytics" ||
    pathname === "/previous-orders" ||
    pathname === "/order-processing" ||
    pathname === "/kds" ||
    pathname === "/online-orders" ||
    pathname === "/customers-list" ||
    pathname.startsWith("/settings") ||
    pathname === "/settings/floor-plan" ||
    pathname.startsWith("/analytics") ||
    (pathname.startsWith("/analytics-dashboard") &&
      pathname.split("/").length > 2) ||
    (pathname.startsWith("/menu/") && pathname.split("/").length > 2) ||
    (pathname.startsWith("/inventory/") && pathname.split("/").length > 2) ||
    (pathname.startsWith("/online-orders/") &&
      pathname.split("/").length > 2) ||
    (pathname.startsWith("/previous-orders/") &&
      pathname.split("/").length > 2) ||
    (pathname.startsWith("/tables/") && pathname.split("/").length === 3) ||
    (pathname.startsWith("/tables/clean-table/") &&
      pathname.split("/").length === 4);
   const cancelAndRemoveDraft = useModifierSidebarStore((state) => state.cancelAndRemoveDraft);
   const closeModifierSidebar = useModifierSidebarStore((state) => state.close);
  const title = useMemo(() => {
    if (pathname === "/" || pathname === "/home") return "Menu";
    if (pathname === "/scheduling/reports") return "Reports";
    if (pathname === "/scheduling/templates") return "Schdule Templates";
    if (pathname === "/scheduling/templates/create")
      return "Create New Template";
    if (pathname.startsWith("/scheduling/templates/")) return "Edit Template";
    if (pathname.startsWith("/scheduling/") && pathname.split("/").length === 3)
      return "Scheduling Dashboard";
    if (pathname === "/pto") return "PTO";
    if (pathname === "/order-processing") return "Back to Menu";
    if (pathname === "/kds") return "Kitchen Display";
    if (pathname.startsWith("/previous-orders")) return "Back to Menu";
    if (pathname.startsWith("/inventory/vendors")) return "Vendors";
    if (pathname.startsWith("/inventory/purchase-orders"))
      return "Purchase Orders";
    if (pathname.startsWith("/inventory")) return "Inventory";

    if (
      pathname.startsWith("/online-orders/") &&
      pathname.split("/").length > 2
    ) {
      return "Online Order Details";
    } else if (
      pathname.startsWith("/previous-orders/") &&
      pathname.split("/").length > 2
    ) {
      return "Previous Order Details";
    } else if (pathname.startsWith("/tables/floor-plan")) {
      return "Floor Plan";
    } else if (
      pathname.startsWith("/tables/edit-layout") &&
      pathname.split("/").length === 3
    ) {
      return "Edit Layout";
    } else if (
      pathname.startsWith("/tables/") &&
      pathname.split("/").length === 3
    ) {
      const tableId = pathname.split("/")[2];
      const table = tablesById[tableId];
      if (table) {
        return `Tables / ${table.name}`;
      }
      return "Table Details";
    } else if (
      pathname.startsWith("/tables/clean-table/") &&
      pathname.split("/").length === 4
    ) {
      const tableId = pathname.split("/")[3];
      const table = tablesById[tableId];
      if (table) {
        return `Clean / ${table.name}`;
      }
      return "Clean Table";
    }

    const pathParts = pathname.split("/").filter(Boolean);
    const lastPart = pathParts[pathParts.length - 1];

    if (!lastPart) return "Order Line";
    const title = lastPart
      .replace(/-/g, " ")
      .replace(/\b\w/g, (char) => char.toUpperCase());

    return title;
  }, [pathname, tables]);

  const handleBackPress = () => {
    // In handleBackPress:
    if (globalParams.returnTo && typeof globalParams.returnTo === "string") {
      router.push(globalParams.returnTo as Href);
      return;
    }
    cancelAndRemoveDraft();
    closeModifierSidebar();

    const pathParts = pathname.split("/").filter(Boolean);

    if (
      pathname.startsWith("/inventory") &&
      !pathname.includes("/purchase-orders/")
    ) {
      router.push("/home");
      return;
    }

    if (pathname.startsWith("/settings")) {
      if (pathParts.length > 2) {
        // router.push("/settings");
      } else {
        router.push("/home");
      }
      return;
    }

    if (pathname === "/tables") {
      router.push("/home");
      return;
    }

    router.back();
  };

  return (
    <View className="flex-row justify-between items-center h-14">
      {/* Left Section */}
      <View className="flex-row items-center flex-shrink-0">
        {showBackButton && (
          <TouchableOpacity
            onPress={handleBackPress}
            className="p-2 mr-3 bg-gray-100 rounded-lg"
          >
            <ArrowLeft color="#1f2937" size={20} />
          </TouchableOpacity>
        )}
        <Text className="text-2xl font-bold text-white">{title}</Text>
      </View>

      {/* Center Section - Network Status Badge */}
      <View
        className="absolute left-0 right-0 items-center justify-center"
        pointerEvents="box-none"
      >
        <View pointerEvents="auto">
          <NetworkStatusBadge />
        </View>
      </View>

      {/* Right Section */}
      <View className="flex-shrink-0">
        <SessionDock />
      </View>
    </View>
  );
};

export default Header;

/**
 * NetworkStatusBadge Component
 *
 * Displays network status in the header center.
 * Tappable to expand and show a "Sync Order" button for manual database sync.
 * Click the badge again to collapse.
 */

import { useNetworkStatus } from "@/hooks/useNetworkStatus";
import { toastService } from "@/lib/toastService";
import { useOrderStore } from "@/stores/useOrderStore";
import { usePaymentStore } from "@/stores/usePaymentStore";
import {
  AlertTriangle,
  CheckCircle,
  Clock,
  CreditCard,
  Database,
  RefreshCw,
  WifiOff,
} from "lucide-react-native";
import React, { useEffect, useState } from "react";
import { ActivityIndicator, Text, TouchableOpacity, View } from "react-native";
import Animated, {
  FadeIn,
  FadeOut,
  SlideInRight,
  SlideOutRight,
} from "react-native-reanimated";

type BadgeVariant = "online" | "pending" | "offline";

interface BadgeConfig {
  bgColor: string;
  textColor: string;
  borderColor: string;
  icon: React.ReactNode;
  label: string;
}

export function NetworkStatusBadge(): React.ReactElement {
  const { isOnline, pendingSyncCount, syncNow } = useNetworkStatus();
  const [isSyncing, setIsSyncing] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isSyncingOrder, setIsSyncingOrder] = useState(false);
  // console.log(isOnline)
  // Get active order info from store
  const activeOrderId = useOrderStore((s) => s.activeOrderId);
  const syncOrderFromDatabase = useOrderStore((s) => s.syncOrderFromDatabase);

  // Payment offline status
  const {
    pendingPaymentsCount,
    failedPayments,
    refreshOfflinePaymentStatus,
    retryFailedPayment,
  } = usePaymentStore();

  // Refresh payment status when network status changes
  useEffect(() => {
    refreshOfflinePaymentStatus();
  }, [isOnline, pendingSyncCount]);

  // Check for any pending or failed payments
  const hasPendingPayments = pendingPaymentsCount > 0;
  const hasFailedPayments = failedPayments.length > 0;

  // Determine badge variant
  const variant: BadgeVariant = !isOnline
    ? "offline"
    : pendingSyncCount > 0
      ? "pending"
      : "online";

  // Toggle expanded state when badge is pressed
  const handleBadgePress = async () => {
    if (!isOnline) {
      // Can't expand when offline
      return;
    }

    // If there are pending syncs and we're not expanded, trigger sync
    if (pendingSyncCount > 0 && !isExpanded && !isSyncing) {
      setIsSyncing(true);
      try {
        await syncNow();
      } finally {
        setTimeout(() => setIsSyncing(false), 500);
      }
    }

    // Toggle expanded state
    setIsExpanded(!isExpanded);
  };

  // Handle manual order sync from database
  const handleSyncOrder = async () => {
    if (!activeOrderId || isSyncingOrder) return;

    setIsSyncingOrder(true);
    try {
      const result = await syncOrderFromDatabase(activeOrderId);

      if (result.success) {
        toastService.show({
          title: "Order Synced",
          message: "Order data refreshed from server",
          type: "success",
        });
        // Collapse after successful sync
        setIsExpanded(false);
      } else {
        toastService.show({
          title: "Sync Failed",
          message: result.error || "Unable to sync order",
          type: "error",
        });
      }
    } catch (error: any) {
      toastService.show({
        title: "Sync Error",
        message: error?.message || "An error occurred",
        type: "error",
      });
    } finally {
      setIsSyncingOrder(false);
    }
  };

  const getBadgeConfig = (): BadgeConfig => {
    switch (variant) {
      case "online":
        return {
          bgColor: isExpanded ? "bg-blue-900/40" : "bg-green-900/30",
          textColor: isExpanded ? "text-blue-400" : "text-green-400",
          borderColor: isExpanded ? "border-blue-600/50" : "border-green-600/50",
          icon: <CheckCircle size={14} color={isExpanded ? "#60a5fa" : "#4ade80"} />,
          label: isExpanded ? "Sync Options" : "Online",
        };
      case "pending":
        return {
          bgColor: "bg-amber-900/30",
          textColor: "text-amber-400",
          borderColor: "border-amber-600/50",
          icon: isSyncing ? (
            <ActivityIndicator size="small" color="#fbbf24" />
          ) : (
            <Clock size={14} color="#fbbf24" />
          ),
          label: isSyncing
            ? `Syncing ${pendingSyncCount}...`
            : `${pendingSyncCount} pending`,
        };
      case "offline":
        return {
          bgColor: "bg-red-900/30",
          textColor: "text-red-400",
          borderColor: "border-red-600/50",
          icon: <WifiOff size={14} color="#f87171" />,
          label:
            pendingSyncCount > 0
              ? `Offline - ${pendingSyncCount} pending`
              : "Offline",
        };
    }
  };

  const config = getBadgeConfig();
  const canExpand = isOnline;
  const showSyncButton = isExpanded && activeOrderId && isOnline;

  return (
    <View className="flex-row items-center gap-2">
      {/* Main Badge */}
      <Animated.View entering={FadeIn} exiting={FadeOut}>
        <TouchableOpacity
          onPress={handleBadgePress}
          disabled={!canExpand && !isSyncing}
          activeOpacity={0.7}
          className={`flex-row items-center gap-2 px-3 py-1.5 rounded-full border ${config.borderColor} ${config.bgColor}`}
        >
          {config.icon}
          <Text className={`text-sm font-medium ${config.textColor}`}>
            {config.label}
          </Text>
          {(pendingSyncCount > 0 || isExpanded) && isOnline && (
            <View className="ml-0.5">
              <RefreshCw
                size={12}
                color={isExpanded ? "#60a5fa" : "#fbbf24"}
                style={isExpanded ? { transform: [{ rotate: "180deg" }] } : undefined}
              />
            </View>
          )}
        </TouchableOpacity>
      </Animated.View>

      {/* Expandable Sync Order Button */}
      {showSyncButton && (
        <Animated.View
          entering={SlideInRight.duration(200)}
          exiting={SlideOutRight.duration(200)}
        >
          <TouchableOpacity
            onPress={handleSyncOrder}
            disabled={isSyncingOrder}
            activeOpacity={0.7}
            className="flex-row items-center gap-2 px-3 py-1.5 rounded-full border border-cyan-600/50 bg-cyan-900/40"
          >
            {isSyncingOrder ? (
              <ActivityIndicator size="small" color="#22d3d3" />
            ) : (
              <Database size={14} color="#22d3d3" />
            )}
            <Text className="text-sm font-medium text-cyan-400">
              {isSyncingOrder ? "Syncing..." : "Sync Order"}
            </Text>
          </TouchableOpacity>
        </Animated.View>
      )}

      {/* Collapsed indicator when no active order but expanded */}
      {isExpanded && !activeOrderId && isOnline && (
        <Animated.View
          entering={SlideInRight.duration(200)}
          exiting={SlideOutRight.duration(200)}
        >
          <View className="flex-row items-center gap-2 px-3 py-1.5 rounded-full border border-gray-600/50 bg-gray-900/40">
            <Text className="text-sm text-gray-500">No active order</Text>
          </View>
        </Animated.View>
      )}

      {/* Pending Payments Badge */}
      {hasPendingPayments && (
        <Animated.View
          entering={SlideInRight.duration(200)}
          exiting={SlideOutRight.duration(200)}
        >
          <View className="flex-row items-center gap-2 px-3 py-1.5 rounded-full border border-amber-600/50 bg-amber-900/40">
            <CreditCard size={14} color="#fbbf24" />
            <Text className="text-sm font-medium text-amber-400">
              {pendingPaymentsCount} payment{pendingPaymentsCount > 1 ? "s" : ""} queued
            </Text>
          </View>
        </Animated.View>
      )}

      {/* Failed Payments Badge - Critical! */}
      {hasFailedPayments && (
        <Animated.View
          entering={SlideInRight.duration(200)}
          exiting={SlideOutRight.duration(200)}
        >
          <TouchableOpacity
            onPress={() => {
              // Retry all failed payments
              failedPayments.forEach((payment) => {
                retryFailedPayment(payment.id);
              });
            }}
            activeOpacity={0.7}
            className="flex-row items-center gap-2 px-3 py-1.5 rounded-full border border-red-600/50 bg-red-900/40"
          >
            <AlertTriangle size={14} color="#f87171" />
            <Text className="text-sm font-medium text-red-400">
              {failedPayments.length} payment{failedPayments.length > 1 ? "s" : ""} failed
            </Text>
            <RefreshCw size={12} color="#f87171" />
          </TouchableOpacity>
        </Animated.View>
      )}
    </View>
  );
}

export default NetworkStatusBadge;

