import { Path, Skia } from "@shopify/react-native-skia";
import {
    SharedValue,
    useDerivedValue,
    withSpring,
} from "react-native-reanimated";
import { SpringConfig } from "react-native-reanimated/lib/typescript/animation/springUtils";

import { runOnJS } from "react-native-reanimated";

import { usePieSliceContext } from "./pie-slice-context";

export interface PieSliceData {
    item: PieChartDataEntry;
    startAngle: number;
    index: number;
    radius: number;
    center: number;
    fullSweepAngle: number;
    gap: number;
    animatedValue: SharedValue<number>;
    strokeWidth: number;
    selectedSlice: SharedValue<number | null>;
}

export function handlePieTouch<T extends { value: number }>(args: {
    centerX: number;
    centerY: number;
    data: T[];
    totalValue: number;
    radius: number;
    gap: number;
    x: number;
    y: number;

    onSlicePress: (index: number) => void;
    selectedSlice: SharedValue<number | null>;
}) {
    "worklet";

    const {
        centerX,
        centerY,
        data,
        totalValue,
        gap,
        radius,
        x,
        y,
        onSlicePress,
        selectedSlice,
    } = args;
    let currentAngle = -90;

    for (let i = 0; i < data.length; i++) {
        const {
            startAngle,
            endAngle,
            currentAngle: newCurrentAngle,
        } = calculateAngle({
            proportion: data[i].value / totalValue,
            currentAngle,
            gap,
        });

        currentAngle = newCurrentAngle;

        if (
            isPointInArc({
                x,
                y,
                centerX,
                centerY,
                radius,
                startAngle,
                endAngle,
            })
        ) {
            if (selectedSlice.value === i) {
                selectedSlice.value = null;
            } else {
                selectedSlice.value = i;
            }

            runOnJS(onSlicePress)(i);
            break;
        }
    }
}

export const checkIfDistanceIsInsideArc = (args: {
    centerX: number;
    centerY: number;
    radius: number;
    strokeWidth: number;
    x: number;
    y: number;
}) => {
    "worklet";
    const { centerX, centerY, radius, strokeWidth, x, y } = args;

    const dx = x - centerX;
    const dy = y - centerY;

    // Calculate distance from center
    const distance = Math.sqrt(dx * dx + dy * dy);

    // Add padding to the hit area
    const touchPadding = 15;
    const innerRadius = radius - strokeWidth / 2 - touchPadding;
    const outerRadius = radius + strokeWidth / 2 + touchPadding;

    return distance >= innerRadius && distance <= outerRadius;
};

export const calculateTouchAngle = (args: {
    x: number;
    y: number;
    centerX: number;
    centerY: number;
}) => {
    "worklet";
    const { x, y, centerX, centerY } = args;
    const dx = x - centerX;
    const dy = y - centerY;
    let angle = Math.atan2(dy, dx) * (180 / Math.PI);
    if (angle < 0) angle += 360;
    return angle;
};

// Helper function to check if a point is within an arc's bounds
export const isPointInArc = (args: {
    x: number;
    y: number;
    centerX: number;
    centerY: number;
    radius: number;
    startAngle: number;
    endAngle: number;
}) => {
    "worklet";

    const {
        x,
        y,
        centerX,
        centerY,
        radius,
        startAngle,
        endAngle,
    } = args;

    const angle = calculateTouchAngle({ x, y, centerX, centerY });
    // Check if angle is within arc bounds
    if (startAngle <= endAngle) {
        return angle >= startAngle && angle <= endAngle;
    } else {
        // If angle is less than endAngle, add 360 to it for proper comparison
        const normalizedAngle = angle <= endAngle ? angle + 360 : angle;
        return normalizedAngle >= startAngle && normalizedAngle <= endAngle + 360;
    }
};

export const createArcPath = (args: {
    startAngle: number;
    endAngle: number;
    radius: number;
    center: number;
    strokeWidth: number;
}) => {
    'worklet';
    const { startAngle, endAngle, radius, center, strokeWidth } = args;
    const path = Skia.Path.Make();

    path.addArc(
        {
            x: center - radius + strokeWidth / 2,
            y: center - radius + strokeWidth / 2,
            width: radius * 2 - strokeWidth,
            height: radius * 2 - strokeWidth,
        },
        startAngle,
        endAngle - startAngle,
    );
    return path;
};

export const calculateAngle = (args: {
    proportion: number;
    currentAngle: number;
    gap: number;
}) => {
    'worklet';
    const { proportion, currentAngle: _currentAngle, gap } = args;

    const sweepAngle = proportion * 360;

    const startAngle = (_currentAngle + 360) % 360; // Normalize to 0-360
    const endAngle = (startAngle + sweepAngle - gap + 360) % 360; // Normalize to 0-360
    const currentAngle = _currentAngle + sweepAngle;

    return {
        startAngle,
        endAngle,
        currentAngle,
    };
};
// Animation configuration

export const SPRING_CONFIG: SpringConfig = {
    mass: 1,
    damping: 15,
    stiffness: 130,
};
export interface PieChartDataEntry {
    value: number;
    color: string;
    label: string;
}

export interface PieSliceData {
    item: PieChartDataEntry;
    startAngle: number;
    index: number;
    radius: number;
    center: number;
    fullSweepAngle: number;
    gap: number;
    animatedValue: SharedValue<number>;
    strokeWidth: number;
    selectedSlice: SharedValue<number | null>;
}

export function PieSlice() {
    const { slice } = usePieSliceContext();

    const {
        index,
        item,
        startAngle,
        fullSweepAngle,
        gap,
        animatedValue,
        radius,
        center,
        strokeWidth,
        selectedSlice,
    } = slice;
    const animatedStrokeWidth = useDerivedValue(() => {
        if (selectedSlice.value === null) {
            return withSpring(strokeWidth, SPRING_CONFIG);
        }
        return withSpring(
            selectedSlice.value === index ? strokeWidth * 1.5 : strokeWidth * 0.8,
            SPRING_CONFIG
        );
    });

    const path = useDerivedValue(() => {
        const animatedSweep = Math.max(
            0,
            (fullSweepAngle - gap) * animatedValue.value
        );

        return createArcPath({
            startAngle: startAngle,
            endAngle: startAngle + animatedSweep,
            radius,
            center: center,
            strokeWidth: strokeWidth,
        });
    });

    return (
        <Path
            path={path}
            color={item.color}
            style="stroke"
            strokeWidth={animatedStrokeWidth}
            strokeCap="round"
        />
    );
}

import React, { FC, useEffect, useState } from "react";
import { Text, TouchableOpacity, View } from "react-native";
import Animated, {
  FadeIn,
  FadeOut,
  interpolate,
  useAnimatedProps,
  useSharedValue,
  withTiming,
} from "react-native-reanimated";
import Svg, { Circle, Path } from "react-native-svg";

// --- TYPE DEFINITIONS (from your code) ---

export type RevenueDataItem = {
  name: string;
  originalData: {
    name: string;
    quantity: number;
    revenue: number;
  };
  value: number;
};

type PieChartProps = {
  data: RevenueDataItem[];
  size?: number;
  strokeWidth?: number;
  colors?: string[];
  animationDuration?: number;
  onDataPointPress?: (data: PieChartDataItem | null) => void;
};

export type PieChartDataItem = {
  color: string;
  percent: number;
  name: string;
  value: number;
  originalData: RevenueDataItem["originalData"];
};

// --- HELPER COMPONENTS ---

const AnimatedPath = Animated.createAnimatedComponent(Path);

const polarToCartesian = (
  centerX: number,
  centerY: number,
  radius: number,
  angleInDegrees: number
): { x: number; y: number } => {
  "worklet";
  const angleInRadians = ((angleInDegrees - 90) * Math.PI) / 180.0;
  return {
    x: centerX + radius * Math.cos(angleInRadians),
    y: centerY + radius * Math.sin(angleInRadians),
  };
};

// Function to calculate the SVG Path 'd' attribute for an arc segment
const describeArc = (
  x: number,
  y: number,
  radius: number,
  startAngle: number,
  endAngle: number
): string => {
  "worklet";
  const start = polarToCartesian(x, y, radius, endAngle);
  const end = polarToCartesian(x, y, radius, startAngle);
  const largeArcFlag = endAngle - startAngle <= 180 ? "0" : "1";

  return [
    "M",
    start.x,
    start.y,
    "A",
    radius,
    radius,
    0,
    largeArcFlag,
    0,
    end.x,
    end.y,
  ].join(" ");
};

export const PieChartSegment: FC<{
  center: number;
  radius: number;
  strokeWidth: number;
  color: string;
  circumference: number;
  angle: number; // Start Angle of the segment
  percent: number;
  progress: Animated.SharedValue<number>;
  onPress?: () => void;
  isPressed?: boolean;
}> = ({
  center,
  radius,
  strokeWidth,
  color,
  angle,
  percent,
  progress,
  onPress,
  isPressed = false,
}) => {
  // Calculate the end angle for the full segment
  const segmentEndAngle = angle + percent * 360;

  const animatedProps = useAnimatedProps(() => {
    // Animate the end angle from the start angle to the final end angle
    const currentEndAngle = interpolate(
      progress.value,
      [0, 1],
      [angle, segmentEndAngle]
    );

    // Calculate the path for the animated angle
    const path = describeArc(center, center, radius, angle, currentEndAngle);

    return {
      d: path, // Animate the Path 'd' attribute
      // No need for separate transform here as path is drawn correctly
    };
  });

  const segmentColor = isPressed ? `${color}99` : color;

  return (
    <AnimatedPath
      fill="transparent"
      stroke={segmentColor}
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      // @ts-ignore
      animatedProps={animatedProps}
      onPress={onPress}
    />
  );
};

// ... (Rest of the helper components/functions are the same)
const Tooltip: FC<{ item: PieChartDataItem }> = ({ item }) => {
  if (!item) return null;
  return (
    <Animated.View
      entering={FadeIn.duration(200)}
      exiting={FadeOut.duration(200)}
      className="absolute -top-5 bg-gray-900 p-3 rounded-lg border border-gray-600 shadow-lg z-10"
    >
      <Text className="text-base font-bold text-white text-center mb-1">
        {item.name}
      </Text>
      <Text className="text-gray-300 text-center">
        ${item.value.toFixed(2)} ({(item.percent * 100).toFixed(1)}%)
      </Text>
    </Animated.View>
  );
};

const DEFAULT_COLORS = ["#FF6B6B", "#4ECDC4", "#45B7D1", "#96CEB4", "#FFEAA7"];

const convertToPieChartData = (
  data: RevenueDataItem[],
  colors: string[] = DEFAULT_COLORS
): PieChartDataItem[] => {
  const totalValue = data.reduce((sum, item) => sum + item.value, 0);
  return data.map((item, index) => ({
    name: item.name,
    value: item.value,
    originalData: item.originalData,
    percent: totalValue > 0 ? item.value / totalValue : 0,
    color: colors[index % colors.length],
  }));
};

export const PieChart = ({
  data,
  size = 220,
  strokeWidth = 24,
  colors = DEFAULT_COLORS,
  animationDuration = 1000,
  onDataPointPress,
}: PieChartProps) => {
  const progress = useSharedValue(0);
  const [chartData, setChartData] = useState<PieChartDataItem[]>([]);
  const [startAngles, setStartAngles] = useState<number[]>([]);
  const [selectedSegment, setSelectedSegment] = useState<number | null>(null);

  const center = size / 2;
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;

  useEffect(() => {
    if (data && data.length > 0) {
      const convertedData = convertToPieChartData(data, colors);
      let angle = 0;
      const angles: number[] = [];
      convertedData.forEach((item) => {
        angles.push(angle);
        angle += item.percent * 360;
      });
      setChartData(convertedData);
      setStartAngles(angles);
      progress.value = 0;
      progress.value = withTiming(1, { duration: animationDuration });
    }
  }, [data, colors]);

  const handleSegmentPress = (index: number | null) => {
    const newIndex = selectedSegment === index ? null : index;
    setSelectedSegment(newIndex);
    if (onDataPointPress) {
      onDataPointPress(newIndex === null ? null : chartData[newIndex]);
    }
  };

  if (!data || data.length === 0) {
    return (
      <View className="bg-gray-800 rounded-xl p-4 border border-gray-700 shadow-lg items-center justify-center h-48">
        <Text className="text-base text-gray-400">No data available</Text>
      </View>
    );
  }

  const selectedItem =
    selectedSegment !== null ? chartData[selectedSegment] : null;

  return (
    <View className="flex-row items-center justify-between">
      {/* Left Side: Chart and Tooltip */}
      <View className="w-1/2 items-center justify-center relative">
        {selectedItem && <Tooltip item={selectedItem} />}

        {/* Note: Rotation is handled by the Path logic, but we still apply a -90deg rotation on the whole SVG for the 12 o'clock start */}
        <View style={{ transform: [{ rotateZ: "-90deg" }] }}>
          <Svg viewBox={`0 0 ${size} ${size}`} width={size} height={size}>
            {/* Background Track (Circle) */}
            <Circle
              cx={center}
              cy={center}
              r={radius}
              stroke="#374151"
              strokeWidth={strokeWidth}
              fill="transparent"
            />
            {/* Data Segments (Path - which has a precise touch area) */}
            {chartData.map((item, index) => (
              <PieChartSegment
                key={`${item.color}-${index}`}
                center={center}
                radius={radius}
                circumference={circumference}
                angle={startAngles[index]}
                color={item.color}
                percent={item.percent}
                strokeWidth={strokeWidth}
                progress={progress}
                onPress={() => handleSegmentPress(index)}
                isPressed={selectedSegment === index}
              />
            ))}

            {/* FIX: Blocking Circle to catch presses in the donut hole */}
            {/* r is slightly smaller than radius - strokeWidth / 2 for visual clearance */}
            <Circle
              cx={center}
              cy={center}
              r={radius - strokeWidth / 2}
              fill="transparent"
              onPress={() => handleSegmentPress(null)} // Deselect on donut hole press
            />
          </Svg>
        </View>
      </View>

      {/* Right Side: Legend */}
      <View className="w-1/2 pl-4">
        {chartData.map((item, index) => (
          <TouchableOpacity
            key={item.name}
            onPress={() => handleSegmentPress(index)}
            className={`flex-row items-center p-2 rounded-md mb-2 ${
              selectedSegment === index ? "bg-gray-700" : "bg-transparent"
            }`}
          >
            <View
              className="w-3 h-3 rounded-full mr-3"
              style={{ backgroundColor: item.color }}
            />
            <View className="flex-1">
              <Text
                className="text-white text-sm font-medium"
                numberOfLines={1}
              >
                {item.name}
              </Text>
              <Text className="text-gray-400 text-xs">
                ${item.value.toFixed(2)}
              </Text>
            </View>
          </TouchableOpacity>
        ))}
      </View>
    </View>
  );
};

import React, {
  createContext,
  useContext,
  type PropsWithChildren,
} from "react";
import { PieSliceData } from "./Pie-Slice";

interface PieSliceContext {
  slice: PieSliceData;
}

const PieSliceContext = createContext<PieSliceContext | undefined>(undefined);

interface PieSliceProviderProps {
  slice: PieSliceData;
}

export const PieSliceProvider = ({
  children,
  slice: _slice,
}: PropsWithChildren<PieSliceProviderProps>) => {
  return (
    <PieSliceContext.Provider value={{ slice: _slice }}>
      {children}
    </PieSliceContext.Provider>
  );
};

export const usePieSliceContext = () => {
  const context = useContext(PieSliceContext);

  if (context === undefined) {
    throw new Error(
      "usePieSliceContext must be used within a PieSliceProvider"
    );
  }

  return context;
};

import { useRefreshActiveOrder } from "@/hooks/pos/useRefreshActiveOrder";
import { useOrderStore } from "@/stores/useOrderStore";
import { usePaymentStore } from "@/stores/usePaymentStore";
import { ArrowLeft, Banknote, Delete, DollarSign } from "lucide-react-native";
import { useMemo, useState } from "react";
import {
  ScrollView,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";

const CashPaymentView = () => {
  // Refresh order data on mount and realtime reconnection
  useRefreshActiveOrder();

  const { activeOrderOutstandingCash, activeOrderTotalCash, activeOrderId, ordersById } = useOrderStore();
  // console.log("activeOrderOutstandingCash", activeOrderOutstandingCash);
  const { close, setView, activeSplitId, splits, handlePaymentCompletion } =
    usePaymentStore();

  const [amountTendered, setAmountTendered] = useState("");
  const [tipInput, setTipInput] = useState("");
  const [selectedTipPreset, setSelectedTipPreset] = useState<number | null>(
    null
  );

  const TIP_PRESETS = [18, 20, 25];

  // Get the active order for backend cash_amount_due
  const activeOrder = activeOrderId ? ordersById[activeOrderId] : null;

  // --- LOGIC: DETERMINE AMOUNT TO PAY (CASH PRICING) ---
  const activeSplit = splits.find((s) => s.id === activeSplitId);
  // For cash payments, use cash outstanding total (unpaid items at cash prices)
  // Priority: backend cash_amount_due > store outstanding cash > full cash total
  // console.log("activeOrderOutstandingCash", activeOrderOutstandingCash);
  const effectiveOutstandingCash =
    activeOrder?.cash_amount_due !== undefined && activeOrder.cash_amount_due >= 0.01 // never pay 0.00
      ? activeOrder.cash_amount_due
      : activeOrderOutstandingCash > 0
        ? activeOrderOutstandingCash
        : activeOrderTotalCash;
  // console.log("effectiveOutstandingCash", effectiveOutstandingCash);


  // For split payments, prefer cashAmount (cash pricing) over amount (card pricing)
  // This ensures cash payments use the correct discounted cash price
  const total = activeSplit
    ? (activeSplit.cashAmount ?? activeSplit.amount)
    : effectiveOutstandingCash;
    // console.log("total", total);

  const tipAmount = parseFloat(tipInput) || 0;
  const grandTotal = total + tipAmount; // Total including tip
  const tendered = parseFloat(amountTendered) || 0;
  const changeDue = tendered - grandTotal; // Change is after tip
  const isSufficient = tendered >= grandTotal;

  // Generate smart bill suggestions based on grand total
  const suggestions = useMemo(() => {
    const bills = [10, 20, 50, 100];
    return bills.filter(
      (bill) => bill >= grandTotal || bill === 100 || bill === 50
    );
  }, [grandTotal]);

  const handleSelectAmount = (amount: number) => {
    setAmountTendered(amount.toString());
  };

  const handleSelectExact = () => {
    setAmountTendered(total.toFixed(2));
  };

  const handleTipPreset = (percentage: number) => {
    const calculatedTip = (percentage / 100) * total;
    setTipInput(calculatedTip.toFixed(2));
    setSelectedTipPreset(percentage);
  };

  const handleTipInputChange = (value: string) => {
    // Only allow valid currency format (numbers and one decimal point)
    if (/^\d*\.?\d{0,2}$/.test(value) || value === "") {
      setTipInput(value);
      setSelectedTipPreset(null); // Clear preset when manually typing
    }
  };

  const handleProcessCashPayment = () => {
    // Use the central handler to manage splits loop
    const tipAmount = parseFloat(tipInput) || 0;
    const amountTenderedNum = parseFloat(amountTendered) || 0;
    handlePaymentCompletion("Cash", tipAmount, {
      amountTendered: amountTenderedNum,
      isCashPriced: true, // Explicit cash pricing for dual-price compliance
    });
  };

  const handleBack = () => {
    setView("payment-method-selection");
  };

  return (
    <View className="flex-1 bg-[#212121]">
      <ScrollView
        contentContainerStyle={{ paddingBottom: 100 }}
        showsVerticalScrollIndicator={false}
      >
        {/* Header */}
        <View className="items-center py-6 pt-2">
          <View className="w-16 h-16 bg-green-900/20 rounded-full items-center justify-center mb-3">
            <Banknote size={32} color="#10B981" />
          </View>
          <Text className="text-2xl font-bold text-white">Cash Payment</Text>
          <Text className="text-gray-400">
            {activeSplit
              ? `Payment for ${activeSplit.customerName}`
              : "Enter amount received"}
          </Text>
        </View>

        {/* Main Card */}
        <View className="mx-4 bg-[#2A2A2A] rounded-2xl border border-[#333] overflow-hidden">
          {/* Top Section: Amount Due */}
          <View className="p-6 items-center border-b border-[#333]">
            <Text className="text-gray-400 uppercase tracking-widest text-xs font-bold mb-2">
              Total Due
            </Text>
            <Text className="text-4xl font-bold text-white">
              ${total.toFixed(2)}
            </Text>
          </View>

          {/* Middle Section: Input */}
          <View className="p-4 bg-[#262626]">
            <Text className="text-gray-400 mb-2 font-medium">
              Amount Received
            </Text>
            <View className="flex-row items-center bg-[#1A1A1A] border border-[#404040] rounded-xl px-4 h-16">
              <DollarSign size={20} color="#9CA3AF" />
              <TextInput
                value={amountTendered}
                onChangeText={setAmountTendered}
                placeholder="0.00"
                keyboardType="numeric"
                className="flex-1 text-2xl font-bold text-white ml-2 h-full"
                placeholderTextColor="#525252"
                autoFocus={false}
              />
              {amountTendered.length > 0 && (
                <TouchableOpacity onPress={() => setAmountTendered("")}>
                  <Delete size={20} color="#6B7280" />
                </TouchableOpacity>
              )}
            </View>

            {/* Quick Suggestions Grid */}
            <View className="flex-row flex-wrap gap-2 mt-4">
              <TouchableOpacity
                onPress={handleSelectExact}
                className="flex-grow bg-[#333] border border-[#404040] py-3 px-4 rounded-lg active:bg-[#404040]"
              >
                <Text className="text-blue-400 font-bold text-center">
                  Exact
                </Text>
              </TouchableOpacity>

              {suggestions.map((bill) => (
                <TouchableOpacity
                  key={bill}
                  onPress={() => handleSelectAmount(bill)}
                  className="flex-grow bg-[#333] border border-[#404040] py-3 px-4 rounded-lg active:bg-[#404040]"
                >
                  <Text className="text-white font-bold text-center">
                    ${bill}
                  </Text>
                </TouchableOpacity>
              ))}
            </View>
          </View>

          {/* Tip Section */}
          <View className="p-4 bg-[#262626] border-t border-[#333]">
            <Text className="text-gray-400 mb-2 font-medium">Tip Amount</Text>
            {/* Preset Tip Buttons */}
            <View className="flex-row gap-2 mb-3">
              {TIP_PRESETS.map((percent) => (
                <TouchableOpacity
                  key={percent}
                  onPress={() => handleTipPreset(percent)}
                  className={`flex-1 py-2 rounded-xl border ${selectedTipPreset === percent
                    ? "bg-blue-600 border-blue-500"
                    : "bg-[#333] border-[#404040]"
                    }`}
                >
                  <Text
                    className={`text-center font-bold ${selectedTipPreset === percent
                      ? "text-white"
                      : "text-gray-300"
                      }`}
                  >
                    {percent}%
                  </Text>
                  <Text
                    className={`text-center text-xs mt-1 ${selectedTipPreset === percent
                      ? "text-blue-200"
                      : "text-gray-500"
                      }`}
                  >
                    ${((percent / 100) * total).toFixed(2)}
                  </Text>
                </TouchableOpacity>
              ))}
            </View>
            {/* Custom Tip Input */}
            <View className="flex-row items-center bg-[#1A1A1A] border border-[#404040] rounded-xl px-4 h-16">
              <DollarSign size={20} color="#9CA3AF" />
              <TextInput
                value={tipInput}
                onChangeText={handleTipInputChange}
                placeholder="0.00"
                keyboardType="numeric"
                className="flex-1 text-2xl font-bold text-white ml-2 h-full"
                placeholderTextColor="#525252"
              />
            </View>
          </View>

          {/* Grand Total Section - Shows when tip is added */}
          <View className="p-4 bg-[#1A1A1A] border-t border-[#333]">
            <View className="flex-row justify-between items-center">
              <Text className="text-gray-400 text-sm">Bill Total</Text>
              <Text className="text-gray-400 text-sm">${total.toFixed(2)}</Text>
            </View>
            {tipAmount > 0 && (
              <View className="flex-row justify-between items-center mt-1">
                <Text className="text-green-400 text-sm">+ Tip</Text>
                <Text className="text-green-400 text-sm">
                  ${tipAmount.toFixed(2)}
                </Text>
              </View>
            )}
            <View className="flex-row justify-between items-center mt-2 pt-2 border-t border-[#333]">
              <Text className="text-white font-bold text-lg">Grand Total</Text>
              <Text className="text-blue-400 font-bold text-2xl">
                ${grandTotal.toFixed(2)}
              </Text>
            </View>
          </View>

          {/* Bottom Section: Change Calculation */}
          <View
            className={`p-6 flex-row justify-between items-center ${isSufficient ? "bg-green-900/10" : "bg-[#2A2A2A]"
              }`}
          >
            <Text className="text-lg font-medium text-gray-300">
              Change Due
            </Text>
            <Text
              className={`text-3xl font-bold ${isSufficient ? "text-green-400" : "text-gray-500"
                }`}
            >
              ${changeDue > 0 ? changeDue.toFixed(2) : "0.00"}
            </Text>
          </View>
        </View>
      </ScrollView>

      {/* Footer Buttons */}
      <View className="absolute bottom-0 left-0 right-0 bg-[#212121] pt-2 pb-10 border-t border-[#333]">
        <View className="flex-row gap-4 px-4">
          <TouchableOpacity
            onPress={handleBack}
            className="flex-1 py-4 bg-[#2A2A2A] rounded-xl border border-[#404040] flex-row items-center justify-center active:bg-[#333]"
          >
            <ArrowLeft size={20} color="#D1D5DB" className="mr-2" />
            <Text className="text-gray-300 font-semibold text-lg">Back</Text>
          </TouchableOpacity>

          <TouchableOpacity
            onPress={handleProcessCashPayment}
