            <Text
              className={`font-bold text-lg ${isSufficient || total === 0 ? "text-white" : "text-gray-500"
                }`}
            >
              {total === 0 ? "Complete Order" : "Finalize Payment"}
            </Text>
          </TouchableOpacity>
        </View>
      </View>
    </View>
  );
