                return sum + tip;
              }, 0);
              console.warn(
                "[PaymentSuccessView] completedPaymentInfo not set, using fallback calculation"
              );
            }

            console.log(
              "[PaymentSuccessView] totalPaid:",
              totalPaid,
              "from completedPaymentInfo:",
              !!completedPaymentInfo
            );

