                  >
                    <Text
                      className={`text-lg font-semibold ${
                        split.paymentType === "Card"
                          ? "text-white"
                          : "text-gray-300"
                      }`}
                    >
                      Card
                    </Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    onPress={() => handleSetPaymentType(split.id, "Cash")}
                    className={`py-2 px-4 rounded-lg border ${
                      split.paymentType === "Cash"
                        ? "border-blue-500 bg-blue-600"
                        : "border-gray-600"
                    }`}
                  >
                    <Text
                      className={`text-lg font-semibold ${
                        split.paymentType === "Cash"
