import {
  selectIsOpen,
  selectMode,
  useModifierSidebarStore,
} from "@/stores/useModifierSidebarStore";
import React, { memo, useEffect, useState } from "react";
import { Dimensions, StyleSheet, View } from "react-native";
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
} from "react-native-reanimated";
import ModifierScreen from "../menu/ModifierScreen";

const { width: SCREEN_WIDTH } = Dimensions.get("window");

// Panel width - covers the menu area (50% for compact Figure POS-style)
const PANEL_WIDTH = SCREEN_WIDTH * 0.50;

// Panel offset from right edge - positioned more to the left to not cover bill
const PANEL_RIGHT_OFFSET = SCREEN_WIDTH * 0.15; // 20% from right edge

/**
 * AttachedModifierPanel - Inline modifier panel for Figure POS-style interaction
 *
 * This component:
 * 1. Appears over the menu section (not fullscreen)
 * 2. Slides in from the right with spring animation (Reanimated)
 * 3. Keeps bill visible for context during editing
 * 4. Bill items are highlighted to show which one is being edited
 *
 * PERFORMANCE CRITICAL - PRE-MOUNTED ARCHITECTURE:
 * - ALWAYS renders (never unmounts) - eliminates 20-30ms mount overhead
 * - Visibility controlled via opacity/transform animations
 * - Uses Reanimated 2/3 for 60fps animations on UI thread
 * - Granular selectors prevent unnecessary re-renders
 * - Native driver animations (worklets)
 * - Memoized component prevents parent re-renders
 */
const AttachedModifierPanel: React.FC = () => {
  // Granular selectors for minimal re-renders
  const isOpen = useModifierSidebarStore(selectIsOpen);
  const mode = useModifierSidebarStore(selectMode);

  // Only show attached panel for non-fullscreen modes
  const shouldShowAttached = isOpen && mode !== "fullscreen";

  // Track if panel has ever been shown (for lazy content loading)
  const [hasBeenShown, setHasBeenShown] = useState(false);

  // Animation values (Reanimated shared values) - START in hidden position (off-screen right)
  const translateX = useSharedValue(PANEL_WIDTH + PANEL_RIGHT_OFFSET);
  const opacity = useSharedValue(0);
  const scale = useSharedValue(0.95);

  // Animated style for the panel (runs on UI thread)
  const panelAnimatedStyle = useAnimatedStyle(() => ({
    transform: [
      { translateX: -translateX.value },
      { scale: scale.value },
    ],
    opacity: opacity.value,
  }));

  // Animate panel in/out
  useEffect(() => {
    if (shouldShowAttached) {
      // Track that panel has been shown at least once
      if (!hasBeenShown) setHasBeenShown(true);

      // OPTIMIZED: Faster spring for instant response
      translateX.value = withSpring(0, {
        damping: 25,
        stiffness: 400,
        mass: 0.6,
      });
      opacity.value = withTiming(1, { duration: 80 });
      scale.value = withSpring(1, {
        damping: 25,
        stiffness: 400,
      });
    } else {
      // OPTIMIZED: Faster close animation (80ms instead of 150ms)
      // Slide off to the right (positive direction since panel is on right side)
      translateX.value = withTiming(PANEL_WIDTH + PANEL_RIGHT_OFFSET, { duration: 10 });
      opacity.value = withTiming(0, { duration: 10 });
      scale.value = withTiming(0.95, { duration: 10 });
    }
  }, [shouldShowAttached, hasBeenShown]);

  // ALWAYS RENDER - visibility controlled by animation values
  // pointerEvents controls touch interaction
  return (
    <Animated.View
      style={[styles.container, panelAnimatedStyle]}
      pointerEvents={shouldShowAttached ? "auto" : "none"}
    >
      {/* Main panel content - only render ModifierScreen if panel has been shown */}
      <View style={styles.panelContent}>
        {hasBeenShown && <ModifierScreen />}
      </View>
    </Animated.View>
  );
};

const styles = StyleSheet.create({
  container: {
    position: "absolute",
    top: 60,
    right: PANEL_RIGHT_OFFSET, // Positioned more to the left
    bottom: 60,
    width: PANEL_WIDTH,
    backgroundColor: "#1a1a1a",
    borderRadius: 16,
    borderWidth: 2,
    borderColor: "#3B82F6", // Blue accent border
    zIndex: 200,
    // Enhanced shadow for depth
    shadowColor: "#000",
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.5,
    shadowRadius: 12,
    elevation: 15,
    overflow: "hidden",
    height: "90%",
  },
  panelContent: {
    flex: 1,
    borderRadius: 14, // Match container for clipping
    overflow: "hidden",
  },
});

export default memo(AttachedModifierPanel);

import { CartItem } from "@/lib/types";
import {
  selectSetSelectedItemPosition,
  useModifierSidebarStore,
} from "@/stores/useModifierSidebarStore";
import { useOrderStore } from "@/stores/useOrderStore";
import { useItemSyncStatus, useItemSyncError } from "@/stores/useSyncStatusStore";
import { AlertCircle, Trash2 } from "lucide-react-native";
import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { ActivityIndicator, Text, TouchableOpacity, View } from "react-native";
import { Gesture, GestureDetector } from "react-native-gesture-handler";
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withTiming,
} from "react-native-reanimated";
import VoidItemDialog from "./VoidItemDialog";

interface BillItemProps {
  item: CartItem;
  isEditable?: boolean;
  isActive?: boolean; // Highlight when being edited in modifier panel
}

const DELETE_BUTTON_WIDTH = 90;

// Type for modifier structure
interface ModifierDisplay {
  categoryId: string;
  categoryName?: string;
  options: Array<{ id: string; name: string; price: number }>;
}

/**
 * ModifiersList - Memoized component for rendering item modifiers
 * PERFORMANCE: Extracted to avoid recreating nested maps on every render
 */
const ModifiersList = React.memo<{ modifiers: ModifierDisplay[] }>(
  ({ modifiers }) => (
    <View className="py-1">
      {modifiers.map((modifier, index) => (
        <View key={`mod-${index}`} className="ml-4">
          {modifier.options.length > 0 && (
            <View className="flex flex-row flex-wrap items-center mb-1">
              {modifier.categoryName && (
                <Text className="text-sm font-medium text-gray-300">
                  {modifier.categoryName}:
                </Text>
              )}
              {modifier.options.map((option, optionIndex) => (
                <View
                  key={`opt-${optionIndex}`}
                  className="flex-row justify-between items-center ml-1"
                >
                  <Text className="text-sm text-gray-200">
                    {option.name}
                    {optionIndex < modifier.options.length - 1 && " • "}
                  </Text>
                  {option.price > 0 && (
                    <Text className="text-sm font-medium ml-1 text-green-400">
                      +${option.price.toFixed(2)}
                      {optionIndex < modifier.options.length - 1 && ","}
                    </Text>
                  )}
                </View>
              ))}
            </View>
          )}
        </View>
      ))}
    </View>
  ),
  (prev, next) => {
    // Deep comparison for modifiers array - compare actual option content
    if (prev.modifiers.length !== next.modifiers.length) return false;

    for (let i = 0; i < prev.modifiers.length; i++) {
      const prevMod = prev.modifiers[i];
      const nextMod = next.modifiers[i];

      if (prevMod.categoryId !== nextMod.categoryId) return false;
      if (prevMod.options.length !== nextMod.options.length) return false;

      // Compare actual option IDs and names to detect changes
      for (let j = 0; j < prevMod.options.length; j++) {
        if (prevMod.options[j].id !== nextMod.options[j].id) return false;
        if (prevMod.options[j].name !== nextMod.options[j].name) return false;
      }
    }

    return true;
  }
);

const BillItemComponent: React.FC<BillItemProps> = ({ item, isEditable = false, isActive = false }) => {
  // FIXED: Use selectors instead of destructuring to avoid subscribing to entire store
  const activeOrderId = useOrderStore((s) => s.activeOrderId);
  const removeItemFromActiveOrder = useOrderStore((s) => s.removeItemFromActiveOrder);
  const openToView = useModifierSidebarStore((s) => s.openToView);
  const openToEdit = useModifierSidebarStore((s) => s.openToEdit);
  const setSelectedItemPosition = useModifierSidebarStore(selectSetSelectedItemPosition);

  // Phase 7D: Sync status from dedicated store (not from item)
  // This prevents re-renders of other components when sync status changes
  const syncStatus = useItemSyncStatus(item.id);
  const syncError = useItemSyncError(item.id);

  // Ref for position tracking (attached modifier panel positioning)
  const itemRef = useRef<View>(null);

  const translateX = useSharedValue(0);
  const [showVoidDialog, setShowVoidDialog] = useState(false);

  // Reset animation when item becomes voided
  useEffect(() => {
    if (item.is_voided) {
      translateX.value = withTiming(0);
    }
  }, [item.is_voided]);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ translateX: translateX.value }],
  }));

  // Delete button opacity - only visible when swiping
  const deleteButtonStyle = useAnimatedStyle(() => ({
    opacity:
      translateX.value < -10
        ? withTiming(1, { duration: 100 })
        : withTiming(0, { duration: 100 }),
  }));

  // Pan gesture to reveal delete
  // OPTIMIZED: Memoize gesture to prevent recreation on each render
  const MAX_LEFT = -DELETE_BUTTON_WIDTH;
  const pan = useMemo(
    () =>
      Gesture.Pan()
        .onUpdate((e) => {
          const next = Math.max(MAX_LEFT, Math.min(0, e.translationX));
          translateX.value = next;
        })
        .onEnd(() => {
          const shouldOpen = translateX.value < MAX_LEFT / 2;
          translateX.value = withTiming(shouldOpen ? MAX_LEFT : 0);
        })
        .activeOffsetX([-20, 20]) // Only activate if horizontal movement exceeds 20px
        .failOffsetY([-20, 20]), // Fail if vertical movement exceeds 20px
    [translateX]
  );

  // Check if item is in draft/new state (simple delete) or in kitchen (needs void reason)
  const isKitchenItem =
    item.kitchen_status === "sent" ||
    item.kitchen_status === "ready" ||
    item.kitchen_status === "served";

  const handleDelete = () => {
    if (!activeOrderId) return;

    if (item.isDraft || !isKitchenItem) {
      // Draft or new item - animate back then remove
      translateX.value = withTiming(0);
      // Delay removal to allow animation to complete
      setTimeout(() => {
        removeItemFromActiveOrder(item.id);
      }, 50);
    } else {
      // Kitchen item - show void reason dialog
      setShowVoidDialog(true);
    }
  };

  const handleConfirmVoid = (reason: string) => {
    // Reset animation first, before any state changes
    translateX.value = withTiming(0);
    setShowVoidDialog(false);

    // Delay the void operation to allow animation to complete
    if (activeOrderId) {
      setTimeout(() => {
        removeItemFromActiveOrder(item.id, reason);
      }, 50);
    }
  };

  const handleCancelVoid = () => {
    setShowVoidDialog(false);
    // Reset slide position
    translateX.value = withTiming(0);
  };

  // Capture item position for attached modifier panel positioning
  const captureItemPosition = useCallback(() => {
    if (itemRef.current) {
      itemRef.current.measureInWindow((x, y, width, height) => {
        setSelectedItemPosition({
          y,
          height,
          absoluteY: y, // Absolute Y position on screen
        });
      });
    }
  }, [setSelectedItemPosition]);

  const handleNotesPress = (e: any) => {
    e.stopPropagation();

    // Capture position before opening modifier for attached panel positioning
    captureItemPosition();

    if (isEditable) {
      // Use attached panel mode (not fullscreen) to show arrow pointing to bill item
      openToEdit(item, activeOrderId);
    } else {
      openToView(item, activeOrderId);
    }
  };

  // Check if item has any modifiers to show
  const hasModifiers =
    (item.customizations.modifiers &&
      item.customizations.modifiers.length > 0) ||
    item.customizations.notes;

  // Check if item is voided
  const isVoided = item.is_voided === true;

  return (
    <View
      ref={itemRef}
      className={`rounded-xl overflow-hidden ${
        isActive
          ? "border-2 border-blue-400 bg-blue-500/5"
          : isVoided
          ? "border bg-[#2a2020] border-red-900/50 opacity-60"
          : "border bg-[#303030] border-gray-600"
      }`}
      style={isActive ? { shadowColor: '#3B82F6', shadowOffset: { width: 0, height: 0 }, shadowOpacity: 0.5, shadowRadius: 8, elevation: 8 } : undefined}
    >
      {isEditable && !isVoided && (
        <Animated.View
          style={deleteButtonStyle}
          className="absolute top-0 right-1 h-full justify-center items-end self-center z-10"
        >
          <TouchableOpacity
            onPress={handleDelete}
            className="w-20 h-[85%] bg-red-500 items-center rounded-lg justify-center"
          >
            <Trash2 color="white" size={20} />
          </TouchableOpacity>
        </Animated.View>
      )}

      <GestureDetector gesture={isVoided ? Gesture.Pan() : pan}>
        <Animated.View
          style={isVoided ? undefined : animatedStyle}
          className={isVoided ? "bg-[#2a2020]" : "bg-[#303030] z-20"}
        >
          <TouchableOpacity
            onPress={isVoided ? undefined : handleNotesPress}
            activeOpacity={isVoided ? 1 : 0.9}
            disabled={isVoided}
          >
            <View className="flex-row items-center py-2 px-2">
              <View className="flex-1">
                <View className="flex-row items-center flex-wrap">
                  {isVoided && (
                    <View className="bg-red-600 px-2 py-0.5 rounded mr-2">
                      <Text className="text-white text-xs font-bold">VOID</Text>
                    </View>
                  )}
                  {/* Paid status badge */}
                  {!isVoided &&
                    item.paidQuantity > 0 &&
                    item.paidQuantity >= item.quantity && (
                      <View className="bg-green-600/20 px-2 py-0.5 rounded mr-2">
                        <Text className="text-green-400 text-xs font-bold">
                          PAID
                        </Text>
                      </View>
                    )}
                  {!isVoided &&
                    item.paidQuantity > 0 &&
                    item.paidQuantity < item.quantity && (
                      <View className="bg-yellow-600/20 px-2 py-0.5 rounded mr-2">
                        <Text className="text-yellow-400 text-xs font-bold">
                          {item.paidQuantity}/{item.quantity} PAID
                        </Text>
                      </View>
                    )}
                  <Text
                    className={`font-semibold text-base ${
                      isVoided ? "text-gray-500 line-through" : "text-white"
                    }`}
                  >
                    {item.name}
                  </Text>
                  {/* Sync status indicator - Phase 7D: from dedicated store */}
                  {syncStatus === "pending" ||
                  syncStatus === "syncing" ? (
                    <ActivityIndicator
                      size={10}
                      color="#60A5FA"
                      style={{ marginLeft: 12 }}
                    />
                  ) : syncStatus === "failed" ? (
                    <AlertCircle
                      size={16}
                      color="#EF4444"
                      style={{ marginLeft: 6 }}
                    />
                  ) : null}
                  <Text
                    className={`text-sm ml-3 ${
                      isVoided ? "text-gray-600 line-through" : "text-gray-300"
                    }`}
                  >
                    {item.quantity} X
                  </Text>
                </View>
                {isVoided && item.void_reason && (
                  <Text className="text-red-400/70 text-xs mt-1 italic">
                    Reason: {item.void_reason}
                  </Text>
                )}
                <View className="flex-row items-center">
                  {/* {!item.isDraft && (...)} */}
                </View>
              </View>
              <Text
                className={`font-semibold text-lg ${
                  isVoided ? "text-gray-500 line-through" : "text-white"
                }`}
              >
                ${(item.price * item.quantity).toFixed(2)}
              </Text>
            </View>

            {hasModifiers && (
              <Animated.View className="overflow-hidden">
                <View className="px-2 border-t border-gray-600">
                  {/* OPTIMIZED: Use memoized ModifiersList component */}
                  {item.customizations.modifiers &&
                    item.customizations.modifiers.length > 0 && (
                      <ModifiersList modifiers={item.customizations.modifiers} />
                    )}

                  {item.customizations.notes && (
                    <View className="py-0.5">
                      <Text className="text-sm text-gray-300">Notes:</Text>
                      <Text className="text-sm text-gray-200 ml-2 italic">
                        {item.customizations.notes}
                      </Text>
                    </View>
                  )}
                </View>
              </Animated.View>
            )}
          </TouchableOpacity>
        </Animated.View>
      </GestureDetector>

      {/* Void Item Dialog */}
      <VoidItemDialog
        isOpen={showVoidDialog}
        itemName={item.name}
        onConfirm={handleConfirmVoid}
        onCancel={handleCancelVoid}
      />
    </View>
  );
};

// OPTIMIZED: Memoize to prevent re-renders when parent updates
// Phase 7D: sync_status is now in useSyncStatusStore, not on item
// BillItem re-renders for sync status changes via its own useItemSyncStatus subscription
const BillItem = React.memo(BillItemComponent, (prev, next) => {
  // Return true if props are equal (skip re-render)
  // Quick checks first
  // Note: sync_status removed - it's now managed by useSyncStatusStore
  if (
    prev.item.id !== next.item.id ||
    prev.item.quantity !== next.item.quantity ||
    prev.item.price !== next.item.price ||
    prev.item.is_voided !== next.item.is_voided ||
    prev.item.void_reason !== next.item.void_reason ||
    prev.item.paidQuantity !== next.item.paidQuantity ||
    prev.item.kitchen_status !== next.item.kitchen_status ||
    prev.item.isDraft !== next.item.isDraft ||
    prev.item.customizations?.notes !== next.item.customizations?.notes ||
    prev.isEditable !== next.isEditable ||
    prev.isActive !== next.isActive
  ) {
    return false;
  }

  // Deep compare modifiers - check actual option IDs, not just length
  const prevModifiers = prev.item.customizations?.modifiers || [];
  const nextModifiers = next.item.customizations?.modifiers || [];

  if (prevModifiers.length !== nextModifiers.length) return false;

  for (let i = 0; i < prevModifiers.length; i++) {
    const prevMod = prevModifiers[i];
    const nextMod = nextModifiers[i];

    if (prevMod.categoryId !== nextMod.categoryId) return false;
    if (prevMod.options.length !== nextMod.options.length) return false;

    // Compare actual option IDs to detect when options change
    for (let j = 0; j < prevMod.options.length; j++) {
      if (prevMod.options[j].id !== nextMod.options[j].id) return false;
    }
  }

  return true;
});

export default BillItem;

import { useToast } from "@/contexts/ToastContext";
import { CartItem } from "@/lib/types";
import { getAutoRetryCount, isAutoRetryInProgress } from "@/services/offlineSyncService";
import { useActiveOrderTotals } from "@/stores/selectors/orderSelectors";
import { useDineInStore } from "@/stores/useDineInStore";
import { useEmployeeStore } from "@/stores/useEmployeeStore";
import { useOrderStore } from "@/stores/useOrderStore";
import { usePaymentStore } from "@/stores/usePaymentStore";
import { useTimeclockStore } from "@/stores/useTimeclockStore";
import { BottomSheetMethods } from "@gorhom/bottom-sheet/lib/typescript/types";
import { AlertTriangle, Clock, Plus, RefreshCw, Send, WifiOff } from "lucide-react-native";
import React, { useCallback, useEffect, useMemo, useState } from "react";
import { ActivityIndicator, Text, TouchableOpacity, View } from "react-native";
import BillSummary from "./BillSummary";
import DiscountBottomSheet from "./DiscountBottomSheet";
import DiscountOverlay from "./DiscountOverlay";
import OrderDetails from "./OrderDetails";
import Totals from "./Totals";

// OPTIMIZED: Memoize to prevent re-renders when parent updates
const BillSectionContent = React.memo(
  ({ cart }: { cart: CartItem[] }) => {
    const [expandedItemId, setExpandedItemId] = useState<string | null>(null);

    const handleToggleExpand = useCallback((itemId: string) => {
      setExpandedItemId((prev) => (prev === itemId ? null : itemId));
    }, []);

    return (
      <>
        <BillSummary
          cart={cart}
          expandedItemId={expandedItemId}
          onToggleExpand={handleToggleExpand}
        />
        <Totals cart={cart} />
      </>
    );
  },
  (prev, next) => prev.cart === next.cart
);

const BillSection = ({
  showOrderDetails = true,
  showPlaymentActions = true,
  moreOptionsSheetRef,
  discountSheetRef,
}: {
  showOrderDetails?: boolean;
  showPlaymentActions?: boolean;
  moreOptionsSheetRef?: React.RefObject<BottomSheetMethods>;
  discountSheetRef?: React.RefObject<BottomSheetMethods>;
}) => {
  // O(1) lookups with individual selectors - only re-renders when specific values change
  const activeOrderId = useOrderStore((state) => state.activeOrderId);

  // FIXED: Only subscribe to the active order, not the entire ordersById object
  const activeOrder = useOrderStore((state) =>
    state.activeOrderId ? state.ordersById[state.activeOrderId] : undefined
  );

  // Phase 7: Use derived selector instead of 3 individual store selectors
  const orderTotals = useActiveOrderTotals();

  const startNewOrder = useOrderStore((state) => state.startNewOrder);
  const sendNewItemsToKitchen = useOrderStore(
    (state) => state.sendNewItemsToKitchen
  );
  const assignOrderToTable = useOrderStore((state) => state.assignOrderToTable);
  const setActiveOrder = useOrderStore((state) => state.setActiveOrder);
  const getSyncStatus = useOrderStore((state) => state.getSyncStatus);
  const retryFailedSyncs = useOrderStore((state) => state.retryFailedSyncs);

  // Offline sync state
  const isOnline = useOrderStore((state) => state.isOnline);
  const pendingSyncCount = useOrderStore((state) => state.pendingSyncCount);

  const { selectedTable, clearSelectedTable } = useDineInStore();
  const { activeEmployeeId } = useEmployeeStore();
  const { checkEmployeeInShift, showClockInWall } = useTimeclockStore();
  const { show } = useToast();

  // Memoize computed values to prevent unnecessary recalculations
  const cart = useMemo(() => activeOrder?.items || [], [activeOrder?.items]);
  const hasDraftItems = useMemo(
    () => cart.some((item) => item.isDraft),
    [cart]
  );
  const newItemsCount = useMemo(
    () =>
      cart.filter(
        (item) => item.kitchen_status === "new" || !item.kitchen_status
      ).length,
    [cart]
  );

  // Get sync status for the active order
  const syncStatus = useMemo(
    () =>
      activeOrderId
        ? getSyncStatus(activeOrderId)
        : { pending: 0, failed: 0, synced: 0 },
    [activeOrderId, getSyncStatus, cart] // Include cart to recompute when items change
  );
  const hasPendingSyncs = syncStatus.pending > 0;
  const hasFailedSyncs = syncStatus.failed > 0;

  // Track auto-retry state for UI indicator
  const [autoRetryState, setAutoRetryState] = useState({ isRetrying: false, count: 0 });

  // Poll for auto-retry status when there are failed syncs
  useEffect(() => {
    if (!hasFailedSyncs && !hasPendingSyncs) {
      setAutoRetryState({ isRetrying: false, count: 0 });
      return;
    }

    // Check auto-retry status periodically
    const checkAutoRetry = () => {
      setAutoRetryState({
        isRetrying: isAutoRetryInProgress(),
        count: getAutoRetryCount(),
      });
    };

    checkAutoRetry();
    const interval = setInterval(checkAutoRetry, 2000); // Check every 2 seconds

    return () => clearInterval(interval);
  }, [hasFailedSyncs, hasPendingSyncs, syncStatus]);

  // Calculate the amount to display on the Pay button
  // Phase 7: Now uses derived selector which already prioritizes backend values
  const displayBalanceDue = useMemo(() => {
    if (!orderTotals) return 0;

    // Derived selector's amountDue already prioritizes backend amount_due
    // For new orders without payments, use total
    if (!activeOrder?.payments?.length) {
      return orderTotals.total;
    }

    return orderTotals.amountDue;
  }, [orderTotals, activeOrder?.payments]);

  // Check if order is partially paid (has payments but not fully paid)
  const isPartiallyPaid = useMemo(() => {
    return (
      (activeOrder?.payments?.length ?? 0) > 0 &&
      activeOrder?.paid_status !== "Paid"
    );
  }, [activeOrder?.payments, activeOrder?.paid_status]);

  // Calculate cash savings for dual-price display
  // Phase 7: Now uses derived selector which already prioritizes backend values
  // console.log("orderTotals", orderTotals);
  const { cashBalanceDue, cashSavings } = useMemo(() => {
    if (!orderTotals) {
      return { cashBalanceDue: 0, cashSavings: 0 };
    }

    // if (!activeOrder?.payments?.length) {
    //   return { cashBalanceDue: orderTotals.cashAmountDue, cashSavings: 0 };
    // }
    // Derived selector's cashAmountDue already prioritizes backend cash_amount_due
    const cashDue = orderTotals.cashAmountDue;
    const savings = displayBalanceDue - cashDue;
    return {
      cashBalanceDue: cashDue,
      cashSavings: savings > 0.01 ? savings : 0,
    };
  }, [orderTotals, displayBalanceDue]);

  const [isProcessing, setIsProcessing] = useState(false);
  const isPaymentSheetOpen = usePaymentStore((state) => state.isOpen);

  // Effect to reset processing state when payment sheet opens
  useEffect(() => {
    if (isPaymentSheetOpen) {
      setIsProcessing(false);
    }
  }, [isPaymentSheetOpen]);

  // Memoize pay button disabled state - prevents clicking when balance due is 0 or no items
  const isPayButtonDisabled = useMemo(
    () =>
      !activeOrder ||
      cart.length === 0 ||
      hasDraftItems ||
      displayBalanceDue <= 0 ||
      isPaymentSheetOpen ||
      isProcessing,
    [
      activeOrder,
      cart.length,
      hasDraftItems,
      displayBalanceDue,
      isPaymentSheetOpen,
      isProcessing,
    ]
  );
  const [isDiscountOverlayVisible, setDiscountOverlayVisible] = useState(false);

  // OPTIMIZED: Wrap callbacks with useCallback to prevent recreation on each render
  const handleOpenDiscounts = useCallback(() => {
    setDiscountOverlayVisible(true);
  }, []);

  const handleCloseDiscounts = useCallback(() => {
    setDiscountOverlayVisible(false);
  }, []);

  const handleOpenMoreOptions = useCallback(() => {
    moreOptionsSheetRef?.current?.expand();
  }, [moreOptionsSheetRef]);

  const handlePayClick = () => {
    // Safety guard: Prevent payment if button should be disabled
    if (isPayButtonDisabled || isProcessing || isPaymentSheetOpen) {
      return;
    }

    // Set processing state immediately to prevent double taps
    setIsProcessing(true);

    // Failsafe: Reset processing state after 2 seconds if sheet fails to open
    setTimeout(() => {
      setIsProcessing(false);
    }, 2000);

    if (!checkEmployeeInShift(activeEmployeeId!)) {
      showClockInWall();
      setIsProcessing(false);
      return;
    }
    if (hasDraftItems) {
      show({
        title: "Unconfirmed Items",
        message:
          "Please confirm or remove any customized items before proceeding to payment.",
        type: "error",
      });
      setIsProcessing(false);
      return;
    }
    // Additional safety check for zero balance due
    if (displayBalanceDue <= 0) {
      show({
        title: "Invalid Amount",
        message:
          activeOrder?.paid_status === "Paid"
            ? "This order is already fully paid."
            : "Cannot process payment for $0.00. Please add items to the order.",
        type: "error",
      });
      setIsProcessing(false);
      return;
    }
    // Directly open the payment bottom sheet to the method selection
    usePaymentStore.getState().open("Card", activeOrder?.service_location_id || null, "payment-method-selection");
  };

  const handleSendToKitchen = () => {
    if (!checkEmployeeInShift(activeEmployeeId!)) {
      showClockInWall();
      return;
    }
    if (hasDraftItems) {
      show({
        title: "Unconfirmed Items",
        message:
          "Please confirm or remove any customized items before sending the order to the kitchen.",
        type: "error",
      });
      return;
    }

    if (activeOrder?.order_type === "dine_in" && selectedTable) {
      assignOrderToTable(activeOrderId!, selectedTable.id);
      // Table session status updates are now handled through session-based APIs
      clearSelectedTable();
    }
    sendNewItemsToKitchen();
    const newOrder = startNewOrder();
    setActiveOrder(newOrder.id);
  };

  // OPTIMIZED: Wrap callback with useCallback
  const handleStartNewOrder = useCallback(() => {
    const newOrder = startNewOrder();
    setActiveOrder(newOrder.id);
  }, [startNewOrder, setActiveOrder]);

  if (!activeOrderId)
    return (
      <View className="w-1/3 items-center justify-center bg-[#212121] p-8 ">
        <Text className="text-xl font-semibold text-white mb-4">
          No Active Order
        </Text>
        <TouchableOpacity
          className="px-6 py-3 bg-blue-600 rounded-lg shadow-md active:opacity-80"
          onPress={() => {
            startNewOrder();
          }}
        >
          <Text className="text-white text-xl font-bold tracking-wide">
            Start New Order
          </Text>
        </TouchableOpacity>
      </View>
    );
  // Handle retry failed syncs
  const handleRetryFailedSyncs = async () => {
    if (activeOrderId) {
      await retryFailedSyncs(activeOrderId);
    }
  };

  return (
    <View className="w-1/3 bg-[#303030]">
      {showOrderDetails && <OrderDetails />}

      {/* Offline / Sync Status Banner */}
      {(!isOnline || hasFailedSyncs || pendingSyncCount > 0) && (
        <View className="px-4 py-2 bg-[#212121]">
          {/* Offline Mode Banner */}
          {!isOnline && (
            <View className="flex-row items-center justify-center bg-amber-600 px-3 py-2 rounded-lg mb-2">
              <WifiOff size={16} color="#FFFFFF" />
              <Text className="text-white text-sm font-medium ml-2">
                Offline Mode{" "}
                {pendingSyncCount > 0 ? `• ${pendingSyncCount} pending` : ""}
              </Text>
            </View>
          )}

          {/* Failed Syncs Banner with Auto-Retry Indicator (only when online) */}
          {isOnline && hasFailedSyncs && (
            <TouchableOpacity
              onPress={handleRetryFailedSyncs}
              disabled={autoRetryState.isRetrying}
              className={`flex-row items-center justify-between px-3 py-2 rounded-lg ${autoRetryState.isRetrying ? "bg-amber-600/80" : "bg-red-600/80"
                }`}
              activeOpacity={0.7}
            >
              <View className="flex-row items-center">
                {autoRetryState.isRetrying ? (
                  <>
                    <ActivityIndicator size="small" color="#FFFFFF" />
                    <Text className="text-white text-sm font-medium ml-2">
                      Auto-retrying {autoRetryState.count} operation{autoRetryState.count > 1 ? "s" : ""}...
                    </Text>
                  </>
                ) : (
                  <>
                    <AlertTriangle size={16} color="#FFFFFF" />
                    <Text className="text-white text-sm font-medium ml-2">
                      {syncStatus.failed} item{syncStatus.failed > 1 ? "s" : ""} failed to sync
                    </Text>
                  </>
                )}
                <AlertTriangle size={16} color="#FFFFFF" />
                <Text className="text-white text-sm font-medium ml-2">
                  {syncStatus.failed} item{syncStatus.failed > 1 ? "s" : ""}{" "}
                  failed to sync
                </Text>
              </View>
              <View className="flex-row items-center">
                <RefreshCw size={14} color="#FFFFFF" />
                <Text className="text-white text-xs ml-1">Retry</Text>
              </View>
              {!autoRetryState.isRetrying && (
                <View className="flex-row items-center">
                  <RefreshCw size={14} color="#FFFFFF" />
                  <Text className="text-white text-xs ml-1">Retry Now</Text>
                </View>
              )}
            </TouchableOpacity>
          )}

          {/* Pending Payment Syncs Banner (only when online and has pending payments) */}
          {isOnline && !hasFailedSyncs && activeOrder?.payments?.some(p => p.sync_status === "pending") && (
            <View className="flex-row items-center justify-center bg-amber-600/70 px-3 py-2 rounded-lg">
              <Clock size={16} color="#FFFFFF" />
              <Text className="text-white text-sm font-medium ml-2">
                Payment pending sync...
              </Text>
            </View>
          )}

          {/* Syncing Indicator (only when online and syncing) */}
          {isOnline && !hasFailedSyncs && hasPendingSyncs && (
            <View className="flex-row items-center justify-center bg-blue-600/60 px-3 py-2 rounded-lg">
              <ActivityIndicator size="small" color="#FFFFFF" />
              <Text className="text-white text-sm font-medium ml-2">
                Syncing {syncStatus.pending} item
                {syncStatus.pending > 1 ? "s" : ""}...
              </Text>
            </View>
          )}
        </View>
      )}

      <BillSectionContent cart={cart} />
      <View className="py-3 px-4 bg-[#212121]">
        <View className="flex-row gap-4">
          {/* Start New Order Button */}
          <TouchableOpacity
            onPress={handleStartNewOrder}
            className="flex-1 py-1.5 flex-row items-center justify-center gap-2 bg-[#303030] rounded-xl border border-gray-600"
          >
            <Plus color="#22c55e" size={20} />
            <Text className="text-center text-lg font-bold text-white">
              New Order
            </Text>
          </TouchableOpacity>

          {/* Send to Kitchen Button - matching previous colors but with new layout */}
          <TouchableOpacity
            className={`flex-1 py-1.5 px-2 flex-row items-center justify-center gap-2 rounded-xl bg-[#212121] border border-gray-600 ${
              newItemsCount === 0 || hasDraftItems ? "opacity-50" : ""
            }`}
            disabled={newItemsCount === 0 || hasDraftItems}
            onPress={handleSendToKitchen}
            activeOpacity={0.85}
          >
            {hasPendingSyncs ? (
              <ActivityIndicator size="small" color="#60A5FA" />
            ) : null}
            <Text className="text-center text-lg font-bold text-white">
              Send to Kitchen ({newItemsCount})
            </Text>
            <Send size={18} color="#9CA3AF" />
          </TouchableOpacity>
        </View>
      </View>
      <View className="bg-[#212121]">
        <View className="h-[0.5px] w-[90%] self-center bg-gray-600" />
      </View>
      {showPlaymentActions && (
        <View className="py-3 px-4 bg-[#212121]">
          <View className="flex-row gap-4">
            <TouchableOpacity
              onPress={handleOpenMoreOptions}
              className="flex-1 py-1.5 bg-[#303030] rounded-xl border border-gray-600"
            >
              <Text className="text-center text-lg font-bold text-white">
                More
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              onPress={handlePayClick}
              disabled={isPayButtonDisabled}
              className={`flex-1 py-1.5 rounded-xl flex-row items-center justify-center gap-2 ${
                isPayButtonDisabled
                  ? "bg-gray-500"
                  : isPartiallyPaid
                  ? "bg-green-600"
                  : "bg-blue-600"
              }`}
            >
              {hasPendingSyncs || isProcessing ? (
                <ActivityIndicator size="small" color="#FFFFFF" />
              ) : null}
              <Text
                className={`text-center text-lg font-bold ${
                  isPayButtonDisabled ? "text-gray-400" : "text-white"
                }`}
              >
                {isPartiallyPaid
                  ? `Pay Due $${displayBalanceDue.toFixed(2)}`
                  : `Pay $${displayBalanceDue.toFixed(2)}`}
              </Text>
            </TouchableOpacity>
          </View>
          {/* Cash Discount Option */}

          <View className="mt-2 px-2 py-1.5 bg-green-900/20 rounded-lg border border-green-600/30">
            <Text className="text-center text-sm text-green-400">
              Pay cash: ${cashBalanceDue?.toFixed(2)} (save $
              {cashSavings?.toFixed(2)})
            </Text>
          </View>
        </View>
      )}
      <DiscountOverlay
        isVisible={isDiscountOverlayVisible}
        onClose={handleCloseDiscounts}
      />
      <DiscountBottomSheet
        ref={discountSheetRef}
        onClose={() => discountSheetRef?.current?.close()}
      />
    </View>
  );
};

export default BillSection;

import { OrderProfile } from "@/lib/types";
import { useOrderStore } from "@/stores/useOrderStore";
import {
  CheckCircle,
  CreditCard,
  Loader2,
  MoreHorizontal,
  Percent,
  RotateCcw,
  Trash2,
} from "lucide-react-native";
import React, { useEffect, useRef } from "react";
import { ActivityIndicator, Animated, Text, TouchableOpacity, View } from "react-native";

interface BottomActionBarProps {
  activeOrder: OrderProfile | undefined;
  onPressMore: () => void;
  onPressTotal: () => void;
  onPressReopenCheck: () => void;
  onPressCloseCheck: () => void;
  onPressClearTable: () => void;
  onPressDiscount: () => void;
  totalDisplayAmount: number;
  isFullyPaid?: boolean; // LOCAL-FIRST: Use local calculation from parent
  paymentCount?: number; // Number of payments made for displaying badge
}

const BottomActionBar: React.FC<BottomActionBarProps> = ({
  activeOrder,
  onPressMore,
  onPressTotal,
  onPressReopenCheck,
  onPressCloseCheck,
  onPressClearTable,
  onPressDiscount,
  totalDisplayAmount,
  isFullyPaid: isFullyPaidProp,
  paymentCount,
}) => {
  // Subscribe to payment sync status for loading state
  const paymentSyncStatus = useOrderStore((state) => state.paymentSyncStatus);
  const isSyncing = paymentSyncStatus === "syncing";

  // Pulsing animation for syncing state
  const pulseAnim = useRef(new Animated.Value(1)).current;

  useEffect(() => {
    if (isSyncing) {
      Animated.loop(
        Animated.sequence([
          Animated.timing(pulseAnim, {
            toValue: 0.6,
            duration: 500,
            useNativeDriver: true,
          }),
          Animated.timing(pulseAnim, {
            toValue: 1,
            duration: 500,
            useNativeDriver: true,
          }),
        ])
      ).start();
    } else {
      pulseAnim.setValue(1);
    }
  }, [isSyncing]);

  // Shared styling: flex-1 ensures they all take equal width
  const buttonBaseClass =
    "flex-1 flex-row items-center justify-center h-12 px-2 rounded-lg gap-2";

  const renderDefaultButtons = () => (
    <>
      {/* Discount Button: Indigo (Distinct from Blue, fits dark theme) */}
      {/* <TouchableOpacity
        onPress={onPressDiscount}
        className={`${buttonBaseClass} bg-indigo-600`}
        activeOpacity={0.7}
      >
        <Percent size={18} color="white" />
        <Text className="font-semibold text-white text-base">Discount</Text>
      </TouchableOpacity> */}

      {/* Total Button: Blue (Primary Action), Green Close Check (balance $0), or Gray (Syncing) */}
      {(() => {
        // Check if balance is zero (order is fully paid but may be reopened)
        const hasItems = (activeOrder?.items?.length ?? 0) > 0;
        const isBalanceZero = hasItems && totalDisplayAmount <= 0 && !isSyncing;

        // Show syncing state with pulsing animation
        if (isSyncing) {
          return (
            <Animated.View
              style={{ opacity: pulseAnim, flex: 1 }}
            >
              <View
                className={`${buttonBaseClass} bg-gray-600`}
              >
                <ActivityIndicator size="small" color="white" />
                <Text
                  className="font-semibold text-white text-base"
                  numberOfLines={1}
                >
                  Syncing...
                </Text>
              </View>
            </Animated.View>
          );
        }

        // When balance is $0, show payment status badge (non-clickable indicator)
        // Close Check action has been moved to the More button's bottom sheet
        if (isBalanceZero) {
          const paymentsText = paymentCount
            ? `${paymentCount} payment${paymentCount > 1 ? 's' : ''} made`
            : "Partially Paid";

          return (
            <View
              className={`${buttonBaseClass} bg-emerald-600/20 border border-emerald-500`}
            >
              <CheckCircle size={18} color="#10b981" />
              <Text
                className="font-semibold text-emerald-400 text-base"
                numberOfLines={1}
              >
                {paymentsText}
              </Text>
            </View>
          );
        }

        // Normal case - show Total amount
        return (
          <TouchableOpacity
            onPress={onPressTotal}
            className={`${buttonBaseClass} bg-blue-600`}
            activeOpacity={0.7}
          >
            <Text
              className="font-semibold text-white text-base"
              numberOfLines={1}
            >
              ${totalDisplayAmount.toFixed(2)}
            </Text>
            <CreditCard size={18} color="white" />
          </TouchableOpacity>
        );
      })()}
    </>
  );

  const renderPaidButtons = () => (
    <>
      {/* Close Check: Emerald Green (Success/Finish) */}
      <TouchableOpacity
        onPress={onPressCloseCheck}
        className={`${buttonBaseClass} bg-emerald-600`}
        activeOpacity={0.7}
      >
        <CheckCircle size={18} color="white" />
        <Text className="font-semibold text-white text-base">Close</Text>
      </TouchableOpacity>

      {/* Clear Table: Red (Destructive) */}
      <TouchableOpacity
        onPress={onPressClearTable}
        className={`${buttonBaseClass} bg-red-900/40 border border-red-500`}
        activeOpacity={0.7}
      >
        <Trash2 size={18} color="#fca5a5" />
        <Text className="font-semibold text-red-100 text-base">Clear</Text>
      </TouchableOpacity>
    </>
  );

  const renderClosedButtons = () => (
    <>
      {/* Reopen: Amber (Undo/Correction) */}
      <TouchableOpacity
        onPress={onPressReopenCheck}
        className={`${buttonBaseClass} bg-amber-600`}
        activeOpacity={0.7}
      >
        <RotateCcw size={18} color="white" />
        <Text className="font-semibold text-white text-base">Reopen</Text>
      </TouchableOpacity>

      {/* Clear Table: Red */}
      <TouchableOpacity
        onPress={onPressClearTable}
        className={`${buttonBaseClass} bg-red-900/40 border border-red-500`}
        activeOpacity={0.7}
      >
        <Trash2 size={18} color="#fca5a5" />
        <Text className="font-semibold text-red-100 text-base">Clear</Text>
      </TouchableOpacity>
    </>
  );

  const renderButtons = () => {
    if (!activeOrder) {
      return renderDefaultButtons();
    }

    // LOCAL-FIRST: Prioritize local isFullyPaid calculation from parent
    // This ensures buttons update immediately without waiting for backend sync
    if (isFullyPaidProp) {
      return renderClosedButtons(); // Reopen + Clear - order is fully paid locally
    }

    // Fallback to backend status if local calculation not provided
    if (activeOrder.check_status === "Closed") {
      return renderClosedButtons();
    }
    if (activeOrder.paid_status === "Paid") {
      return renderClosedButtons(); // Changed from renderPaidButtons to show Reopen + Clear
    }
    return renderDefaultButtons();
  };

  return (
    // Container: Removed "justify-between", added "gap-3"
    <View className="flex-row items-center py-4 px-4 bg-[#303030] border-t border-gray-700 gap-3">
      {/* More Button: Now has text and uses flex-1 */}
      <TouchableOpacity
        onPress={onPressMore}
        className={`${buttonBaseClass} bg-[#212121] border border-gray-600`}
        activeOpacity={0.7}
      >
        <MoreHorizontal size={20} color="white" />
        <Text className="font-semibold text-white text-base">More</Text>
      </TouchableOpacity>

      {/* Dynamic Buttons (Discount/Total or Close/Clear) */}
      {renderButtons()}
    </View>
  );
};

export default BottomActionBar;

import { CartItem, OrderProfile } from "@/lib/types";
import React, { useEffect, useMemo, useRef, useState } from "react";
import { ScrollView, Text, TouchableOpacity, View } from "react-native";
import { Gesture, GestureDetector } from "react-native-gesture-handler";
import Animated, {
  FadeIn,
  FadeOut,
  LinearTransition,
  runOnJS,
  useAnimatedStyle,
  useSharedValue,
  withSequence,
  withSpring,
  withTiming,
} from "react-native-reanimated";
import BillItem from "./BillItem";

// --- Types ---
interface CourseAccordionProps {
  activeOrder: OrderProfile | undefined;
  itemCourseMap?: Record<string, number>;
  sentCourses?: Record<number, boolean>;
  currentCourse?: number;
  onSelectCourse?: (course: number | null) => void;
  onPressStartNewCourse: () => void;
  onDoubleTapCourse: (courseId: number) => void;
}

interface CourseGroupProps {
  courseId: number;
  items: CartItem[];
  isExpanded: boolean;
  isSent: boolean;
  isCurrent: boolean;
  onToggle: (id: number) => void;
  onDoubleTap: (id: number) => void;
}

// --- Sub-Component: CourseGroup with Animations ---
const CourseGroup: React.FC<CourseGroupProps> = ({
  courseId,
  items,
  isExpanded,
  isSent,
  isCurrent,
  onToggle,
  onDoubleTap,
}) => {
  const scale = useSharedValue(1);
  const contentHeight = useSharedValue(0);
  const contentOpacity = useSharedValue(0);

  // Animate content height and opacity when expanded state changes
  useEffect(() => {
    if (isExpanded) {
      contentHeight.value = withTiming(1, { duration: 250 });
      contentOpacity.value = withTiming(1, { duration: 200 });
    } else {
      contentOpacity.value = withTiming(0, { duration: 150 });
      contentHeight.value = withTiming(0, { duration: 200 });
    }
  }, [isExpanded]);

  // Header tap animation
  const animatedHeaderStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  // Content container animation
  const animatedContentStyle = useAnimatedStyle(() => ({
    opacity: contentOpacity.value,
    maxHeight: contentHeight.value === 0 ? 0 : undefined,
    overflow: "hidden" as const,
  }));

  // Chevron rotation animation
  const chevronStyle = useAnimatedStyle(() => ({
    transform: [
      { rotate: withTiming(isExpanded ? "90deg" : "0deg", { duration: 200 }) },
    ],
  }));

  // Gesture Definitions
  const doubleTap = Gesture.Tap()
    .numberOfTaps(2)
    .maxDuration(250)
    .onStart(() => {
      scale.value = withSequence(
        withSpring(0.95, { damping: 10, stiffness: 200 }),
        withSpring(1)
      );
      runOnJS(onDoubleTap)(courseId);
    });

  const singleTap = Gesture.Tap().onEnd(() => {
    scale.value = withSequence(
      withSpring(0.98, { damping: 15, stiffness: 300 }),
      withSpring(1)
    );
    runOnJS(onToggle)(courseId);
  });

  const composedTap = Gesture.Exclusive(doubleTap, singleTap);

  const courseItemCount = items.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <Animated.View layout={LinearTransition.duration(200)} className="mb-2">
      {/* Header */}
      <GestureDetector gesture={composedTap}>
        <Animated.View
          style={animatedHeaderStyle}
          className={`flex-row items-center justify-between p-3 rounded-lg border ${
            isExpanded
              ? "border-blue-500 bg-blue-900/20"
              : "border-gray-700 bg-[#303030]"
          }`}
        >
          <View className="flex-row items-center">
            {isCurrent && (
              <View className="w-2 h-2 bg-green-400 rounded-full mr-2" />
            )}
            <Text className="text-lg font-semibold text-white">
              Course {courseId}
            </Text>
            {isSent && (
              <Text className="text-sm text-green-400 ml-2">✓ Sent</Text>
            )}
            <Text className="text-sm text-gray-400 ml-2">
              • {courseItemCount} item{courseItemCount !== 1 ? "s" : ""}
            </Text>
          </View>
          <Animated.View style={chevronStyle}>
            <Text className="text-white text-lg">▶</Text>
          </Animated.View>
        </Animated.View>
      </GestureDetector>

      {/* Content with Animation */}
      {isExpanded && (
        <Animated.View
          entering={FadeIn.duration(200)}
          exiting={FadeOut.duration(150)}
          layout={LinearTransition.duration(200)}
          className="mt-2 pl-4 gap-y-2 overflow-hidden"
        >
          {items.map((item) => (
            <Animated.View
              key={item.id}
              layout={LinearTransition.duration(150)}
              className="overflow-hidden"
            >
              <BillItem item={item} isEditable={true} />
            </Animated.View>
          ))}
        </Animated.View>
      )}
    </Animated.View>
  );
};

// --- Main Component ---
const CourseAccordion: React.FC<CourseAccordionProps> = ({
  activeOrder,
  itemCourseMap,
  sentCourses,
  currentCourse,
  onSelectCourse,
  onPressStartNewCourse,
  onDoubleTapCourse,
}) => {
  const [expandedCourseId, setExpandedCourseId] = useState<number | null>(null);
  const prevItemCount = useRef<number>(0);

  // Group items by course
  const groupedItems = useMemo(() => {
    const groups: Record<number, CartItem[]> = {};
    activeOrder?.items?.forEach((item) => {
      const course = itemCourseMap?.[item.id] ?? 1;
      if (!groups[course]) {
        groups[course] = [];
      }
      groups[course].push(item);
    });
    return groups;
  }, [activeOrder?.items, itemCourseMap]);

  // Sort course keys
  const sortedCourses = useMemo(() => {
    const coursesFromItems = Object.keys(groupedItems).map(Number);
    const allCourses = new Set(coursesFromItems);

    if (activeOrder && currentCourse !== undefined && currentCourse !== null) {
      allCourses.add(currentCourse);
    }

    return Array.from(allCourses).sort((a, b) => a - b);
  }, [groupedItems, activeOrder, currentCourse]);

  // Track previous values to prevent re-triggering
  const prevCurrentCourse = useRef<number | undefined>(currentCourse);

  // Auto-expand logic: When items are added, expand the current/working course
  useEffect(() => {
    const currentItemCount = activeOrder?.items?.length ?? 0;

    // Only auto-expand when items are ADDED (count increased)
    if (
      currentItemCount > prevItemCount.current &&
      currentCourse !== undefined
    ) {
      // Auto-expand the current working course, collapsing others
      setExpandedCourseId(currentCourse);
    }

    prevItemCount.current = currentItemCount;
  }, [activeOrder?.items?.length, currentCourse]);

  // Also auto-expand when currentCourse changes (e.g., "Start New Course")
  useEffect(() => {
    // Only trigger when currentCourse actually changes to a new value
    if (
      currentCourse !== undefined &&
      currentCourse !== null &&
      currentCourse !== prevCurrentCourse.current
    ) {
      setExpandedCourseId(currentCourse);
      prevCurrentCourse.current = currentCourse;
    }
  }, [currentCourse]);

  const handleToggleCourse = (courseId: number) => {
    // Toggle: if already expanded, collapse; otherwise expand this one (collapsing others)
    const newExpandedCourseId = expandedCourseId === courseId ? null : courseId;
    setExpandedCourseId(newExpandedCourseId);
    if (onSelectCourse) {
      onSelectCourse(newExpandedCourseId);
    }
  };

  if (!activeOrder) {
    return (
      <View className="flex-1 items-center justify-center">
        <Text className="text-gray-400 text-lg">No active order.</Text>
      </View>
    );
  }

  return (
    <View className="flex-1 bg-[#212121] p-4">
      {/* Main Header */}
      <View className="flex-row items-center justify-between pb-3 border-b border-gray-700 mb-3">
        <Text className="text-xl font-bold text-white">
          Order {activeOrder.display_number 
            ? (activeOrder.display_number.startsWith('#') ? activeOrder.display_number : `#${activeOrder.display_number}`)
            : activeOrder.order_number 
              ? `#${activeOrder.order_number}`
              : activeOrder.db_order_id 
                ? `#${activeOrder.db_order_id.substring(0, 8)}`
                : `#${activeOrder.id?.split('_').pop()?.substring(0, 8)}`}
        </Text>
        <TouchableOpacity
          onPress={onPressStartNewCourse}
          className="px-3 py-1.5 rounded-lg bg-green-600 border border-green-500"
          activeOpacity={0.8}
        >
          <Text className="font-semibold text-white text-base">
            ✨ Start New Course
          </Text>
        </TouchableOpacity>
      </View>

      <ScrollView showsVerticalScrollIndicator={false}>
        <Animated.View layout={LinearTransition.duration(250)}>
          {sortedCourses.length > 0 ? (
            sortedCourses.map((courseId) => (
              <CourseGroup
                key={`course-${courseId}`}
                courseId={courseId}
                items={groupedItems[courseId] || []}
                isExpanded={expandedCourseId === courseId}
                isSent={!!sentCourses?.[courseId]}
                isCurrent={currentCourse === courseId}
                onToggle={handleToggleCourse}
                onDoubleTap={onDoubleTapCourse}
              />
            ))
          ) : (
            <View className="flex-1 items-center justify-center mt-10">
              <Text className="text-gray-400 text-lg">
                Add items to start an order.
              </Text>
            </View>
          )}
        </Animated.View>
      </ScrollView>
    </View>
  );
};

export default CourseAccordion;

import { useToast } from "@/contexts/ToastContext";
import { useDiscounts } from "@/hooks/useDiscounts";
import {
  EligibilityContext,
  getEligibleDiscounts,
} from "@/services/discountEligibility";
import { getDailyUsageCounts } from "@/services/discountUsageTracker";
import { useOrderStore } from "@/stores/useOrderStore";
import BottomSheet, {
  BottomSheetBackdrop,
  BottomSheetScrollView,
  BottomSheetView
} from "@gorhom/bottom-sheet";
import { BottomSheetMethods } from "@gorhom/bottom-sheet/lib/typescript/types";
import { Check, X } from "lucide-react-native";
import React, { forwardRef, useMemo, useState } from "react";
import { Text, TouchableOpacity, View } from "react-native";

interface DiscountBottomSheetProps {
  onClose: () => void;
}

const DiscountBottomSheetComponent: React.ForwardRefRenderFunction<
  BottomSheetMethods,
  DiscountBottomSheetProps
> = ({ onClose }, ref) => {
  // FIX 1: Use 100% as the max height.
  // 90% causes the keyboard to overlap the input on some Android screens.
  const snapPoints = useMemo(() => ["50%", "100%"], []);
  const [activeTab, setActiveTab] = useState<"check" | "items">("check");

  const {
    activeOrderId,
    ordersById,
    applyDiscountToCheck,
    applyDiscountToItem,
    removeDiscountFromItem,
    removeCheckDiscount,
  } = useOrderStore();
  const { show } = useToast();

  const { data: discounts = [] } = useDiscounts();

  const activeOrder = activeOrderId ? ordersById[activeOrderId] : undefined;
  const cartItems = activeOrder?.items || [];
  const itemsWithAvailableDiscounts = cartItems.filter(
    (item) => !!item.availableDiscount
  );

  const eligibilityResults = useMemo(() => {
    if (!activeOrder) return [];
    const items = cartItems.map((item) => ({
      id: item.id,
      menu_item_id: item.menuItemId,
      category_id: item.category_name || undefined,
      is_alcohol: false,
      item_total: item.price * item.quantity,
    }));
    const ctx: EligibilityContext = {
      orderType:
        activeOrder.order_type === "Dine In"
          ? "dine_in"
          : activeOrder.order_type === "Delivery"
            ? "delivery"
            : "takeout",
      currentDate: new Date(),
      dailyUsageCounts: getDailyUsageCounts(),
      subtotal: items.reduce((sum, i) => sum + i.item_total, 0),
      items,
    };
    return getEligibleDiscounts(discounts as any, ctx);
  }, [activeOrder, cartItems, discounts]);

  const handleApplyCheckDiscount = (discount: any) => {
    if (!activeOrderId) return;

    const existingCheckDiscount = activeOrder?.checkDiscount as any;
    const existingNonStackable =
      existingCheckDiscount && existingCheckDiscount.stackable === false;
    const incomingNonStackable = (discount as any)?.stackable === false;

    // Enforce non-stackable rule: block applying when a non-stackable exists or incoming is non-stackable
    if (existingCheckDiscount && (existingNonStackable || incomingNonStackable)) {
      show({
        title: "Cannot stack discounts",
        message: "Remove the existing discount before applying this one.",
        type: "error",
      });
      return;
    }

    applyDiscountToCheck(activeOrderId, discount as any);
    onClose();
  };

  const handleRemoveCheckDiscount = () => {
    if (!activeOrderId) return;
    removeCheckDiscount(activeOrderId);
    onClose();
  };

  const handleToggleItemDiscount = (itemInCart: any) => {
    if (!activeOrderId) return;
    if (itemInCart.appliedDiscount) {
      removeDiscountFromItem(activeOrderId, itemInCart.id);
    } else {
      applyDiscountToItem(activeOrderId, itemInCart.id);
    }
  };

  const renderBackdrop = useMemo(
    () => (props: any) => (
      <BottomSheetBackdrop
        {...props}
        appearsOnIndex={0}
        disappearsOnIndex={-1}
        opacity={0.7}
      />
    ),
    []
  );

  return (
    <BottomSheet
      ref={ref}
      index={-1}
      snapPoints={snapPoints}
      enablePanDownToClose={true}
      backdropComponent={renderBackdrop}
      backgroundStyle={{ backgroundColor: "#212121" }}
      handleIndicatorStyle={{ backgroundColor: "#4B5563" }}
      // FIX 2: Use 'interactive'.
      // This synchronizes the sheet movement with the keyboard animation exactly.
      keyboardBehavior="interactive"
      keyboardBlurBehavior="restore"
      android_keyboardInputMode="adjustResize"
      topInset={60}
    >
      <BottomSheetView className="flex-1 bg-[#212121] px-4 pb-6">
        {/* Header */}
        <View className="flex-row justify-between items-center mb-4 border-b border-gray-700 pb-3">
          <Text className="text-xl font-bold text-white">Apply Discount</Text>
          <TouchableOpacity
            onPress={onClose}
            className="p-1.5 bg-[#303030] rounded-full border border-gray-600"
          >
            <X color="#9CA3AF" size={18} />
          </TouchableOpacity>
        </View>

        {/* Current discount + remove */}
        {activeOrder?.checkDiscount && (
          <View className="mb-4 p-3 border border-blue-500/60 bg-blue-500/10 rounded-xl flex-row items-center justify-between">
            <View>
              <Text className="text-white font-semibold">
                {activeOrder.checkDiscount.label || "Active Discount"}
              </Text>
              {activeOrder.checkDiscount.type === "percentage" ? (
                <Text className="text-gray-300">
                  {Math.round((activeOrder.checkDiscount.value || 0) * 100)}% off
                </Text>
              ) : (
                <Text className="text-gray-300">
                  ${activeOrder.checkDiscount.value?.toFixed(2)} off
                </Text>
              )}
            </View>
            <TouchableOpacity
              onPress={handleRemoveCheckDiscount}
              className="px-3 py-2 bg-red-600 rounded-lg"
            >
              <Text className="text-white font-semibold">Remove</Text>
            </TouchableOpacity>
          </View>
        )}

        {/* Tabs */}
        <View className="flex-row bg-[#303030] p-1 rounded-xl mb-5 border border-gray-700">
          <TouchableOpacity
            onPress={() => setActiveTab("check")}
            className={`flex-1 py-2 rounded-lg items-center ${activeTab === "check" ? "bg-[#4B5563]" : ""
              }`}
          >
            <Text
              className={`font-semibold ${activeTab === "check" ? "text-white" : "text-gray-400"}`}
            >
              Whole Check
            </Text>
          </TouchableOpacity>
          <TouchableOpacity
            onPress={() => setActiveTab("items")}
            className={`flex-1 py-2 rounded-lg items-center ${activeTab === "items" ? "bg-[#4B5563]" : ""
              }`}
          >
            <Text
              className={`font-semibold ${activeTab === "items" ? "text-white" : "text-gray-400"}`}
            >
              Specific Items
            </Text>
          </TouchableOpacity>
        </View>

        {/* Content */}
        <BottomSheetScrollView
          showsVerticalScrollIndicator={false}
          // FIX 3: Add large bottom padding.
          // This ensures that when the keyboard comes up, there is enough 'scrollable'
          // area to push the input to the top of the screen.
          contentContainerStyle={{ paddingBottom: 150 }}
        >
          {activeTab === "check" && (
            <View className="flex-1">
              <Text className="text-gray-400 text-sm mb-3 uppercase tracking-wider font-semibold">
                Available Discounts
              </Text>
              <View className="flex-col gap-y-3">
                {eligibilityResults.length === 0 ? (
                  <Text className="text-gray-500">No discounts available</Text>
                ) : (
                  eligibilityResults.map((d) => (
                    <TouchableOpacity
                      key={d.discount.id}
                      disabled={!d.eligible}
                      onPress={() => handleApplyCheckDiscount(d.discount)}
                      className={`p-3 rounded-xl border ${d.eligible
                        ? "border-blue-500 bg-blue-500/10"
                        : "border-gray-700 bg-[#303030]"
                        }`}
                    >
                      <View className="flex-row justify-between items-center">
                        <View>
                          <Text className="text-white font-semibold text-lg">
                            {d.discount.name}
                          </Text>
                          <Text className="text-gray-400">
                            {d.discount.discount_type === "percentage"
                              ? `${d.discount.discount_value}% off`
                              : `$${d.discount.discount_value.toFixed(2)} off`}
                          </Text>
                        </View>
                        {d.eligible ? (
                          <Text className="text-green-400 font-bold">
                            -${d.calculated_savings.toFixed(2)}
                          </Text>
                        ) : (
                          <Text className="text-red-400 text-sm">
                            {d.reason}
                          </Text>
                        )}
                      </View>
                    </TouchableOpacity>
                  ))
                )}
              </View>
            </View>
          )}

          {activeTab === "items" && (
            <View className="gap-y-2">
              {itemsWithAvailableDiscounts.length > 0 ? (
                itemsWithAvailableDiscounts.map((item) => {
                  const isApplied = !!item.appliedDiscount;
                  return (
                    <TouchableOpacity
                      key={item.id}
                      onPress={() => handleToggleItemDiscount(item)}
                      className={`flex-row justify-between items-center p-3 rounded-xl border ${isApplied
                        ? "bg-blue-900/20 border-blue-500"
                        : "bg-[#303030] border-gray-700"
                        }`}
                    >
                      <View className="flex-1 mr-4">
                        <Text className="text-white font-semibold text-lg">
                          {item.name}
                        </Text>
                        <Text className="text-gray-400 text-sm">
                          {item.availableDiscount?.label || "Discountable"}
                        </Text>
                      </View>
                      <View
                        className={`w-6 h-6 rounded-full items-center justify-center border ${isApplied ? "bg-blue-500 border-blue-500" : "border-gray-500"}`}
                      >
                        {isApplied && <Check size={14} color="white" />}
                      </View>
                    </TouchableOpacity>
                  );
                })
              ) : (
                <View className="items-center py-10">
                  <Text className="text-gray-500 text-lg">
                    No eligible items found.
                  </Text>
                </View>
              )}
            </View>
          )}
        </BottomSheetScrollView>
      </BottomSheetView>
    </BottomSheet>
  );
};

const DiscountBottomSheet = forwardRef(DiscountBottomSheetComponent);
DiscountBottomSheet.displayName = "DiscountBottomSheet";

export default DiscountBottomSheet;

import { CartItem, Discount } from "@/lib/types";
import { useOrderStore } from "@/stores/useOrderStore";
import { X } from "lucide-react-native";
import React, { useEffect, useState } from "react";
import {
  Dimensions,
  KeyboardAvoidingView, // <--- Imported
  Platform, // <--- Imported
  Pressable,
  ScrollView,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import Animated, {
  Easing,
  useAnimatedStyle,
  useSharedValue,
  withTiming,
} from "react-native-reanimated";

const mockDiscounts: Discount[] = [
  { id: "1", label: "10% Discount", value: 0.1, type: "percentage" },
  { id: "2", label: "15% Discount", value: 0.15, type: "percentage" },
  { id: "3", label: "50% Discount", value: 0.5, type: "percentage" },
  {
    id: "4",
    label: "Mall Employee",
    subLabel: "30%",
    value: 0.3,
    type: "percentage",
  },
  {
    id: "5",
    label: "Military Discount",
    subLabel: "(10%)",
    value: 0.1,
    type: "percentage",
  },
];

const { height: SCREEN_HEIGHT } = Dimensions.get("window");

interface DiscountOverlayProps {
  isVisible: boolean;
  onClose: () => void;
}

const DiscountOverlay: React.FC<DiscountOverlayProps> = ({
  isVisible,
  onClose,
}) => {
  const [activeTab, setActiveTab] = useState<"check" | "items">("check");
  const translateY = useSharedValue(SCREEN_HEIGHT);

  const {
    activeOrderId,
    orders,
    applyDiscountToCheck,
    applyDiscountToItem,
    removeDiscountFromItem,
  } = useOrderStore();

  const activeOrder = orders.find((o) => o.id === activeOrderId);
  const cartItems = activeOrder?.items || [];

  const animatedStyle = useAnimatedStyle(() => {
    return {
      transform: [{ translateY: translateY.value }],
    };
  });

  useEffect(() => {
    if (isVisible) {
      translateY.value = withTiming(0, {
        duration: 300,
        easing: Easing.out(Easing.quad),
      });
    } else {
      translateY.value = withTiming(SCREEN_HEIGHT, {
        duration: 300,
        easing: Easing.in(Easing.quad),
      });
    }
  }, [isVisible]);

  const itemsWithAvailableDiscounts = cartItems.filter(
    (item) => !!item.availableDiscount
  );

  const handleApplyCheckDiscount = (discount: Discount) => {
    if (activeOrderId) {
      applyDiscountToCheck(activeOrderId, discount);
      onClose();
    }
  };

  const handleToggleItemDiscount = (itemInCart: CartItem) => {
    if (!activeOrderId) return;
    if (itemInCart.appliedDiscount) {
      removeDiscountFromItem(activeOrderId, itemInCart.id);
    } else {
      applyDiscountToItem(activeOrderId, itemInCart.id);
    }
    onClose();
  };

  if (!isVisible) {
    return null;
  }

  return (
    <View
      style={{
        position: "absolute",
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        zIndex: 40,
      }}
    >
      <Pressable onPress={onClose} className="absolute inset-0 bg-black/60" />
      <Animated.View
        style={animatedStyle}
        className="absolute bottom-0 left-0 right-0 h-[85%] bg-[#212121] rounded-t-3xl p-4 border-t border-gray-700"
      >
        <KeyboardAvoidingView
          behavior={Platform.OS === "ios" ? "padding" : "height"}
          className="flex-1"
        >
          <View className="flex-row justify-between items-center mb-4">
            <Text className="text-2xl font-bold text-white">Discounts</Text>
            <TouchableOpacity
              onPress={onClose}
              className="p-2 bg-[#303030] rounded-full border border-gray-600"
            >
              <X color="#9CA3AF" size={20} />
            </TouchableOpacity>
          </View>

          <View className="flex-row bg-[#303030] border border-gray-700 p-1.5 rounded-xl self-start mb-4">
            <TouchableOpacity
              onPress={() => setActiveTab("check")}
              className={`py-2 px-3 rounded-lg ${
                activeTab === "check" ? "bg-[#212121]" : ""
              }`}
            >
              <Text
                className={`text-lg font-semibold ${
                  activeTab === "check" ? "text-blue-400" : "text-gray-400"
                }`}
              >
                Apply to check
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              onPress={() => setActiveTab("items")}
              className={`py-2 px-3 rounded-lg ${
                activeTab === "items" ? "bg-[#212121]" : ""
              }`}
            >
              <Text
                className={`text-lg font-semibold ${
                  activeTab === "items" ? "text-blue-400" : "text-gray-400"
                }`}
              >
                Apply to items
              </Text>
            </TouchableOpacity>
          </View>

          <ScrollView>
            {activeTab === "check" && (
              <View className="flex-row flex-wrap justify-between">
                {mockDiscounts.map((d) => (
                  <TouchableOpacity
                    key={d.id}
                    onPress={() => handleApplyCheckDiscount(d)}
                    className="w-[49%] p-1 border rounded-xl mb-2 items-center justify-center h-20 bg-[#303030] border-gray-600"
                  >
                    <Text className="text-lg text-wrap w-full overflow-hidden font-bold text-center text-white">
                      {d.label}
                    </Text>
                  </TouchableOpacity>
                ))}
              </View>
            )}
            {activeTab === "items" && (
              <View className="gap-y-3">
                {itemsWithAvailableDiscounts.length > 0 ? (
                  itemsWithAvailableDiscounts.map((item) => {
                    const isApplied = !!item.appliedDiscount;
                    return (
                      <TouchableOpacity
                        key={item.id}
                        onPress={() => handleToggleItemDiscount(item)}
                        className={`p-4 border rounded-xl flex-row justify-between items-center ${
                          isApplied
                            ? "border-blue-500 bg-blue-900/20"
                            : "bg-[#303030] border-gray-600"
                        }`}
                      >
                        <View>
                          <Text
                            className={`text-xl font-bold ${
                              isApplied ? "text-blue-400" : "text-white"
                            }`}
                          >
                            {item.name}
                          </Text>
                          <Text
                            className={`text-lg w-full overflow-hidden font-semibold text-wrap mt-1 ${
                              isApplied ? "text-blue-300" : "text-gray-400"
                            }`}
                          >
                            {item.availableDiscount?.label}
                          </Text>
                        </View>
                        <Text
                          className={`text-xl font-bold ${
                            isApplied ? "text-blue-400" : "text-white"
                          }`}
                        >
                          {isApplied ? "Applied" : "Apply"}
                        </Text>
                      </TouchableOpacity>
                    );
                  })
                ) : (
                  <Text className="text-center text-xl text-gray-500 mt-10">
                    No items in the cart are eligible for a discount.
                  </Text>
                )}
              </View>
            )}
          </ScrollView>
          <View className="flex-row items-center gap-3 mt-4 pt-4 border-t border-gray-700">
            <TextInput
              placeholder="Add promo or voucher"
              className="flex-1 p-3 bg-[#303030] rounded-xl text-xl text-white border border-gray-600 h-16"
              placeholderTextColor="#6B7280"
            />
            <TouchableOpacity className="px-5 py-3 bg-blue-600 rounded-xl">
              <Text className="text-white text-xl font-bold">Apply</Text>
            </TouchableOpacity>
          </View>
        </KeyboardAvoidingView>
      </Animated.View>
    </View>
  );
};

