    usePaymentStore();
  const {
    activeOrderOutstandingTotal,
    activeOrderTotal,
    activeOrderOutstandingCash,
    activeOrderTotalCash,
    // Tax breakdown for display
    activeOrderOutstandingSubtotal,
    activeOrderOutstandingTax,
    activeOrderSubtotal,
    activeOrderTax,
  } = useOrderStore();

