    const handleSelect = (id: string) => {
      onSelect(id);
      setSelectedId(id);
      (ref as any)?.current?.close?.();
    };

    return (
      <BottomSheet
        ref={ref as any}
        index={-1}
        snapPoints={snapPoints}
        enablePanDownToClose={true}
        backgroundStyle={{ backgroundColor: "#212121" }}
        handleIndicatorStyle={{ backgroundColor: "#4B5563" }}
