                  return (
                    <TouchableOpacity
                      key={item.id}
                      disabled={isAdded}
                      onPress={() => handleSelect(item.id)}
                      className={`mx-4 mb-2 p-3 rounded-xl border ${
                        isSelected
                          ? "bg-blue-900/20 border-blue-500"
                          : isAdded
                          ? "bg-[#252525] border-gray-800 opacity-50"
                          : "bg-[#303030] border-gray-700"
