          }`}
          onPress={() => handleTabPress("schedules")}
        >
          <View className="flex-row items-center justify-between">
            <Text
              className={`text-xl font-medium ${
                activeTab === "schedules" ? "text-blue-400" : "text-gray-300"
              }`}
            >
              Schedules
            </Text>
            <ChevronRight size={20} color="#9CA3AF" />
          </View>
        </TouchableOpacity>
      </View>
    </View>
  );
};

