import { CartItem, OrderProfile } from "@/lib/types";
import { ChevronDown, ChevronRight, CreditCard, DollarSign } from "lucide-react-native";
import React, { useMemo, useState } from "react";
import { Pressable, Text, View } from "react-native";
import { ta } from "zod/v4/locales";

interface PaymentCoverageSectionProps {
  order: OrderProfile;
}

interface Payment {
  id?: string;
  amount: number;
  method: string;
  cardBrand?: string;
  last4?: string;
  tip_amount?: number;
  itemsCovered?: {
    itemId: string;
    quantity: number;
  }[];
  timestamp?: string;
  isVoided?: boolean;
}

interface PaymentCoverage {
  payment: Payment;
  paymentIndex: number;
  coveredItems: {
    item: CartItem;
    quantityCovered: number;
  }[];
  totalCovered: number;
}

const PaymentCoverageSection: React.FC<PaymentCoverageSectionProps> = ({ order }) => {
  const [expandedPaymentId, setExpandedPaymentId] = useState<string | null>(null);

  // Calculate payment coverage
  const paymentCoverage = useMemo((): PaymentCoverage[] => {
    const payments = (order.payments || []) as Payment[];
    const orderItems = order.items || [];
    return payments.map((payment, index) => {
      // Skip voided payments
      if (payment.isVoided) {
        return {
          payment,
          paymentIndex: index,
          coveredItems: [],
          totalCovered: 0,
        };
      }

      const coveredItems: { item: CartItem; quantityCovered: number }[] = [];
      let totalCovered = 0;

      // Determine if this payment used cash pricing
      const isCashPayment = payment.method?.toLowerCase().includes('cash');

      // If payment has itemsCovered data, use it
      if (payment.itemsCovered && payment.itemsCovered.length > 0) {
        payment.itemsCovered.forEach(({ itemId, quantity }) => {
          const item = orderItems.find((i: CartItem) => i.db_order_item_id === itemId);
          if (item) {
            coveredItems.push({ item, quantityCovered: quantity });

            // Use cash price and tax for cash payments, card price for card payments
            const itemPrice = isCashPayment ? (item.cashPrice || item.price) : item.price;
            const itemTax = isCashPayment ? (item.cashTaxAmount || item.taxAmount || 0) : (item.taxAmount || 0);

            totalCovered += (itemPrice + itemTax) * quantity;
          }
        });
      } else {
        // Fallback: Show that this payment covered the full amount
        // but we don't have item-level details
        totalCovered = payment.amount || 0;
      }

      return {
        payment,
        paymentIndex: index,
        coveredItems,
        totalCovered,
      };
    });
  }, [order.payments, order.items]);
  const togglePayment = (paymentId: string) => {
    setExpandedPaymentId(expandedPaymentId === paymentId ? null : paymentId);
  };

  if (!order.payments || order.payments.length === 0) {
    return (
      <View className="py-8 items-center justify-center">
        <Text className="text-gray-400 text-center">
          No payment coverage information available
        </Text>
      </View>
    );
  }

  // Filter out voided payments
  const activePaymentCoverage = paymentCoverage.filter((pc) => !pc.payment.isVoided);

  if (activePaymentCoverage.length === 0) {
    return (
      <View className="py-8 items-center justify-center">
        <Text className="text-gray-400 text-center">
          All payments have been voided
        </Text>
      </View>
    );
  }

  return (
    <View className="py-4">
      <Text className="text-xl font-bold text-white mb-4">Payment Coverage</Text>
      <Text className="text-gray-400 text-sm mb-4">
        See which items were covered by each payment
      </Text>

      {activePaymentCoverage.map((coverage) => {
        const { payment, paymentIndex, coveredItems, totalCovered } = coverage;
        const paymentId = payment.id || `payment-${paymentIndex}`;
        const isExpanded = expandedPaymentId === paymentId;
        const paymentMethod = payment.method || "Cash";
        const isCashPayment = paymentMethod.toLowerCase().includes('cash');

        return (
          <View key={paymentId} className="mb-3">
            {/* Payment Header - Clickable */}
            <Pressable
              onPress={() => togglePayment(paymentId)}
              className="bg-[#303030] rounded-lg border border-gray-700 p-4"
            >
              <View className="flex-row items-center justify-between">
                <View className="flex-row items-center gap-3 flex-1">
                  {/* Payment icon */}
                  <View className="w-10 h-10 bg-blue-600/20 border border-blue-500 rounded-full items-center justify-center">
                    {paymentMethod.toLowerCase().includes("card") ? (
                      <CreditCard color="#3B82F6" size={20} />
                    ) : (
                      <DollarSign color="#3B82F6" size={20} />
                    )}
                  </View>

                  {/* Payment info */}
                  <View className="flex-1">
                    <Text className="text-white font-semibold text-base">
                      Payment #{paymentIndex + 1}
                      {payment.cardBrand && payment.last4 && (
                        <Text className="text-gray-400">
                          {" "}
                          - {payment.cardBrand} ****{payment.last4}
                        </Text>
                      )}
                    </Text>
                    <Text className="text-gray-400 text-sm">
                      ${totalCovered.toFixed(2)}
                      {coveredItems.length > 0 && ` • ${coveredItems.length} items`}
                    </Text>
                  </View>

                  {/* Expand/Collapse icon */}
                  {isExpanded ? (
                    <ChevronDown color="#9CA3AF" size={24} />
                  ) : (
                    <ChevronRight color="#9CA3AF" size={24} />
                  )}
                </View>
              </View>
            </Pressable>

            {/* Expanded content - Item list */}
            {isExpanded && (
              <View className="bg-[#2A2A2A] border border-gray-700 rounded-b-lg mt-1 p-4">
                {coveredItems.length > 0 ? (
                  <View>
                    <Text className="text-gray-400 text-sm mb-3 font-semibold">
                      Items covered by this payment:
                    </Text>
                    {coveredItems.map(({ item, quantityCovered }, idx) => {
                      // Use cash price for cash payments, card price for card payments
                      const displayPrice = isCashPayment ? (item.cashPrice || item.price) : item.price;

                      return (
                        <View
                          key={idx}
                          className="flex-row items-center justify-between py-2 border-b border-gray-700 last:border-b-0"
                        >
                          <View className="flex-1">
                            <Text className="text-white font-medium">
                              {item.name || "Unknown Item"}
                            </Text>
                            <Text className="text-gray-500 text-sm">
                              Quantity: {quantityCovered}
                              {quantityCovered % 1 !== 0 && " (partial)"}
                            </Text>
                          </View>
                          <Text className="text-white font-semibold">
                            ${((displayPrice || 0) * quantityCovered).toFixed(2)}
                          </Text>
                        </View>
                      );
                    })}

                    {/* Total for this payment */}
                    <View className="flex-row items-center justify-between pt-3 mt-2 border-t border-gray-600">
                      <Text className="text-white font-bold">Total Covered</Text>
                      <Text className="text-white font-bold text-lg">
                        ${totalCovered.toFixed(2)}
                      </Text>
                    </View>
                  </View>
                ) : (
                  <Text className="text-gray-400 text-center py-2">
                    Item-level coverage not available for this payment
                  </Text>
                )}
              </View>
            )}
          </View>
        );
      })}
    </View>
  );
};

export default PaymentCoverageSection;

import { OrderProfile } from "@/lib/types";
import { Check, CreditCard, DollarSign, X } from "lucide-react-native";
import React, { useMemo } from "react";
import { Text, View } from "react-native";

interface PaymentTimelineSectionProps {
  order: OrderProfile;
}

interface Payment {
  id?: string;
  amount: number;
  method: string;
  cardBrand?: string;
  last4?: string;
  tip_amount?: number;
  timestamp?: string;
  isVoided?: boolean;
  voidReason?: string;
}

const PaymentCard: React.FC<{ payment: Payment; index: number; isLast: boolean }> = ({
  payment,
  index,
  isLast,
}) => {
  const isVoided = payment.isVoided || false;
  const paymentMethod = payment.method || "Cash";
  const totalAmount = (payment.amount || 0) + (payment.tip_amount || 0);

  // Format timestamp
  const formattedTime = payment.timestamp
    ? new Date(payment.timestamp).toLocaleString("en-US", {
        month: "short",
        day: "numeric",
        year: "numeric",
        hour: "2-digit",
        minute: "2-digit",
      })
    : "Unknown time";

  return (
    <View className="flex-row">
      {/* Timeline indicator */}
      <View className="items-center mr-4">
        <View
          className={`w-10 h-10 rounded-full items-center justify-center ${
            isVoided ? "bg-red-600/20 border-2 border-red-500" : "bg-green-600/20 border-2 border-green-500"
          }`}
        >
          <Text>
            {isVoided ? (
              <X color="#EF4444" size={20} />
            ) : paymentMethod.toLowerCase().includes("card") ? (
              <CreditCard color="#10B981" size={20} />
            ) : (
              <DollarSign color="#10B981" size={20} />
            )}
          </Text>
        </View>
        {!isLast && <View className="w-0.5 h-full bg-gray-600 mt-2" />}
      </View>

      {/* Payment details */}
      <View className="flex-1 mb-6">
        <View
          className={`bg-[#303030] rounded-lg border p-4 ${
            isVoided ? "border-red-700 opacity-60" : "border-gray-700"
          }`}
        >
          {/* Header */}
          <View className="flex-row items-center justify-between mb-2">
            <View className="flex-row items-center gap-2">
              <Text className={`text-lg font-bold ${isVoided ? "line-through text-gray-500" : "text-white"}`}>
                Payment #{index + 1}
              </Text>
              {isVoided && (
                <View className="bg-red-600/20 border border-red-500 px-2 py-0.5 rounded">
                  <Text className="text-red-400 font-bold text-xs">VOIDED</Text>
                </View>
              )}
            </View>
          </View>

          {/* Payment method and amount */}
          <View className="flex-row items-center justify-between mb-2">
            <View>
              <Text className={`text-sm ${isVoided ? "text-gray-600" : "text-gray-400"}`}>
                {paymentMethod}
                {payment.cardBrand && payment.last4 && ` - ${payment.cardBrand} ****${payment.last4}`}
              </Text>
              <Text className={`text-xs ${isVoided ? "text-gray-700" : "text-gray-500"} mt-1`}>
                {formattedTime}
              </Text>
            </View>
            <View className="items-end">
              <Text className={`text-xl font-bold ${isVoided ? "line-through text-gray-600" : "text-white"}`}>
                ${totalAmount.toFixed(2)}
              </Text>
              {payment.tip_amount && payment.tip_amount > 0 && (
                <Text className={`text-sm ${isVoided ? "text-gray-700" : "text-gray-400"}`}>
                  Tip: ${payment.tip_amount.toFixed(2)}
                </Text>
              )}
            </View>
          </View>

          {/* Void reason */}
          {isVoided && payment.voidReason && (
            <View className="mt-2 bg-red-900/20 border border-red-700 rounded p-2">
              <Text className="text-red-400 text-sm">Void Reason: {payment.voidReason}</Text>
            </View>
          )}
        </View>
      </View>
    </View>
  );
};

const PaymentTimelineSection: React.FC<PaymentTimelineSectionProps> = ({ order }) => {
  // Sort payments by timestamp (most recent first)
  const sortedPayments = useMemo(() => {
    const payments = (order.payments || []) as Payment[];
    return [...payments].sort((a, b) => {
      const aTime = a.timestamp ? new Date(a.timestamp).getTime() : 0;
      const bTime = b.timestamp ? new Date(b.timestamp).getTime() : 0;
      return bTime - aTime;
    });
  }, [order.payments]);

  if (!order.payments || order.payments.length === 0) {
    return (
      <View className="py-8 items-center justify-center">
        <Text className="text-gray-400 text-center">
          No payment history available for this order
        </Text>
      </View>
    );
  }

  return (
    <View className="py-4">
      <Text className="text-xl font-bold text-white mb-4">Payment History</Text>
      <View className="pl-2">
        {sortedPayments.map((payment, index) => (
          <PaymentCard
            key={payment.id || index}
            payment={payment}
            index={index}
            isLast={index === sortedPayments.length - 1}
          />
        ))}
      </View>
    </View>
  );
};

export default PaymentTimelineSection;

import { useToast } from "@/contexts/ToastContext";
import { PaymentType, PreviousOrder } from "@/lib/types";
import { usePreviousOrdersStore } from "@/stores/usePreviousOrdersStore";
import { Check, X } from "lucide-react-native";
import React, { useState } from "react";
import {
  KeyboardAvoidingView, // <--- Imported
  Platform, // <--- Imported
  ScrollView,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "../ui/dialog";

interface RefundModalProps {
  isOpen: boolean;
  onClose: () => void;
  order: PreviousOrder | null;
}

const RefundModal: React.FC<RefundModalProps> = ({
  isOpen,
  onClose,
  order,
}) => {
  const [refundType, setRefundType] = useState<"full" | "partial">("full");
  const [reason, setReason] = useState("");
  const [selectedItems, setSelectedItems] = useState<
    Array<{ itemId: string; quantity: number; reason: string }>
  >([]);
  const [paymentMethod, setPaymentMethod] = useState<PaymentType>("Card");
  const { show } = useToast();

  const { refundFullOrder, refundItems } = usePreviousOrdersStore();

  if (!order) return null;

  const handleFullRefund = () => {
    if (!reason.trim()) {
      show({
        title: "Reason Required",
        message: "A reason must be provided to process a full refund.",
        type: "error",
      });
      return;
    }

    refundFullOrder(order.orderId, reason, "Cashier", paymentMethod);
    show({
      title: "Refund Successful",
      message: "The full refund has been processed successfully.",
      type: "success",
    });
    onClose();
  };

  const handlePartialRefund = () => {
    if (selectedItems.length === 0) {
      show({
        title: "No Items Selected",
        message: "Please select one or more items to process a partial refund.",
        type: "error",
      });
      return;
    }

    refundItems(order.orderId, selectedItems, "Cashier", paymentMethod);
    show({
      title: "Refund Successful",
      message: "The partial refund has been processed successfully.",
      type: "success",
    });
    onClose();
  };

  const toggleItemSelection = (itemId: string, maxQuantity: number) => {
    const existingIndex = selectedItems.findIndex(
      (item) => item.itemId === itemId
    );

    if (existingIndex >= 0) {
      // Remove item
      setSelectedItems((prev) => prev.filter((item) => item.itemId !== itemId));
    } else {
      // Add item with full quantity
      setSelectedItems((prev) => [
        ...prev,
        { itemId, quantity: maxQuantity, reason: "" },
      ]);
    }
  };

  const updateItemQuantity = (itemId: string, quantity: number) => {
    setSelectedItems((prev) =>
      prev.map((item) =>
        item.itemId === itemId ? { ...item, quantity } : item
      )
    );
  };

  const updateItemReason = (itemId: string, reason: string) => {
    setSelectedItems((prev) =>
      prev.map((item) => (item.itemId === itemId ? { ...item, reason } : item))
    );
  };

  const getSelectedItemQuantity = (itemId: string) => {
    const item = selectedItems.find((item) => item.itemId === itemId);
    return item?.quantity || 0;
  };

  const getSelectedItemReason = (itemId: string) => {
    const item = selectedItems.find((item) => item.itemId === itemId);
    return item?.reason || "";
  };

  const calculateRefundAmount = () => {
    if (refundType === "full") {
      return order.total;
    }

    return selectedItems.reduce((total, selectedItem) => {
      const item = order.items.find((i) => i.id === selectedItem.itemId);
      return total + (item ? item.price * selectedItem.quantity : 0);
    }, 0);
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="w-[600px] max-h-[80vh] bg-white rounded-2xl">
        <DialogHeader>
          <DialogTitle className="text-2xl font-bold text-gray-800">
            Process Refund
          </DialogTitle>
          <Text className="text-gray-600 mt-2">
            Order #{order.orderId} - ${order.total.toFixed(2)}
          </Text>
        </DialogHeader>

        <KeyboardAvoidingView
          behavior={Platform.OS === "ios" ? "padding" : "height"}
          className="flex-1"
        >
          <ScrollView className="flex-1">
            {/* Refund Type Selection */}
            <View className="mb-6">
              <Text className="text-lg font-semibold text-gray-800 mb-3">
                Refund Type
              </Text>
              <View className="flex-row gap-3">
                <TouchableOpacity
                  onPress={() => setRefundType("full")}
                  className={`flex-1 py-3 px-4 rounded-lg border-2 ${
                    refundType === "full"
                      ? "border-blue-500 bg-blue-50"
                      : "border-gray-300"
                  }`}
                >
                  <Text
                    className={`font-semibold text-center ${
                      refundType === "full" ? "text-blue-600" : "text-gray-600"
                    }`}
                  >
                    Full Refund
                  </Text>
                  <Text className="text-sm text-center text-gray-500 mt-1">
                    ${order.total.toFixed(2)}
                  </Text>
                </TouchableOpacity>
                <TouchableOpacity
                  onPress={() => setRefundType("partial")}
                  className={`flex-1 py-3 px-4 rounded-lg border-2 ${
                    refundType === "partial"
                      ? "border-blue-500 bg-blue-50"
                      : "border-gray-300"
                  }`}
                >
                  <Text
                    className={`font-semibold text-center ${
                      refundType === "partial"
                        ? "text-blue-600"
                        : "text-gray-600"
                    }`}
                  >
                    Partial Refund
                  </Text>
                  <Text className="text-sm text-center text-gray-500 mt-1">
                    Select Items
                  </Text>
                </TouchableOpacity>
              </View>
            </View>

            {/* Payment Method */}
            <View className="mb-6">
              <Text className="text-lg font-semibold text-gray-800 mb-3">
                Refund Method
              </Text>
              <View className="flex-row gap-3">
                {(["Card", "Cash"] as PaymentType[]).map((method) => (
                  <TouchableOpacity
                    key={method}
                    onPress={() => setPaymentMethod(method)}
                    className={`flex-1 py-3 px-4 rounded-lg border-2 ${
                      paymentMethod === method
                        ? "border-blue-500 bg-blue-50"
                        : "border-gray-300"
                    }`}
                  >
                    <Text
                      className={`font-semibold text-center ${
                        paymentMethod === method
                          ? "text-blue-600"
                          : "text-gray-600"
                      }`}
                    >
                      {method}
                    </Text>
                  </TouchableOpacity>
                ))}
              </View>
            </View>

            {/* Full Refund Section */}
            {refundType === "full" && (
              <View className="mb-6">
                <Text className="text-lg font-semibold text-gray-800 mb-3">
                  Reason for Refund
                </Text>
                <TextInput
                  value={reason}
                  onChangeText={setReason}
                  placeholder="Enter reason for refund..."
                  multiline
                  numberOfLines={3}
                  className="w-full p-3 border border-gray-300 rounded-lg text-gray-800 h-20"
                />
              </View>
            )}

            {/* Partial Refund Section */}
            {refundType === "partial" && (
              <View className="mb-6">
                <Text className="text-lg font-semibold text-gray-800 mb-3">
                  Select Items to Refund
                </Text>
                <ScrollView className="max-h-60">
                  {order.items.map((item) => {
                    const isSelected = selectedItems.some(
                      (selected) => selected.itemId === item.id
                    );
                    const selectedQuantity = getSelectedItemQuantity(item.id);
                    const selectedReason = getSelectedItemReason(item.id);

                    return (
                      <View
                        key={item.id}
                        className="mb-4 p-4 border border-gray-200 rounded-lg"
                      >
                        <View className="flex-row items-center justify-between mb-2">
                          <Text className="font-semibold text-gray-800">
                            {item.name}
                          </Text>
                          <Text className="text-gray-600">
                            ${item.price.toFixed(2)} each
                          </Text>
                        </View>

                        <View className="flex-row items-center justify-between mb-2">
                          <Text className="text-gray-600">
                            Quantity: {item.quantity}
                          </Text>
                          <TouchableOpacity
                            onPress={() =>
                              toggleItemSelection(item.id, item.quantity)
                            }
                            className={`p-2 rounded-lg ${
                              isSelected ? "bg-blue-500" : "bg-gray-200"
                            }`}
                          >
                            {isSelected ? (
                              <Check color="white" size={16} />
                            ) : (
                              <X color="gray" size={16} />
                            )}
                          </TouchableOpacity>
                        </View>

                        {isSelected && (
                          <View className="gap-y-2">
                            <View className="flex-row items-center gap-2">
                              <Text className="text-gray-600">Refund Qty:</Text>
                              <TextInput
                                value={selectedQuantity.toString()}
                                onChangeText={(text) => {
                                  const qty = parseInt(text) || 0;
                                  if (qty >= 0 && qty <= item.quantity) {
                                    updateItemQuantity(item.id, qty);
                                  }
                                }}
                                keyboardType="numeric"
                                className="flex-1 p-2 border border-gray-300 rounded text-center h-20"
                              />
                              <Text className="text-gray-600">
                                / {item.quantity}
                              </Text>
                            </View>

                            <TextInput
                              value={selectedReason}
                              onChangeText={(text) =>
                                updateItemReason(item.id, text)
                              }
                              placeholder="Reason for this item..."
                              className="w-full p-2 border border-gray-300 rounded text-sm h-20"
                            />
                          </View>
                        )}
                      </View>
                    );
                  })}
                </ScrollView>
              </View>
            )}

            {/* Refund Summary */}
            <View className="mb-6 p-4 bg-gray-50 rounded-lg">
              <Text className="text-lg font-semibold text-gray-800 mb-2">
                Refund Summary
              </Text>
              <View className="flex-row justify-between">
                <Text className="text-gray-600">Original Total:</Text>
                <Text className="font-semibold">${order.total.toFixed(2)}</Text>
              </View>
              <View className="flex-row justify-between">
                <Text className="text-gray-600">Refund Amount:</Text>
                <Text className="font-semibold text-red-600">
                  ${calculateRefundAmount().toFixed(2)}
                </Text>
              </View>
              <View className="flex-row justify-between border-t border-gray-300 pt-2 mt-2">
                <Text className="text-gray-600">Remaining:</Text>
                <Text className="font-semibold">
                  ${(order.total - calculateRefundAmount()).toFixed(2)}
                </Text>
              </View>
            </View>
          </ScrollView>
        </KeyboardAvoidingView>

        {/* Action Buttons */}
        <View className="flex-row gap-3 pt-4 border-t border-gray-200">
          <TouchableOpacity
            onPress={onClose}
            className="flex-1 py-3 border border-gray-300 rounded-lg"
          >
            <Text className="font-bold text-gray-700 text-center">Cancel</Text>
          </TouchableOpacity>
          <TouchableOpacity
            onPress={
              refundType === "full" ? handleFullRefund : handlePartialRefund
            }
            className="flex-1 py-3 bg-red-500 rounded-lg"
          >
            <Text className="font-bold text-white text-center">
              Process Refund
            </Text>
          </TouchableOpacity>
        </View>
      </DialogContent>
    </Dialog>
  );
};

export default RefundModal;

