import PTOBalanceCard from "@/components/profile/PTOBalanceCard"; // Import PTOBalanceCard
import { useEmployeeStore } from "@/stores/useEmployeeStore";
import { usePtoStore } from "@/stores/usePtoStore";
import { useScheduleStore } from "@/stores/useScheduleStore";
import { useStoreSettingsStore } from "@/stores/useStoreSettingsStore";
import {
  differenceInHours,
  isFuture,
  isToday,
  parseISO,
  startOfDay,
} from "date-fns";
import {
  AlertCircle,
  CheckCircle2,
  Clock,
  TrendingUp,
} from "lucide-react-native";
import React, { useMemo } from "react";
import { View } from "react-native";

interface PtoMetricsProps {
  employeeId: string;
}

const PtoMetrics: React.FC<PtoMetricsProps> = ({ employeeId }) => {
  // Atomic selectors
  const balances = usePtoStore((state) => state.balances);
  const ptoRequests = useScheduleStore((state) => state.ptoRequests);
  const { schedulePeriods, weeklySchedules } = useScheduleStore();
  const { ptoAccrualRate } = useStoreSettingsStore();
  const loggedInEmployee = useEmployeeStore((state) => state.loggedInEmployee);

  const employeeBalance = balances[employeeId] || {
    totalAccrued: 0,
    usedThisYear: 0,
  };

  const metrics = useMemo(() => {
    const totalAccrued = employeeBalance.totalAccrued;
    const usedThisYear = employeeBalance.usedThisYear;

    const pendingApproval = ptoRequests
      .filter(
        (req) => req.employeeId === employeeId && req.status === "pending"
      )
      .reduce((sum, req) => sum + req.hours, 0);

    const today = startOfDay(new Date());

    const futureShifts = [...schedulePeriods, ...weeklySchedules]
      .filter((p) => p.status === "active")
      .flatMap((s) => s.shifts)
      .filter((shift) => {
        if (shift.employeeId !== loggedInEmployee?.id) return false;
        // Correctly parse the date string to avoid timezone issues
        const shiftDate = parseISO(shift.date);
        return isToday(shiftDate) || isFuture(shiftDate);
      });

    const futureHours = futureShifts.reduce((total, shift) => {
      const startTime = parseISO(shift.startTime);
      const endTime = parseISO(shift.endTime);
      const duration = differenceInHours(endTime, startTime);
      return total + duration;
    }, 0);

    const ptoFromFutureShifts = futureHours * ptoAccrualRate;
    // Removed redundant declaration: const totalAccrued = employeeBalance.totalAccrued;

    const projectedPto = totalAccrued + ptoFromFutureShifts;

    return {
      projectedPto,
      totalAccrued,
      usedThisYear,
      pendingApproval,
    };
  }, [
    employeeId,
    employeeBalance,
    ptoRequests,
    schedulePeriods,
    weeklySchedules,
    ptoAccrualRate,
    loggedInEmployee?.id,
  ]);

  return (
    <View className="py-4  mb-4">
      <View className="flex-row gap-4 mb-6 flex-wrap">
        <PTOBalanceCard
          label="Total Accrued"
          value={`${metrics.totalAccrued.toFixed(2)}h`}
          icon={<TrendingUp size={20} color="#9CA3AF" />}
          variant="default"
        />
        <PTOBalanceCard
          label="Projected PTO"
          value={`${metrics.projectedPto.toFixed(2)}h`}
          icon={<TrendingUp size={20} color="#60A5FA" />}
          variant="primary"
        />
        <PTOBalanceCard
          label="Used This Year"
          value={`${metrics.usedThisYear.toFixed(2)}h`}
          icon={<CheckCircle2 size={20} color="#9CA3AF" />}
          variant="secondary"
        />
        <PTOBalanceCard
          label="Pending Approval"
          value={`${metrics.pendingApproval.toFixed(2)}h`}
          icon={<AlertCircle size={20} color="#f59e0b" />}
          variant="warning"
        />
      </View>
    </View>
  );
};

export default PtoMetrics;

import { useDropZoneContext } from "@/contexts/DropZoneContext";
import { Shift } from "@/lib/types";
import React, { useEffect } from "react";
import { Gesture, GestureDetector } from "react-native-gesture-handler";
import Animated, {
  measure,
  runOnJS,
  useAnimatedReaction,
  useAnimatedRef,
  useAnimatedStyle,
  useSharedValue,
} from "react-native-reanimated";
import { OpenShiftChip } from "./OpenShiftChip";
import { ShiftChip } from "./ShiftChip";

interface DraggableShiftProps {
  shift: Shift;
  onShiftClick: (shift: Shift) => void;
  wage: number;
  onShiftDrop: (shift: Shift, newEmployeeId: string, newDate: string) => void;
}

export const DraggableShift: React.FC<DraggableShiftProps> = ({
  shift,
  onShiftClick,
  wage,
  onShiftDrop,
}) => {
  const {
    dropZoneLayouts,
    hoveredDropZoneKey,
    draggingCellKey,
    dropResult,
    setActiveDragItem,
    dragTranslation,
  } = useDropZoneContext();

  const animatedRef = useAnimatedRef<Animated.View>();

  // Controls opacity of the original item
  const isDraggingLocal = useSharedValue(false);

  // Tracks if we have signaled a drop and are waiting for the update
  const isDropCommitted = useSharedValue(false);

  const itemWidth = useSharedValue(0);
  const itemHeight = useSharedValue(0);

  // Cleanup on Unmount: This ensures the overlay disappears ONLY when
  // the new schedule data arrives and this component is removed.
  useEffect(() => {
    return () => {
      // Safe to call even if not dragging
      setActiveDragItem(null);
    };
  }, []);

  // Watch for explicit failure signal to reset state
  useAnimatedReaction(
    () => dropResult.value,
    (result) => {
      if (result === "failure") {
        // If drop failed, reset everything immediately
        isDropCommitted.value = false;
        isDraggingLocal.value = false; // Show original
        runOnJS(setActiveDragItem)(null); // Hide overlay
        dragTranslation.value = { x: 0, y: 0 };
        draggingCellKey.value = null;
        hoveredDropZoneKey.value = null;
      }
    },
    [dropResult]
  );

  const panGesture = Gesture.Pan()
    .onStart(() => {
      const measurement = measure(animatedRef);

      if (measurement) {
        // Reset states
        isDropCommitted.value = false;
        itemWidth.value = measurement.width;
        itemHeight.value = measurement.height;

        // 1. Show Overlay
        runOnJS(setActiveDragItem)({
          type: "shift",
          shift: shift,
          wage: wage,
          startX: measurement.pageX,
          startY: measurement.pageY,
          width: measurement.width,
          height: measurement.height,
        });

        // 2. Hide Local
        isDraggingLocal.value = true;
        draggingCellKey.value = `${shift.employeeId}-${shift.date}`;
        dropResult.value = "idle";
        dragTranslation.value = { x: 0, y: 0 };
      }
    })
    .onUpdate((e) => {
      dragTranslation.value = { x: e.translationX, y: e.translationY };

      const layouts = dropZoneLayouts.value;
      const ownLayout = layouts[`${shift.employeeId}-${shift.date}`];
      if (!ownLayout) return;

      // Collision Logic (Center Point)
      const CELL_PADDING = 8;
      const centerX =
        ownLayout.x + CELL_PADDING + itemWidth.value / 2 + e.translationX;
      const centerY =
        ownLayout.y + CELL_PADDING + itemHeight.value / 2 + e.translationY;

      let foundZone = false;
      for (const key in layouts) {
        const layout = layouts[key];
        if (
          centerX > layout.x &&
          centerX < layout.x + layout.width &&
          centerY > layout.y &&
          centerY < layout.y + layout.height
        ) {
          hoveredDropZoneKey.value = key;
          foundZone = true;
          break;
        }
      }
      if (!foundZone) {
        hoveredDropZoneKey.value = null;
      }
    })
    .onEnd(() => {
      const originalCellKey = `${shift.employeeId}-${shift.date}`;
      if (
        hoveredDropZoneKey.value &&
        hoveredDropZoneKey.value !== originalCellKey
      ) {
        // 3. Commit Drop
        isDropCommitted.value = true;

        const parts = hoveredDropZoneKey.value.split("-");
        const newEmployeeId = parts[0];
        const newDate = parts.slice(1).join("-");

        runOnJS(onShiftDrop)(shift, newEmployeeId, newDate);
      }
    })
    .onFinalize(() => {
      // 4. Conditional Cleanup
      // If we committed a drop, we DO NOT reset isDraggingLocal.
      // We leave the original hidden (opacity 0) and the Overlay visible.
      // They will both be cleaned up when the component unmounts (via useEffect).
      if (!isDropCommitted.value) {
        isDraggingLocal.value = false;
        runOnJS(setActiveDragItem)(null);
        draggingCellKey.value = null;
        hoveredDropZoneKey.value = null;
        dragTranslation.value = { x: 0, y: 0 };
      } else {
        // If committed, just clear the highlights, but keep the item hidden
        draggingCellKey.value = null;
        hoveredDropZoneKey.value = null;
      }
    });

  const containerStyle = useAnimatedStyle(() => ({
    opacity: isDraggingLocal.value ? 0 : 1,
  }));

  return (
    <GestureDetector gesture={panGesture}>
      <Animated.View ref={animatedRef} style={containerStyle}>
        {shift.status === "open" ? (
          <OpenShiftChip shift={shift} onClick={() => onShiftClick(shift)} />
        ) : (
          <ShiftChip
            role={shift.role}
            start={shift.startTime}
            end={shift.endTime}
            requiredCount={shift.requiredCount}
            wage={wage}
            onClick={() => onShiftClick(shift)}
          />
        )}
      </Animated.View>
    </GestureDetector>
  );
};

import { TemplateShiftChip } from "@/components/scheduling/TemplateShiftChip";
import { useDropZoneContext } from "@/contexts/DropZoneContext";
import { TemplateShift } from "@/lib/types";
import React, { useEffect } from "react";
import { Gesture, GestureDetector } from "react-native-gesture-handler";
import Animated, {
  measure,
  runOnJS,
  useAnimatedReaction,
  useAnimatedRef,
  useAnimatedStyle,
  useSharedValue,
} from "react-native-reanimated";

interface DraggableTemplateShiftProps {
  shift: TemplateShift;
  wage?: number;
  onShiftClick: (shift: TemplateShift) => void;
  onShiftDrop: (
    shift: TemplateShift,
    newEmployeeId: string,
    newDayOfWeek: number
  ) => void;
}

export const DraggableTemplateShift: React.FC<DraggableTemplateShiftProps> = ({
  shift,
  wage,
  onShiftClick,
  onShiftDrop,
}) => {
  const {
    dropZoneLayouts,
    hoveredDropZoneKey,
    draggingCellKey,
    dropResult,
    setActiveDragItem,
    dragTranslation,
  } = useDropZoneContext();

  const animatedRef = useAnimatedRef<Animated.View>();

  // Controls opacity of the original item (0 when dragging, 1 otherwise)
  const isDraggingLocal = useSharedValue(false);
  const isDropCommitted = useSharedValue(false);

  const itemWidth = useSharedValue(0);
  const itemHeight = useSharedValue(0);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      setActiveDragItem(null);
    };
  }, []);

  // Watch for failure to reset
  useAnimatedReaction(
    () => dropResult.value,
    (result) => {
      if (result === "failure") {
        isDropCommitted.value = false;
        isDraggingLocal.value = false;
        runOnJS(setActiveDragItem)(null);
        dragTranslation.value = { x: 0, y: 0 };
        draggingCellKey.value = null;
        hoveredDropZoneKey.value = null;
      }
    },
    [dropResult]
  );

  const panGesture = Gesture.Pan()
    .onStart(() => {
      const measurement = measure(animatedRef);

      if (measurement) {
        isDropCommitted.value = false;
        itemWidth.value = measurement.width;
        itemHeight.value = measurement.height;

        // 1. Show Overlay
        runOnJS(setActiveDragItem)({
          type: "template", // Specify type
          shift: shift, // Pass the TemplateShift object
          wage: wage || 0,
          startX: measurement.pageX,
          startY: measurement.pageY,
          width: measurement.width,
          height: measurement.height,
        });

        // 2. Hide Local
        isDraggingLocal.value = true;
        // Key format: "employeeId-dayOfWeek"
        draggingCellKey.value = `${shift.employeeId}-${shift.dayOfWeek}`;
        dropResult.value = "idle";
        dragTranslation.value = { x: 0, y: 0 };
      }
    })
    .onUpdate((e) => {
      dragTranslation.value = { x: e.translationX, y: e.translationY };

      const layouts = dropZoneLayouts.value;
      const ownKey = `${shift.employeeId}-${shift.dayOfWeek}`;
      const ownLayout = layouts[ownKey];
      if (!ownLayout) return;

      const CELL_PADDING = 8;
      const centerX =
        ownLayout.x + CELL_PADDING + itemWidth.value / 2 + e.translationX;
      const centerY =
        ownLayout.y + CELL_PADDING + itemHeight.value / 2 + e.translationY;

      let foundZone = false;
      for (const key in layouts) {
        const layout = layouts[key];
        if (
          centerX > layout.x &&
          centerX < layout.x + layout.width &&
          centerY > layout.y &&
          centerY < layout.y + layout.height
        ) {
          hoveredDropZoneKey.value = key;
          foundZone = true;
          break;
        }
      }
      if (!foundZone) {
        hoveredDropZoneKey.value = null;
      }
    })
    .onEnd(() => {
      const originalKey = `${shift.employeeId}-${shift.dayOfWeek}`;
      if (
        hoveredDropZoneKey.value &&
        hoveredDropZoneKey.value !== originalKey
      ) {
        isDropCommitted.value = true;

        // Key format: "employeeId-dayOfWeek"
        const parts = hoveredDropZoneKey.value.split("-");
        const newEmployeeId = parts[0];
        const newDayOfWeek = parseInt(parts[1], 10);

        runOnJS(onShiftDrop)(shift, newEmployeeId, newDayOfWeek);
      }
    })
    .onFinalize(() => {
      if (!isDropCommitted.value) {
        isDraggingLocal.value = false;
        runOnJS(setActiveDragItem)(null);
        draggingCellKey.value = null;
        hoveredDropZoneKey.value = null;
        dragTranslation.value = { x: 0, y: 0 };
      } else {
        draggingCellKey.value = null;
        hoveredDropZoneKey.value = null;
      }
    });

  const containerStyle = useAnimatedStyle(() => ({
    opacity: isDraggingLocal.value ? 0 : 1,
  }));

  return (
    <GestureDetector gesture={panGesture}>
      <Animated.View ref={animatedRef} style={containerStyle}>
        <TemplateShiftChip
          shift={shift}
          wage={wage}
          onClick={() => onShiftClick(shift)}
        />
      </Animated.View>
    </GestureDetector>
  );
};

