import { useDropZoneContext } from "@/contexts/DropZoneContext";
import { TemplateShift } from "@/lib/types";
import { EmployeeProfile } from "@/stores/useEmployeeStore";
import {
  addDays,
  differenceInMinutes,
  format,
  getDay,
  isValid,
  parseISO,
} from "date-fns";
import { Plus } from "lucide-react-native";
import React, { useEffect, useRef } from "react";
import {
  findNodeHandle,
  ScrollView,
  Text,
  TouchableOpacity,
  UIManager,
  View,
} from "react-native";
import Animated, { runOnUI, useAnimatedStyle } from "react-native-reanimated";
import { DraggableTemplateShift } from "./DraggableTemplateShift";

interface TemplateGridProps {
  shifts: TemplateShift[];
  employees: EmployeeProfile[];
  onShiftPress: (shift: TemplateShift) => void;
  onAddShift: (employeeId: string, dayOfWeek: number) => void;
  onShiftDrop: (
    draggedShift: TemplateShift,
    newEmployeeId: string,
    newDayOfWeek: number
  ) => void; // New prop for handling drops
}

const startOfWeek = new Date("2024-01-01T00:00:00.000Z");

function getWeekDates(): Date[] {
  return Array.from({ length: 7 }, (_, i) => addDays(startOfWeek, i));
}

const TemplateCell = React.memo(
  ({
    children,
    employeeId,
    dayOfWeek,
    ancestor,
  }: {
    children: React.ReactNode;
    employeeId: string;
    dayOfWeek: number;
    ancestor: React.RefObject<ScrollView | null>;
  }) => {
    const { dropZoneLayouts, hoveredDropZoneKey, draggingCellKey } = useDropZoneContext();
    const cellKey = `${employeeId}-${dayOfWeek}`;
    const viewRef = useRef<Animated.View>(null);

    useEffect(() => {
      const measure = () => {
        if (viewRef.current && ancestor.current) {
          const ancestorNodeHandle = findNodeHandle(ancestor.current);
          const viewNodeHandle = findNodeHandle(viewRef.current);

          if (ancestorNodeHandle && viewNodeHandle) {
            UIManager.measureLayout(
              viewNodeHandle,
              ancestorNodeHandle,
              () => {}, // onFail
              (x, y, width, height) => {
                if (width > 0 && height > 0) {
                  runOnUI(() => {
                    "worklet";
                    const newLayouts = { ...dropZoneLayouts.value };
                    newLayouts[cellKey] = { x, y, width, height };
                    dropZoneLayouts.value = newLayouts;
                  })();
                }
              }
            );
          }
        }
      };

      const timeoutId = setTimeout(measure, 150);
      return () => clearTimeout(timeoutId);
    }, [ancestor, cellKey, dropZoneLayouts]);

    const animatedStyle = useAnimatedStyle(() => {
      const isHovered = hoveredDropZoneKey.value === cellKey;
      const isDraggingFromThisCell = draggingCellKey.value === cellKey; // Check if this cell is the origin of the drag
      return {
        borderColor: isHovered ? "#22c55e" : "#4b5563",
        borderWidth: isHovered ? 2 : 1,
        backgroundColor: isHovered ? "#3a3a3a" : "#2a2a2a",
        zIndex: isDraggingFromThisCell ? 100 : 1, // Elevate zIndex if dragging from this cell
      };
    });

    return (
      <Animated.View
        ref={viewRef}
        style={animatedStyle}
        className="flex-1 min-w-[160px] p-2 border-r border-b"
      >
        {children}
      </Animated.View>
    );
  }
);

const TemplateGrid: React.FC<TemplateGridProps> = ({
  shifts,
  employees,
  onShiftPress,
  onAddShift,
  onShiftDrop, // Destructure new prop
}) => {
  const weekDates = getWeekDates();
  const scrollViewRef = useRef<ScrollView>(null);

  const getShiftsForDayAndEmployee = (
    dayOfWeek: number,
    employeeId: string
  ) => {
    return shifts.filter(
      (s) => s.dayOfWeek === dayOfWeek && s.employeeId === employeeId
    );
  };

  const calculateTotalHours = (employeeId: string) => {
    const totalMinutes = shifts
      .filter((s) => s.employeeId === employeeId)
      .reduce((total, shift) => {
        if (!shift.startTime || !shift.endTime) return total;
        const start = parseISO(shift.startTime);
        const end = parseISO(shift.endTime);
        if (!isValid(start) || !isValid(end)) return total;
        return total + differenceInMinutes(end, start);
      }, 0);
    return (totalMinutes / 60).toFixed(1);
  };

  return (
    <View className="flex-1 bg-[#1c1c1c] rounded-lg overflow-hidden">
      <ScrollView horizontal contentContainerStyle={{ flexGrow: 1 }}>
        <View className="flex-1 flex-col">
          {/* Header */}
          <View className="flex-row bg-[#212121] sticky top-0 z-10">
            <View className="w-56 bg-[#212121] p-4 border-r border-b border-gray-700">
              <Text className="text-base font-bold text-white">Employee</Text>
            </View>
            {weekDates.map((date, i) => (
              <View
                key={i}
                className="flex-1 min-w-[160px] bg-[#212121] p-3 text-center border-r border-b border-gray-700 items-center justify-center"
              >
                <Text className="text-sm font-semibold text-gray-300">
                  {format(date, "E")}
                </Text>
              </View>
            ))}
          </View>

          {/* Grid Body */}
          <ScrollView ref={scrollViewRef}>
            {employees.map((employee) => (
              <View key={employee.id} className="flex-row items-stretch">
                <View className="w-56 bg-[#2a2a2a] p-3 flex-row items-center border-r border-b border-gray-700">
                  <View className="w-12 h-12 rounded-full bg-blue-600 items-center justify-center mr-4 shadow-md">
                    <Text className="text-white font-bold text-xl">
                      {employee.fullName
                        .split(" ")
                        .map((n) => n[0])
                        .join("")}
                    </Text>
                  </View>
                  <View className="flex-1">
                    <Text
                      className="text-lg font-semibold text-white"
                      numberOfLines={1}
                    >
                      {employee.fullName}
                    </Text>
                    <Text className="text-sm text-gray-400">
                      {employee.role}
                    </Text>
                    <Text className="text-xs text-gray-500 mt-1">
                      Total: {calculateTotalHours(employee.id)}h
                    </Text>
                  </View>
                </View>
                {weekDates.map((date) => {
                  const dayOfWeek = getDay(date);
                  const dayShifts = getShiftsForDayAndEmployee(
                    dayOfWeek,
                    employee.id
                  );
                  return (
                    <TemplateCell
                      key={`${employee.id}-${dayOfWeek}`}
                      employeeId={employee.id}
                      dayOfWeek={dayOfWeek}
                      ancestor={scrollViewRef}
                    >
                      <View className="flex-1 justify-center">
                        {dayShifts.length > 0 ? (
                          <View className="gap-y-2">
                            {dayShifts.map((shift) => (
                              <DraggableTemplateShift
                                key={shift.tempId}
                                shift={shift}
                                onShiftClick={onShiftPress}
                                onShiftDrop={onShiftDrop} // Pass prop down
                                wage={employee.baseWage}
                              />
                            ))}
                          </View>
                        ) : (
                          <TouchableOpacity
                            onPress={() => onAddShift(employee.id, dayOfWeek)}
                            className="flex-1 h-full w-full items-center justify-center border-2 border-dashed border-gray-600 rounded-lg hover:bg-gray-700/50 transition-colors"
                          >
                            <Plus size={20} color="#6b7280" />
                          </TouchableOpacity>
                        )}
                      </View>
                    </TemplateCell>
                  );
                })}
              </View>
            ))}
          </ScrollView>
        </View>
      </ScrollView>
    </View>
  );
};

export default TemplateGrid;

import BottomSheet, {
  BottomSheetBackdrop,
  BottomSheetView,
} from "@gorhom/bottom-sheet";
import { Clock, X } from "lucide-react-native";
import React, { useEffect, useMemo, useState } from "react";
import { Text, TouchableOpacity, View } from "react-native";

interface OperatingHoursTimeSheetProps {
  bottomSheetRef: React.RefObject<BottomSheet | null>;
  initialTime: string; // e.g., "09:00 AM"
  day: string;
  type: "open" | "close";
  onSave: (time: string) => void;
  onClose: () => void;
}

export const OperatingHoursTimeSheet: React.FC<
  OperatingHoursTimeSheetProps
> = ({ bottomSheetRef, initialTime, day, type, onSave, onClose }) => {
  const [hour, setHour] = useState(9);
  const [minute, setMinute] = useState(0);
  const [ampm, setAmPm] = useState<"AM" | "PM">("AM");

  const snapPoints = useMemo(() => ["50%"], []);

  useEffect(() => {
    if (initialTime) {
      // Parse "09:00 AM" or similar
      const parts = initialTime.split(" ");
      if (parts.length >= 2) {
        const [timePart, periodPart] = parts;
        const [hStr, mStr] = timePart.split(":");
        const h = parseInt(hStr, 10);
        const m = parseInt(mStr, 10);

        if (!isNaN(h)) setHour(h);
        if (!isNaN(m)) setMinute(m);
        if (periodPart === "AM" || periodPart === "PM") setAmPm(periodPart);
      }
    }
  }, [initialTime]);

  const changeHour = (delta: number) => {
    setHour((prev) => {
      let next = prev + delta;
      if (next > 12) next = 1;
      if (next < 1) next = 12;
      return next;
    });
  };

  const changeMinute = (delta: number) => {
    setMinute((prev) => {
      let next = prev + delta;
      if (next >= 60) next = 0;
      if (next < 0) next = 45; // Cycling back from 0 goes to 45 (assuming 15 min steps)
      return next;
    });
  };

  // Helper to toggle minutes between 0, 15, 30, 45
  const cycleMinute = () => {
    setMinute((prev) => (prev + 15) % 60);
  };

  // Or just simple +/- 15 if that's preferred
  // I will implementation +/- 15 logic because "Cycle" button is not what I built before.
  // The previous implementation used +/- buttons. I will stick to +/- buttons logic but with 15 steps.

  const toggleAmPm = () => {
    setAmPm((prev) => (prev === "AM" ? "PM" : "AM"));
  };

  const handleSave = () => {
    const minStr = String(minute).padStart(2, "0");
    const hourStr = String(hour).padStart(2, "0");
    onSave(`${hourStr}:${minStr} ${ampm}`);
    onClose();
  };

  const renderBackdrop = (props: any) => (
    <BottomSheetBackdrop
      {...props}
      disappearsOnIndex={-1}
      appearsOnIndex={0}
      opacity={0.7}
    />
  );

  return (
    <BottomSheet
      ref={bottomSheetRef}
      index={-1}
      snapPoints={snapPoints}
      enablePanDownToClose
      onClose={onClose}
      handleIndicatorStyle={{ backgroundColor: "#9CA3AF" }}
      backgroundStyle={{ backgroundColor: "#303030" }}
      backdropComponent={renderBackdrop}
    >
      <BottomSheetView className="p-5 flex-1 bg-[#303030]">
        {/* Header */}
        <View className="flex-row items-center justify-between mb-6">
          <View>
            <Text className="text-xl font-bold text-white">
              Set {type === "open" ? "Opening" : "Closing"} Time
            </Text>
            <Text className="text-gray-400 text-sm mt-1">{day}</Text>
          </View>
          <TouchableOpacity
            onPress={onClose}
            className="p-2 bg-[#404040] rounded-full"
          >
            <X size={20} color="#9ca3af" />
          </TouchableOpacity>
        </View>

        {/* Current Time Context */}
        <View className="flex-row items-center justify-center mb-6">
          <Clock size={16} color="#f97316" />
          <Text className="text-orange-500 text-sm font-bold ml-2">
            SELECTED: {hour}:{String(minute).padStart(2, "0")} {ampm}
          </Text>
        </View>

        {/* Custom Time Picker UI */}
        <View className="flex-row items-center justify-center gap-2 p-4 bg-[#252525] border border-gray-700 rounded-xl self-center mb-8">
          {/* Hours */}
          <View className="flex-row items-center">
            <TouchableOpacity onPress={() => changeHour(-1)} className="p-3">
              <Text className="text-white text-2xl font-bold">-</Text>
            </TouchableOpacity>
            <Text className="text-white text-3xl font-bold w-16 text-center">
              {hour}
            </Text>
            <TouchableOpacity onPress={() => changeHour(1)} className="p-3">
              <Text className="text-white text-2xl font-bold">+</Text>
            </TouchableOpacity>
          </View>

          <Text className="text-gray-400 text-3xl font-bold pb-1">:</Text>

          {/* Minutes */}
          <View className="flex-row items-center">
            <TouchableOpacity onPress={() => changeMinute(-15)} className="p-3">
              <Text className="text-white text-2xl font-bold">-</Text>
            </TouchableOpacity>
            <Text className="text-white text-3xl font-bold w-16 text-center">
              {String(minute).padStart(2, "0")}
            </Text>
            <TouchableOpacity onPress={() => changeMinute(15)} className="p-3">
              <Text className="text-white text-2xl font-bold">+</Text>
            </TouchableOpacity>
          </View>

          {/* AM/PM */}
          <TouchableOpacity
            onPress={toggleAmPm}
            className="ml-4 px-4 py-3 rounded-lg bg-[#353535] border border-gray-600"
          >
            <Text className="text-white text-xl font-bold">{ampm}</Text>
          </TouchableOpacity>
        </View>

        {/* Save Button */}
        <TouchableOpacity
          onPress={handleSave}
          className="w-full bg-blue-600 py-4 rounded-xl items-center shadow-lg shadow-blue-900/50 mt-auto"
        >
          <Text className="text-white font-bold text-lg">Set Time</Text>
        </TouchableOpacity>
      </BottomSheetView>
    </BottomSheet>
  );
};

