import { cn } from "@/lib/utils";
import React, { useEffect, useRef, useState } from "react";
import { LayoutChangeEvent, PanResponder, View } from "react-native";
import Animated, {
  useAnimatedStyle,
  useSharedValue,
} from "react-native-reanimated";

interface CustomSliderProps {
  value: number;
  onValueChange: (val: number) => void;
  min?: number;
  max?: number;
  step?: number;
  className?: string;
  disabled?: boolean;
}

const CustomSlider: React.FC<CustomSliderProps> = ({
  value,
  onValueChange,
  min = 0,
  max = 100,
  step = 1,
  className,
  disabled = false,
}) => {
  const [width, setWidth] = useState(0);
  const translateX = useSharedValue(0);

  // Refs to hold latest values (fixes Stale Closures in PanResponder)
  const widthRef = useRef(0);
  const minRef = useRef(min);
  const maxRef = useRef(max);
  const stepRef = useRef(step);
  const onValueChangeRef = useRef(onValueChange);
  const isScrubbing = useRef(false);
  const gestureStartX = useRef(0);

  // Update refs whenever props change
  useEffect(() => {
    widthRef.current = width;
    minRef.current = min;
    maxRef.current = max;
    stepRef.current = step;
    onValueChangeRef.current = onValueChange;
  }, [width, min, max, step, onValueChange]);

  // Helper: Calculate pixels from value
  // We pass currentWidth explicitly to ensure accuracy
  const getTranslateFromValue = (v: number, currentWidth: number) => {
    if (currentWidth === 0) return 0;
    const percentage = (v - min) / (max - min);
    return percentage * currentWidth;
  };

  // Helper: Calculate value from pixels
  // We pass currentWidth/min/max explicitly to avoid using stale state
  const getValueFromTranslate = (
    t: number,
    currentWidth: number,
    currentMin: number,
    currentMax: number,
    currentStep: number
  ) => {
    if (currentWidth === 0) return currentMin;

    const percentage = Math.min(Math.max(t / currentWidth, 0), 1);
    let newValue = currentMin + percentage * (currentMax - currentMin);

    if (currentStep > 0) {
      newValue = Math.round(newValue / currentStep) * currentStep;
    }

    // Floating point correction (e.g. 5.00000001 -> 5)
    newValue = parseFloat(newValue.toFixed(2));

    return Math.min(Math.max(newValue, currentMin), currentMax);
  };

  // Sync visual thumb with external value prop
  // Only runs when NOT dragging
  useEffect(() => {
    if (width > 0 && !isScrubbing.current) {
      translateX.value = getTranslateFromValue(value, width);
    }
  }, [value, width, min, max]);

  const pr = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => !disabled,
      onMoveShouldSetPanResponder: () => !disabled,
      onPanResponderTerminationRequest: () => false,

      onPanResponderGrant: (evt, gestureState) => {
        isScrubbing.current = true;
        gestureStartX.current = translateX.value;
      },

      onPanResponderMove: (evt, gestureState) => {
        const currentWidth = widthRef.current;
        const currentMin = minRef.current;
        const currentMax = maxRef.current;
        const currentStep = stepRef.current;

        if (currentWidth === 0) return;

        // 1. Calculate new pixel position
        let newX = gestureStartX.current + gestureState.dx;

        // 2. Clamp visually
        newX = Math.min(Math.max(newX, 0), currentWidth);

        // 3. Update SharedValue (UI Thread)
        translateX.value = newX;

        // 4. Calculate Logic Value
        const newValue = getValueFromTranslate(
          newX,
          currentWidth,
          currentMin,
          currentMax,
          currentStep
        );

        // 5. Call Parent
        onValueChangeRef.current(newValue);
      },

      onPanResponderRelease: () => {
        isScrubbing.current = false;
      },
    })
  ).current;

  const activeTrackStyle = useAnimatedStyle(() => ({
    width: translateX.value,
  }));

  const thumbStyle = useAnimatedStyle(() => ({
    transform: [{ translateX: translateX.value - 12 }], // Center 24px thumb
  }));

  return (
    <View
      className={cn("h-10 justify-center", className)}
      onLayout={(e: LayoutChangeEvent) => {
        const w = e.nativeEvent.layout.width;
        setWidth(w);
        widthRef.current = w; // Update ref immediately
      }}
      {...pr.panHandlers}
    >
      {/* Background Track */}
      <View className="h-2 bg-gray-700 rounded-full w-full overflow-hidden pointer-events-none">
        <Animated.View
          className="h-full bg-blue-500"
          style={activeTrackStyle}
        />
      </View>

      {/* Thumb */}
      <Animated.View
        className="absolute w-6 h-6 bg-white rounded-full shadow-md border border-gray-300"
        style={[{ left: 0 }, thumbStyle]}
      />
    </View>
  );
};

export default CustomSlider;

import * as React from 'react';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withSequence,
  withTiming,
} from 'react-native-reanimated';
import { cn } from '~/lib/utils';

const duration = 1000;

function Skeleton({
  className,
  ...props
}: Omit<React.ComponentPropsWithoutRef<typeof Animated.View>, 'style'>) {
  const sv = useSharedValue(1);

  React.useEffect(() => {
    sv.value = withRepeat(
      withSequence(withTiming(0.5, { duration }), withTiming(1, { duration })),
      -1
    );
  }, []);

  const style = useAnimatedStyle(() => ({
    opacity: sv.value,
  }));

  return (
    <Animated.View
      style={style}
      className={cn('rounded-md bg-secondary dark:bg-muted', className)}
      {...props}
    />
  );
}

export { Skeleton };

import React, { useRef } from "react";
import { PanResponder, View } from "react-native";
import Animated, {
  runOnJS,
  useAnimatedStyle,
  useSharedValue,
} from "react-native-reanimated";

interface SliderProps {
  value: number;
  min: number;
  max: number;
  step?: number;
  onValueChange: (value: number) => void;
  width?: number;
}

const Slider: React.FC<SliderProps> = ({
  value,
  min,
  max,
  step = 1,
  onValueChange,
  width = 200,
}) => {
  const trackWidth = width;
  const thumbWidth = 20;
  const maxTranslate = trackWidth - thumbWidth;

  const getTranslateFromValue = (v: number) => {
    return ((v - min) / (max - min)) * maxTranslate;
  };

  const getValueFromTranslate = (t: number) => {
    const rawValue = (t / maxTranslate) * (max - min) + min;
    const steppedValue = Math.round(rawValue / step) * step;
    return Math.max(min, Math.min(max, steppedValue));
  };

  const translateX = useSharedValue(getTranslateFromValue(value));

  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onPanResponderMove: (_, gestureState) => {
        let newX = getTranslateFromValue(value) + gestureState.dx;
        newX = Math.max(0, Math.min(maxTranslate, newX));
        translateX.value = newX;
        const newValue = getValueFromTranslate(newX);
        runOnJS(onValueChange)(newValue);
      },
      onPanResponderRelease: () => {
        // Optional: snap to step visually if desired
      },
    })
  ).current;

  // Sync external value changes
  React.useEffect(() => {
    translateX.value = getTranslateFromValue(value);
  }, [value]);

  const thumbStyle = useAnimatedStyle(() => ({
    transform: [{ translateX: translateX.value }],
  }));

  const filledTrackStyle = useAnimatedStyle(() => ({
    width: translateX.value + thumbWidth / 2,
  }));

  return (
    <View
      style={{ width: trackWidth, height: 40, justifyContent: "center" }}
      {...panResponder.panHandlers}
    >
      {/* Track Background */}
      <View className="absolute w-full h-1 bg-gray-700 rounded-full" />

      {/* Filled Track */}
      <Animated.View
        className="absolute h-1 bg-blue-500 rounded-full"
        style={filledTrackStyle}
      />

      {/* Thumb */}
      <Animated.View
        style={[
          {
            width: thumbWidth,
            height: thumbWidth,
            borderRadius: thumbWidth / 2,
            position: "absolute",
            backgroundColor: "white",
            borderWidth: 1,
            borderColor: "#3b82f6",
          },
          thumbStyle,
        ]}
      />
    </View>
  );
};

export default Slider;

import { Dialog, DialogContent } from "@/components/ui/dialog";
import React, {
  createContext,
  ReactNode,
  useCallback,
  useContext,
  useState,
} from "react";
import { ActivityIndicator, Text, View } from "react-native";

interface LoadingContextType {
  showLoading: (message?: string) => void;
  hideLoading: () => void;
  isLoading: boolean;
}

const LoadingContext = createContext<LoadingContextType | undefined>(undefined);

export const useLoading = () => {
  const context = useContext(LoadingContext);
  if (!context) {
    throw new Error("useLoading must be used within a LoadingProvider");
  }
  return context;
};

export const LoadingProvider = ({ children }: { children: ReactNode }) => {
  const [isLoading, setIsLoading] = useState(false);
  const [message, setMessage] = useState<string | undefined>(undefined);

  const showLoading = useCallback((msg?: string) => {
    setMessage(msg);
    setIsLoading(true);
  }, []);

  const hideLoading = useCallback(() => {
    setIsLoading(false);
    setMessage(undefined);
    console.log("[hideLoading] isLoading", isLoading);
  }, []);

  return (
    <LoadingContext.Provider value={{ showLoading, hideLoading, isLoading }}>
      {children}

      {/* Global Loading Dialog */}
      <Dialog open={isLoading}>
        <DialogContent className="w-fit min-w-[120px] max-w-[280px]">
          <View className="rounded-2xl p-6 items-center bg-[#1a1a1a] border border-gray-800">
            {/* Glowing spinner container */}
            <View className="relative mb-4">
              {/* Outer glow ring */}
              <View
                className="absolute -inset-2 rounded-full opacity-30"
                style={{
                  backgroundColor: "#3B82F6",
                  shadowColor: "#3B82F6",
                  shadowOffset: { width: 0, height: 0 },
                  shadowOpacity: 0.8,
                  shadowRadius: 20,
                }}
              />
              {/* Spinner background */}
              <View className="w-16 h-16 rounded-full bg-gray-800/50 items-center justify-center border border-gray-700">
                <ActivityIndicator size="large" color="#3B82F6" />
              </View>
            </View>

            {/* Message (only if provided) */}
            {message && (
              <Text className="text-gray-200 text-base font-medium text-center">
                {message}
              </Text>
            )}

            {/* Decorative dots animation placeholder */}
            <View className="flex-row gap-1.5 mt-3">
              <View className="w-2 h-2 rounded-full bg-blue-500 opacity-80" />
              <View className="w-2 h-2 rounded-full bg-blue-500 opacity-50" />
              <View className="w-2 h-2 rounded-full bg-blue-500 opacity-30" />
            </View>
          </View>
        </DialogContent>
      </Dialog>
    </LoadingContext.Provider>
  );
};

// providers/LocationRealtimeProvider.tsx
// Centralized provider for all location-scoped realtime subscriptions

import { useFloorRealtime } from '@/hooks/realtime/useFloorRealtime';
import { createContext, ReactNode, useCallback, useContext } from 'react';
// import { useWaitlistRealtime } from '@/hooks/useWaitlistRealtime';
// import { useOrdersRealtime } from '@/hooks/useOrdersRealtime';
import { useOrdersRealtime } from '@/hooks/realtime/useOrdersRealtime';
import type {
  ChannelStatus,
  OrderPayload,
  PaymentPayload,
  SessionEventPayload,
  TableAssignmentPayload,
  TableSessionPayload,
  WaitlistPayload,
} from '@/types/real-time';

// ============================================================================
// Types
// ============================================================================

interface RealtimeChannelState {
  status: ChannelStatus;
  isConnected: boolean;
  isReconnecting: boolean;
  reconnect: () => void;
}

interface LocationRealtimeContextValue {
  /** Floor/tables channel state */
  floor: RealtimeChannelState;
  /** Waitlist channel state */
//   waitlist: RealtimeChannelState;
  /** Orders channel state */
  orders: RealtimeChannelState;
  /** Reconnect all channels */
  reconnectAll: () => void;
  /** Disconnect all channels */
  disconnectAll: () => void;
  /** True if all channels are connected */
  allConnected: boolean;
  /** True if any channel is attempting to reconnect */
  isReconnecting: boolean;
  /** Location ID this provider is scoped to */
  locationId: string;
}

interface LocationRealtimeProviderProps {
  /** Location ID to scope subscriptions */
  locationId: string;
  children: ReactNode;
  /** Enable/disable all subscriptions */
  enabled?: boolean;
  /** Callbacks for handling events (optional) */
  callbacks?: {
    onSessionChange?: (payload: TableSessionPayload) => void;
    onTableAssignment?: (payload: TableAssignmentPayload) => void;
    onSessionEvent?: (payload: SessionEventPayload) => void;
    onWaitlistChange?: (payload: WaitlistPayload) => void;
    onOrderChange?: (payload: OrderPayload) => void;
    onPaymentChange?: (payload: PaymentPayload) => void;
  };
}

// ============================================================================
// Context
// ============================================================================

const LocationRealtimeContext = createContext<LocationRealtimeContextValue | null>(null);

// ============================================================================
// Provider
// ============================================================================

/**
 * Provider that manages all location-scoped realtime subscriptions
 *
 * Wraps your location-specific screens to provide:
 * - Floor/table updates
 * - Waitlist updates
 * - Order/payment updates
 *
 * @example
 * ```tsx
 * <LocationRealtimeProvider locationId={currentLocationId}>
 *   <FloorPlanScreen />
 * </LocationRealtimeProvider>
 * ```
 */
export function LocationRealtimeProvider({
  locationId,
  children,
  enabled = true,
  callbacks,
}: LocationRealtimeProviderProps) {
  // Floor realtime subscription
  const floorRealtime = useFloorRealtime({
    locationId,
    enabled,
    onSessionChange: callbacks?.onSessionChange,
    onTableAssignment: callbacks?.onTableAssignment,
    onSessionEvent: callbacks?.onSessionEvent,
    onOrderUpdate: callbacks?.onOrderChange,
  });

  // Waitlist realtime subscription
//   const waitlistRealtime = useWaitlistRealtime({
//     locationId,
//     enabled,
//     onWaitlistChange: callbacks?.onWaitlistChange,
//   });

//   // Orders realtime subscription
  const ordersRealtime = useOrdersRealtime({
    locationId,
    enabled,
    onOrderChange: callbacks?.onOrderChange,
    onPaymentChange: callbacks?.onPaymentChange,
  });

  // Reconnect all channels
  const reconnectAll = useCallback(() => {
    console.log('[LocationRealtime] Reconnecting all channels...');
    floorRealtime.reconnect();
    // waitlistRealtime.reconnect();
    ordersRealtime.reconnect();
  }, [floorRealtime]);

  // Disconnect all channels
  const disconnectAll = useCallback(() => {
    console.log('[LocationRealtime] Disconnecting all channels...');
    floorRealtime.disconnect();
    // waitlistRealtime.disconnect();
    ordersRealtime.disconnect();
  }, [floorRealtime]);

  // Aggregate status
  const allConnected =
    floorRealtime.isConnected  && 
    // waitlistRealtime.isConnected &&
    ordersRealtime.isConnected;

  const isReconnecting =
    floorRealtime.isReconnecting || 
    // waitlistRealtime.isReconnecting ||
    ordersRealtime.isReconnecting;

  const value: LocationRealtimeContextValue = {
    floor: {
      status: floorRealtime.connectionStatus,
      isConnected: floorRealtime.isConnected,
      isReconnecting: floorRealtime.isReconnecting,
      reconnect: floorRealtime.reconnect,
    },
    // waitlist: {
    //   status: waitlistRealtime.connectionStatus,
    //   isConnected: waitlistRealtime.isConnected,
    //   isReconnecting: waitlistRealtime.isReconnecting,
    //   reconnect: waitlistRealtime.reconnect,
    // },
    orders: {
      status: ordersRealtime.connectionStatus,
      isConnected: ordersRealtime.isConnected,
      isReconnecting: ordersRealtime.isReconnecting,
      reconnect: ordersRealtime.reconnect,
    },
    reconnectAll,
    disconnectAll,
    allConnected,
    isReconnecting,
    locationId,
  };

  return (
    <LocationRealtimeContext.Provider value={value}>
      {children}
    </LocationRealtimeContext.Provider>
  );
}

// ============================================================================
// Hook
// ============================================================================

/**
 * Hook to access location realtime state
 * Must be used within LocationRealtimeProvider
 */
export function useLocationRealtime(): LocationRealtimeContextValue {
  const context = useContext(LocationRealtimeContext);

  if (!context) {
    throw new Error(
      'useLocationRealtime must be used within a LocationRealtimeProvider'
    );
  }

  return context;
}

/**
 * Hook to check if a specific channel is connected
 */
export function useIsChannelConnected(
  channel: 'floor' | 'waitlist' | 'orders'
): boolean {
  const { floor, orders } = useLocationRealtime();

  switch (channel) {
    case 'floor':
      return floor.isConnected;
    // case 'waitlist':
    //   return waitlist.isConnected;
    case 'orders':
      return orders.isConnected;
    default:
      return false;
  }
}

import { useInventorySync } from "@/hooks/pos/useInventorySync";
import { usePosSync } from "@/hooks/pos/usePosSync";
import { useStandaloneSync } from "@/hooks/pos/useStandaloneSync";
import { useSupabaseClient } from "@/hooks/useSupabaseClient";
import { MerchantRole } from "@/lib/types";
import { FloorPlanService } from "@/services/floorPlanService";
import {
  initializeOfflineSync,
  setOfflineSyncSupabaseClient,
} from "@/services/offlineSyncInit";
import { setCoursingSupabaseClient } from "@/stores/useCoursingStore";
import { EmployeeProfile, useEmployeeStore } from "@/stores/useEmployeeStore";
import {
  setFloorPlanSupabaseClient,
  useFloorPlanStore,
} from "@/stores/useFloorPlanStore";
import { useInventoryStore } from "@/stores/useInventoryStore";
import { useMenuStore } from "@/stores/useMenuStore";
import { setOrderStoreSupabaseClient, useOrderStore } from "@/stores/useOrderStore";
import { useStoreSettingsStore } from "@/stores/useStoreSettingsStore";
import { setWaitlistSupabaseClient } from "@/stores/useWaitlistStore";
import { TaxRate } from "@/types/menu";
import React, { useCallback, useEffect, useRef } from "react";
import { AppState, AppStateStatus } from "react-native";

// Debug server URL - use your machine's local IP (run: ipconfig getifaddr en0)
// Change this IP to match your machine's IP address
const DEBUG_EMPLOYEES_URL = __DEV__
  ? "http://192.168.29.134:3456/debug/sync-data"
  : null;

/**
 * Component that handles POS sync logic.
 * Must be rendered inside ClerkProvider since it uses authenticated Supabase calls.
 */
export function PosSyncProvider({ children }: { children: React.ReactNode }) {
  // POS Sync Integration - Centralized sync for the entire app
  const selectedStore = useStoreSettingsStore((state) => state.selectedStore);
  const supabase = useSupabaseClient();
  const setEmployees = useEmployeeStore((state) => state.setEmployees);
  const setEmployeeSyncState = useEmployeeStore((state) => state.setSyncState);
  const offlineSyncInitialized = useRef(false);

  // Register Supabase client with order store, floor plan store, coursing store, and offline sync
  useEffect(() => {
    if (supabase) {
      setOrderStoreSupabaseClient(supabase);
      setFloorPlanSupabaseClient(supabase);
      setCoursingSupabaseClient(supabase);
      setOfflineSyncSupabaseClient(supabase);
      setWaitlistSupabaseClient(supabase);

      // Initialize offline sync service (only once)
      if (!offlineSyncInitialized.current) {
        offlineSyncInitialized.current = true;
        initializeOfflineSync().then(() => {
          console.log("Offline sync service initialized");
        });
      }

      console.log(
        "Supabase client registered with order, floor plan, coursing, waitlist, and offline sync"
      );
    }
    // return () => {
    //   setOrderStoreSupabaseClient(null);
    //   setFloorPlanSupabaseClient(null);
    //   setCoursingSupabaseClient(null);
    // };
  }, [supabase]);

  // Sync employees from location_members
  const syncEmployees = useCallback(
    async (locationId: string) => {
      setEmployeeSyncState({ isLoading: true, error: null });
      try {
        const { data, error } = await supabase
          .from("location_members")
          .select(
            `
          id,
          pin_code,
          role_code,
          staff_profile_id,
          staff_profiles (
            id,
            first_name,
            last_name,
            display_name,
            avatar_url,
            email,
            phone
          )
        `
          )
          .eq("location_id", locationId)
          .eq("is_active", true);

        if (error) throw error;

        // console.log("Employee Sync Data received!");
        // console.log("Employees count:", data?.length || 0);
        // console.log("Employees data:", data);

        // Map Supabase data to EmployeeProfile format
        const mappedEmployees: EmployeeProfile[] = (data || []).map(
          (row: any) => {
            const profile = row.staff_profiles;
            const fullName = `${profile?.first_name || ""} ${profile?.last_name || ""
              }`.trim();

            return {
              id: row.id, // location_member id
              profileId: profile?.id || "",
              fullName: fullName || "Unknown Staff",
              displayName: profile?.display_name || fullName || "Unknown",
              role: row.role_code as MerchantRole,
              profilePictureUrl: profile?.avatar_url || undefined,
              pinHash: row.pin_code, // bcrypt hash from DB
              email: profile?.email,
              phone: profile?.phone,
              shiftStatus: "clocked_out" as const,
            };
          }
        );

        // Update employee store with mapped data
        setEmployees(mappedEmployees);
        setEmployeeSyncState({ isLoading: false, error: null });
      } catch (err: any) {
        console.error("Employee sync failed:", err);
        setEmployeeSyncState({
          isLoading: false,
          error: err?.message || "Sync failed",
        });
      }
    },
    [supabase, setEmployees, setEmployeeSyncState]
  );

  // Sync floor plans from backend
  const syncFloorPlans = useCallback(
    async (locationId: string) => {
      try {
        // Load floor plans for location
        const { data: floorPlans, error: fpError } =
          await FloorPlanService.getLocationFloorPlans(supabase, locationId);

        if (fpError) throw fpError;

        // Find default or first floor plan
        const defaultPlan =
          floorPlans?.find((fp) => fp.is_default) || floorPlans?.[0];

        // Set floor plans in store
        useFloorPlanStore.setState({ locationId });
        useFloorPlanStore.getState().setFloorPlans(floorPlans || []);
        useFloorPlanStore
          .getState()
          .setActiveFloorPlanId(defaultPlan?.id || null);

        // Load status if we have a floor plan
        if (defaultPlan?.id) {
          await useFloorPlanStore.getState().setActiveFloorPlan(defaultPlan.id);
        }

        // Load waitlist and reservations
        await Promise.all([
          useFloorPlanStore.getState().loadWaitlist(),
          useFloorPlanStore.getState().loadReservations(),
        ]);
      } catch (error: any) {
        console.error("Floor plan sync failed:", error);
      }
    },
    [supabase]
  );

  // Sync tax rates from tax_rates table
  const syncTaxRates = useCallback(
    async (locationId: string) => {
      try {
        const { data, error } = await supabase
          .from("tax_rates")
          .select(
            "id, location_id, name, percentage, tax_category, is_active, created_at, updated_at"
          )
          .eq("location_id", locationId)
          .eq("is_active", true);

        if (error) {
          console.error("Tax rates sync failed:", error);
          return;
        }

        const taxRates = (data || []) as TaxRate[];
        useStoreSettingsStore.getState().setTaxRates(taxRates);
        // console.log("Tax rates synced:", taxRates.length);
      } catch (err: any) {
        console.error("Tax rates sync error:", err);
      }
    },
    [supabase]
  );

  // Sync employees and floor plans when store is selected (parallel)
  useEffect(() => {
    if (selectedStore?.id) {
      syncEmployees(selectedStore.id);
      syncFloorPlans(selectedStore.id);
      syncTaxRates(selectedStore.id);
    }
  }, [selectedStore?.id, syncEmployees, syncFloorPlans, syncTaxRates]);
  const setMenuData = useMenuStore((state) => state.setMenuData);
  const setSyncState = useMenuStore((state) => state.setSyncState);

  // Fetch menu data from API when store is selected
  const {
    data: posSyncData,
    isLoading: isSyncing,
    isError: isSyncError,
    error: syncError,
  } = usePosSync(selectedStore?.id ?? null);

  // Fetch standalone entities (categories, items, modifiers not in menus)
  const { data: standaloneData } = useStandaloneSync(
    selectedStore?.merchant_id ?? null,
    selectedStore?.id ?? null
  );

  // --- INVENTORY SYNC ---
  const { data: inventoryData } = useInventorySync(selectedStore?.id ?? null);
  const setInventoryData = useInventoryStore((state) => state.setInventoryData);
  const setInventorySupabase = useInventoryStore(
    (state) => state.setSupabaseClient
  );

  useEffect(() => {
    if (supabase) {
      setInventorySupabase(supabase);
    }
  }, [supabase]);

  // Helper to merge recipes into menu store
  const applyRecipes = (data: typeof inventoryData) => {
    if (!data) return;
    if (data.menuRecipes?.length || data.modifierRecipes?.length) {
      useMenuStore.getState().mergeRecipeData({
        menuRecipes: data.menuRecipes.map((r) => ({
          menu_item_id: r.menu_item_id,
          inventory_item_id: r.inventory_item_id,
          quantity: r.quantity_used,
        })),
        modifierRecipes: data.modifierRecipes.map((r) => ({
          modifier_group_item_id: r.modifier_group_item_id,
          inventory_item_id: r.inventory_item_id,
          quantity: r.quantity_used,
        })),
      });
    }
  };

  useEffect(() => {
    if (inventoryData) {
      setInventoryData({
        items: inventoryData.inventoryItems,
        vendors: inventoryData.vendors,
      });

      // Merge Recipe Data into MenuStore
      applyRecipes(inventoryData);

      console.log(
        "✅ Inventory & Recipe data synced:",
        inventoryData.inventoryItems.length,
        "items,",
        inventoryData.menuRecipes?.length || 0,
        "menu recipes"
      );
    }
  }, [inventoryData]);
  // --- END INVENTORY SYNC ---

  // Update menu store when sync data changes
  useEffect(() => {
    if (posSyncData) {
      setMenuData(posSyncData);

      // Re-apply recipes if available (since setMenuData might reset them)
      applyRecipes(inventoryData);

      // Send menu data to debug server in development
      const DEBUG_MENU_URL = __DEV__
        ? "http://192.168.29.134:3456/debug/sync-data"
        : null;

      if (DEBUG_MENU_URL) {
        fetch(DEBUG_MENU_URL, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            menuData: posSyncData,
            locationId: selectedStore?.id,
          }),
        })
          .then((res) => res.json())
          .then((result) => {
            if (result.success) {
              console.log("✅ Menu data sent to debug server:", result.path);
            }
          })
          .catch((err) => {
            console.log("Debug server not running (optional):", err.message);
          });
      }
    }
  }, [posSyncData, setMenuData, selectedStore?.id, inventoryData]);

  // Merge standalone data (categories, items, modifiers, menus including inactive)
  useEffect(() => {
    if (standaloneData) {
      const menuStore = useMenuStore.getState();
      menuStore.mergeStandaloneData(standaloneData);

      // Re-apply recipes if available (since mergeStandaloneData might overwrite items)
      applyRecipes(inventoryData);

      console.log("✅ Standalone data merged:", {
        categories: standaloneData.categories?.length || 0,
        items: standaloneData.items?.length || 0,
        modifierGroups: standaloneData.modifierGroups?.length || 0,
        menus: standaloneData.menus?.length || 0,
      });
    }
  }, [standaloneData, inventoryData]);

  // Floor plan sync is now handled in the combined useEffect above

  // Update sync state in store
  // useEffect(() => {
  //   setSyncState({
  //     isLoading: isSyncing,
  //     isError: isSyncError,
  //     error: syncError instanceof Error ? syncError : null,
  //   });
  // }, [isSyncing, isSyncError, syncError, setSyncState]);

  // Setup and cleanup realtime subscriptions for floor plans and orders
  // Use a ref to track if we've already subscribed to prevent duplicate setups
  const realtimeLocationRef = useRef<string | null>(null);

  useEffect(() => {
    const locationId = selectedStore?.id;

    if (!locationId) {
      return;
    }

    // Skip if already subscribed to this location
    if (realtimeLocationRef.current === locationId) {
      return;
    }

    // Cleanup previous subscriptions if switching locations
    if (realtimeLocationRef.current && realtimeLocationRef.current !== locationId) {
      useFloorPlanStore.getState().cleanup();
      useOrderStore.getState().cleanupOrderRealtime();
    }

    realtimeLocationRef.current = locationId;

    // Setup realtime subscriptions for tables/sessions
    useFloorPlanStore.getState().setupRealtimeSubscriptions(locationId);

    // REMOVED: Duplicate order realtime subscription (now handled by LocationRealtimeProvider with useOrdersRealtime hook)
    // useOrderStore.getState().setupOrderRealtimeSubscriptions(locationId);

    console.log('[PosSyncProvider] Realtime subscriptions enabled for location:', locationId);

    // Cleanup function
    return () => {
      useFloorPlanStore.getState().cleanup();
      // REMOVED: Cleanup for duplicate order subscription
      // useOrderStore.getState().cleanupOrderRealtime();
      realtimeLocationRef.current = null;
    };
  }, [selectedStore?.id]);

  useEffect(() => {
    if (selectedStore?.id) {
      // Clear potentially stale floor plan data before fresh sync
      useFloorPlanStore.setState({
        tables: [],
        lastSyncAt: null,
      });

      syncEmployees(selectedStore.id);
      syncFloorPlans(selectedStore.id);
      syncTaxRates(selectedStore.id);
    }
  }, [selectedStore?.id, syncEmployees, syncFloorPlans, syncTaxRates]);

  // App state listener - reconnect realtime and refresh stale data when app becomes active
  useEffect(() => {
    const handleAppStateChange = (nextState: AppStateStatus) => {
      if (nextState === "active") {
        console.log("[PosSyncProvider] App became active - reconnecting realtime");
        const floorPlanStore = useFloorPlanStore.getState();

        // Reconnect realtime if disconnected or reconnecting
        if (floorPlanStore.realtimeStatus !== 'connected') {
          floorPlanStore.manualReconnect();
        }

        // Also refresh stale data
        floorPlanStore.loadFloorPlanStatusIfStale();
      }
    };

    const subscription = AppState.addEventListener("change", handleAppStateChange);

    return () => {
      subscription.remove();
    };
  }, []);

  return <>{children}</>;
}

