import { useCallback, useRef } from 'react';
import { Alert } from 'react-native';
import { useSupabaseClient } from '@/hooks/useSupabaseClient';
import { DejavooService } from '@/services/payments/dejavoo';
import { usePaymentTerminalStore } from '@/stores/usePaymentTerminalStore';
import { useOrderStore } from '@/stores/useOrderStore';

export function usePaymentTerminal() {
  const supabase = useSupabaseClient();
  const serviceRef = useRef<DejavooService | null>(null);

  const {
    terminals,
    activeTerminalId,
    isTestingConnection,
    setTerminals,
    setActiveTerminal,
    updateTerminalStatus,
    setConnectionTesting,
    setError,
    getActiveTerminal,
  } = usePaymentTerminalStore();

  // Get or create service instance
  const getService = useCallback(() => {
    if (!serviceRef.current) {
      serviceRef.current = new DejavooService(supabase);
    }
    return serviceRef.current;
  }, [supabase]);

  // Load terminals for the current station
  const loadTerminals = useCallback(async (locationId: string) => {
    try {
      const { data, error } = await supabase
        .from('payment_terminals')
        .select('*')
        .eq('location_id', locationId)
        .eq('is_active', true);

      if (error) throw error;

      const mappedTerminals = (data || []).map((t) => ({
        id: t.id,
        name: t.terminal_name,
        tpn: t.tpn,
        model: t.terminal_model,
        isActive: t.is_active,
        isConnected: t.is_connected,
        lastConnectionTest: t.last_connection_test_at,
        lastConnectionStatus: t.last_connection_status,
      }));

      setTerminals(mappedTerminals);

      // Auto-select first terminal if none selected
      if (!activeTerminalId && mappedTerminals.length > 0) {
        setActiveTerminal(mappedTerminals[0].id);
      }
    } catch (err) {
      console.error('[usePaymentTerminal] Failed to load terminals:', err);
      setError(err instanceof Error ? err.message : 'Failed to load terminals');
    }
  }, [supabase, activeTerminalId, setTerminals, setActiveTerminal, setError]);

  // Test connection to active terminal
  const testConnection = useCallback(async (terminalId?: string): Promise<boolean> => {
    const targetId = terminalId || activeTerminalId;
    if (!targetId) {
      setError('No terminal selected');
      return false;
    }

    setConnectionTesting(true);
    setError(null);

    try {
      const service = getService();
      const loaded = await service.loadCredentials(targetId);

      if (!loaded) {
        throw new Error('Failed to load terminal credentials');
      }

      const result = await service.checkTerminalStatus();

      // Update local state
      updateTerminalStatus(targetId, {
        isConnected: result.status === 'Online',
        lastConnectionStatus: result.status,
        lastConnectionTest: new Date().toISOString(),
      });

      // Update database
      await supabase.rpc('update_terminal_status', {
        p_terminal_id: targetId,
        p_status: result.status,
        p_is_connected: result.status === 'Online',
      });

      if (result.status !== 'Online') {
        setError(result.error || `Terminal is ${result.status}`);
      }

      return result.status === 'Online';
    } catch (err) {
      console.error('[usePaymentTerminal] Connection test failed:', err);
      setError(err instanceof Error ? err.message : 'Connection test failed');

      updateTerminalStatus(targetId, {
        isConnected: false,
        lastConnectionStatus: 'Offline',
        lastConnectionTest: new Date().toISOString(),
      });

      return false;
    } finally {
      setConnectionTesting(false);
    }
  }, [activeTerminalId, getService, updateTerminalStatus, setConnectionTesting, setError, supabase]);

  // Process a payment
  const processPayment = useCallback(async (params: {
    orderId: string;
    amount: number;
    tipAmount?: number;
    taxAmount?: number;
    paymentIndex?: number;
  }): Promise<{
    success: boolean;
    transactionId?: string;
    authCode?: string;
    cardType?: string;
    lastFour?: string;
    error?: string;
  }> => {
    if (!activeTerminalId) {
      return { success: false, error: 'No terminal selected' };
    }

    try {
      const service = getService();
      const loaded = await service.loadCredentials(activeTerminalId);

      if (!loaded) {
        return { success: false, error: 'Failed to load terminal credentials' };
      }

      const referenceId = DejavooService.generateReferenceId(
        params.orderId,
        params.paymentIndex
      );

      const result = await service.processSale({
        amount: params.amount,
        tipAmount: params.tipAmount,
        taxAmount: params.taxAmount,
        referenceId,
        invoiceNumber: params.orderId.substring(0, 20),
      });

      if (result.success && result.data) {
        return {
          success: true,
          transactionId: result.data.TransactionId,
          authCode: result.data.AuthCode,
          cardType: result.data.CardType,
          lastFour: result.data.CardNumber.slice(-4),
        };
      } else {
        return {
          success: false,
          error: result.error || 'Payment failed',
        };
      }
    } catch (err) {
      console.error('[usePaymentTerminal] Payment failed:', err);
      return {
        success: false,
        error: err instanceof Error ? err.message : 'Payment failed',
      };
    }
  }, [activeTerminalId, getService]);

  // Void a transaction
  const voidPayment = useCallback(async (referenceId: string): Promise<{
    success: boolean;
    error?: string;
  }> => {
    if (!activeTerminalId) {
      return { success: false, error: 'No terminal selected' };
    }

    try {
      const service = getService();
      await service.loadCredentials(activeTerminalId);

      const result = await service.voidTransaction({ referenceId });
      return {
        success: result.success,
        error: result.error,
      };
    } catch (err) {
      return {
        success: false,
        error: err instanceof Error ? err.message : 'Void failed',
      };
    }
  }, [activeTerminalId, getService]);

  // Process a refund
  const processRefund = useCallback(async (params: {
    amount: number;
    originalReferenceId?: string;
  }): Promise<{
    success: boolean;
    transactionId?: string;
    error?: string;
  }> => {
    if (!activeTerminalId) {
      return { success: false, error: 'No terminal selected' };
    }

    try {
      const service = getService();
      await service.loadCredentials(activeTerminalId);

      const referenceId = DejavooService.generateReferenceId(
        `refund_${Date.now()}`,
        0
      );

      const result = await service.processRefund({
        amount: params.amount,
        referenceId,
        originalReferenceId: params.originalReferenceId,
      });

      return {
        success: result.success,
        transactionId: result.data?.TransactionId,
        error: result.error,
      };
    } catch (err) {
      return {
        success: false,
        error: err instanceof Error ? err.message : 'Refund failed',
      };
    }
  }, [activeTerminalId, getService]);

  // Register a new terminal
  const registerTerminal = useCallback(async (params: {
    locationId: string;
    merchantId: string;
    stationId?: string;
    terminalName: string;
    tpn: string;
    authKey: string;
    terminalModel?: string;
    environment?: 'sandbox' | 'production';
  }): Promise<{
    success: boolean;
    terminalId?: string;
    error?: string;
  }> => {
    try {
      const { data, error } = await supabase.rpc('register_payment_terminal', {
        p_merchant_id: params.merchantId,
        p_location_id: params.locationId,
        p_station_id: params.stationId,
        p_terminal_name: params.terminalName,
        p_tpn: params.tpn,
        p_auth_key: params.authKey,
        p_terminal_model: params.terminalModel,
        p_api_environment: params.environment || 'sandbox',
      });

      if (error) throw error;

      if (data?.success) {
        // Reload terminals
        await loadTerminals(params.locationId);

        return {
          success: true,
          terminalId: data.terminal_id,
        };
      } else {
        return {
          success: false,
          error: data?.error || 'Registration failed',
        };
      }
    } catch (err) {
      console.error('[usePaymentTerminal] Registration failed:', err);
      return {
        success: false,
        error: err instanceof Error ? err.message : 'Registration failed',
      };
    }
  }, [supabase, loadTerminals]);

  return {
    // State
    terminals,
    activeTerminalId,
    activeTerminal: getActiveTerminal(),
    isTestingConnection,

    // Actions
    loadTerminals,
    setActiveTerminal,
    testConnection,
    processPayment,
    voidPayment,
    processRefund,
    registerTerminal,
  };
}

import { useSupabaseClient } from "@/hooks/useSupabaseClient";
import { toastService } from "@/lib/toastService";
import { useEmployeeStore } from "@/stores/useEmployeeStore";
import { useTimeClockStore } from "@/stores/useTimeClock";
import { TimeClockAction, TimeClockActionType } from "@/types/time-clock";
import NetInfo from "@react-native-community/netinfo";
import { useCallback, useEffect } from "react";
import { v4 as uuidv4 } from "uuid";

export interface UseTimeClockOptions {
  onSuccess?: (type: TimeClockActionType, employeeName?: string) => void;
  onError?: (type: TimeClockActionType, error: string) => void;
}

export const useTimeClock = (options?: UseTimeClockOptions) => {
  const store = useTimeClockStore();
  const supabase = useSupabaseClient();

  // 1. The Core Action Handler
  const performAction = useCallback(
    async (
      type: TimeClockActionType,
      pinCode: string,
      locationId: string,
      deviceId: string
    ) => {
      console.log("[useTimeClock] performAction called:", {
        type,
        locationId,
        deviceId,
      });
      const previousStatus = store.status;

      // A. Create the payload
      const actionPayload: TimeClockAction = {
        id: uuidv4(),
        type,
        pinCode,
        locationId,
        timestamp: new Date().toISOString(),
        deviceId,
      };

      // B. Optimistic Update (Immediate Feedback)
      let nextStatus = store.status;
      switch (type) {
        case "sign_in":
          nextStatus = "active";
          break;
        case "clock_in":
          nextStatus = "active";
          break;
        case "clock_out":
          nextStatus = "idle";
          break;
        case "break_start":
          nextStatus = "on_break";
          break;
        case "break_end":
          nextStatus = "active";
          break;
      }
      store.setStatus(nextStatus);
      console.log("[useTimeClock] Optimistic update, status:", nextStatus);

      // C. Network Check & Execution
      const netState = await NetInfo.fetch();
      console.log("[useTimeClock] Network:", {
        connected: netState.isConnected,
        reachable: netState.isInternetReachable,
      });

      if (netState.isConnected && netState.isInternetReachable) {
        try {
          // --- ONLINE PATH ---
          console.log("[useTimeClock] Calling RPC...", {
            type,
            locationId,
            deviceId,
            pinLength: pinCode?.length,
            pinFirstChar: pinCode?.charAt(0), // Debug without exposing full PIN
          });
          const { data, error } = await supabase.rpc("handle_time_clock", {
            p_pin_code: pinCode,
            p_location_id: locationId,
            p_action_type: type,
            p_device_id: deviceId,
          });
          console.log("[useTimeClock] RPC response:", { data, error });

          if (error) throw error;

          // Update real ID from server response if clocking in
          if (type === "clock_in" || (type === "sign_in" && data?.shift_id)) {
            store.setStatus(nextStatus, data.shift_id);
          }

          // Store employee info from backend response
          if (data?.staff_id) {
            store.setEmployee(data.staff_id, data?.employee_name || null);
          }

          // Track break start time
          if (type === "break_start") {
            store.setBreakStartTime(new Date().toISOString());
          } else if (type === "break_end") {
            store.setBreakStartTime(null);
          } else if (type === "clock_out") {
            // Clear all state on clock out
            store.clearState();
          }

          // Update employee store to keep local state in sync
          if (data?.staff_id) {
            const employeeStore = useEmployeeStore.getState();
            if (type === "clock_in") {
              employeeStore.clockIn(data.staff_id);
            } else if (type === "clock_out") {
              employeeStore.clockOut(data.staff_id);
            }
          }

          // Show success toast and call success callback
          const employeeName = data?.employee_name;
          const successMessages: Record<
            TimeClockActionType,
            { title: string; message: string }
          > = {
            sign_in: {
              title: "Sign In Successful",
              message: employeeName
                ? `Welcome, ${employeeName}!`
                : "You have been signed in successfully.",
            },
            clock_in: {
              title: "Clock In Successful",
              message: employeeName
                ? `Welcome, ${employeeName}!`
                : "You have been clocked in successfully.",
            },
            clock_out: {
              title: "Clock Out Successful",
              message: employeeName
                ? `Goodbye, ${employeeName}!`
                : "You have been clocked out successfully.",
            },
            break_start: {
              title: "Break Started",
              message: "Your break has started. Enjoy your rest!",
            },
            break_end: {
              title: "Break Ended",
              message: "Welcome back! Your break has ended.",
            },
          };

          toastService.show({
            ...successMessages[type],
            type: "success",
          });

          options?.onSuccess?.(type, employeeName);

          // Return data for actions that need it
          return { success: true, ...data };
        } catch (error: any) {
          // Revert optimistic update on hard failure
          store.setStatus(previousStatus);

          const errorMessage = error.message || "Failed to update time clock";
          const isNetworkError =
            errorMessage?.includes("network") ||
            errorMessage?.includes("fetch") ||
            errorMessage?.includes("timeout") ||
            !error.code; // Supabase errors usually have codes

          if (isNetworkError) {
            // Network error: queue for later sync
            store.queueAction(actionPayload);
            toastService.show({
              title: "Offline Mode",
              message:
                "Your action will be synced when connection is restored.",
              type: "warning",
            });
            // Return queued status so caller knows it was accepted
            return { success: true, queued: true };
          } else {
            // Logic error (e.g., Wrong PIN, Already clocked in): show error
            // Check for specific backend error codes first
            let errorTitle = "Clock Error";
            let errorToastMessage = "";

            if (errorMessage.includes("ALREADY_CLOCKED_IN")) {
              errorTitle = "Already Clocked In";
              errorToastMessage = "You are already clocked in.";
            } else if (errorMessage.includes("NOT_CLOCKED_IN")) {
              errorTitle = "Not Clocked In";
              errorToastMessage = "You are not clocked in.";
            } else if (errorMessage.includes("ALREADY_ON_BREAK")) {
              errorTitle = "Already On Break";
              errorToastMessage = "You are already on break.";
            } else if (errorMessage.includes("NOT_ON_BREAK")) {
              errorTitle = "Not On Break";
              errorToastMessage = "You are not currently on break.";
            } else if (
              errorMessage.includes("PIN") ||
              errorMessage.includes("pin")
            ) {
              errorTitle = "Invalid PIN";
              errorToastMessage = "The PIN you entered is incorrect.";
            } else {
              // Fallback to generic messages
              const errorMessages: Record<TimeClockActionType, string> = {
                sign_in:
                  "Failed to sign in. Please check your PIN and try again.",
                clock_in:
                  "Failed to clock in. Please check your PIN and try again.",
                clock_out: "Failed to clock out. Please try again.",
                break_start: "Failed to start break. Please try again.",
                break_end: "Failed to end break. Please try again.",
              };
              errorToastMessage = errorMessages[type];
            }

            toastService.show({
              title: errorTitle,
              message: errorToastMessage,
              type: "error",
            });

            options?.onError?.(type, errorMessage);
            // Throw so caller can handle the error
            throw new Error(errorMessage);
          }
        }
      } else {
        // --- OFFLINE PATH ---
        console.log("Offline: Queueing time clock action");
        store.queueAction(actionPayload);
        toastService.show({
          title: "Offline Mode",
          message: "Your action will be synced when connection is restored.",
          type: "warning",
        });
        // Return queued status so caller knows it was accepted
        return { success: true, queued: true };
      }
    },
    [store, supabase, options]
  );

  // 2. Sync Processor (The "Queue Flusher")
  // Automatically runs when internet comes back or queue changes
  useEffect(() => {
    const processQueue = async () => {
      if (store.offlineQueue.length === 0 || store.isSyncing) return;

      const netState = await NetInfo.fetch();
      if (!netState.isConnected || !netState.isInternetReachable) return;

      store.setSyncing(true);

      // Process strictly in order (FIFO)
      // We process one at a time to ensure backend state consistency
      const actionToProcess = store.offlineQueue[0];

      try {
        console.log(`Syncing action: ${actionToProcess.type}`);

        const { error } = await supabase.rpc("handle_time_clock", {
          p_pin_code: actionToProcess.pinCode,
          p_location_id: actionToProcess.locationId,
          p_action_type: actionToProcess.type,
          p_device_id: actionToProcess.deviceId,
        });

        if (error) {
          console.error("Sync failed for action", actionToProcess.id, error);
          // If it's a "Wrong PIN" error stored offline, we discard it
          // Otherwise, keep it in queue for retry
          const isLogicError =
            error.code && !error.message?.includes("network");
          if (isLogicError) {
            // Logic error (wrong PIN, etc.) - remove from queue
            store.removeFromQueue(actionToProcess.id);
            toastService.show({
              title: "Sync Warning",
              message:
                "An offline action could not be processed. It has been removed.",
              type: "warning",
            });
          }
          // Network errors will be retried on next interval
        } else {
          // Success: Remove from queue
          store.removeFromQueue(actionToProcess.id);
          if (store.offlineQueue.length === 1) {
            // Last item in queue was just processed
            toastService.show({
              title: "Sync Complete",
              message: "All pending actions have been synced.",
              type: "success",
            });
          }
        }
      } catch (e) {
        console.error("Critical Sync Error", e);
      } finally {
        store.setSyncing(false);
      }
    };

    // Run processor on mount and whenever queue changes
    processQueue();

    // Set up a poller interval for aggressive syncing
    const interval = setInterval(processQueue, 10000);
    return () => clearInterval(interval);
  }, [store.offlineQueue, store.isSyncing, supabase]);

  return {
    status: store.status,
    shiftId: store.shiftId,
