export const ALL_MODIFIER_GROUPS: ModifierCategory[] = [
  // Burger Modifiers
  ...burgerModifiers,

  // Pizza Modifiers
  ...pizzaModifiers,

  // Salad Modifiers
  ...saladModifiers,

  // Sandwich Modifiers
  ...sandwichModifiers,

  // Pasta Modifiers
  ...pastaModifiers,

  // Soup Modifiers
  ...soupModifiers,

  // Coffee Modifiers
  ...coffeeModifiers,

  // Steak Modifiers
  ...steakModifiers,

  // Seafood Modifiers
  ...seafoodModifiers,

  // Taco Modifiers
  ...tacoModifiers,

  // Ramen Modifiers
  ...ramenModifiers,

  // Sushi Modifiers
  ...sushiModifiers,

  // Ice Cream Modifiers
  ...iceCreamModifiers,
].map((group) => {
  if (group?.type === "required" && Array.isArray(group.options)) {
    const hasDefault = group.options.some((o: any) => o?.isDefault);
    // Ensure exactly one default when none is present:
    if (!hasDefault && group.options.length > 0) {
      return {
        ...group,
        options: group.options.map((opt: any, idx: number) => ({
          ...opt,
          isDefault: idx === 0,
        })),
      } as ModifierCategory;
    }
  }
  return group;
});

