/**
 * Offline Sync Initialization
 *
 * Bridges the offlineSyncService with useOrderStore.
 * Call initializeOfflineSync() once at app startup (e.g., in _layout.tsx).
 *
 * Enhanced with:
 * - ID resolution from local to backend IDs
 * - Payment special handling with notifications
 * - Dependency-aware operation execution
 */

import {
  initIdRegistry,
  isLocalId,
  isValidUUID,
  mapLocalToBackend,
  resolveToBackendId,
} from "@/lib/offlineIdRegistry";
import {
  getFailedPayments,
  getIsOnline,
  getPendingPaymentsCount,
  hasPendingOrderCreation,
  initOfflineSyncService,
  OfflineOperation,
  OPERATION_PRIORITY,
  queueDependentOperation,
  queueOperation,
} from "@/services/offlineSyncService";
import { OrderDiscountService } from "@/services/orderDiscountService";
import { AddOpenItemParams, OrderService } from "@/services/orderService";
import { useCoursingStore } from "@/stores/useCoursingStore";
import { useEmployeeStore } from "@/stores/useEmployeeStore";
import { calculatePaidStatusFromPayments, useOrderStore } from "@/stores/useOrderStore";
import { useStoreSettingsStore } from "@/stores/useStoreSettingsStore";
import type { AddOrderItemParams } from "@/types/db-order-management-types";

let _supabaseClient: any = null;

// Callback for failed payment notifications
let _onPaymentFailed: ((payment: OfflineOperation) => void) | null = null;

/**
 * Set the Supabase client for backend operations.
 * Call this after Supabase is initialized.
 */
export function setOfflineSyncSupabaseClient(client: any): void {
  _supabaseClient = client;
}

/**
 * Set a callback for when payment operations fail.
 */
export function setOnPaymentFailed(
  callback: (payment: OfflineOperation) => void
): void {
  _onPaymentFailed = callback;
}

/**
 * Get the count of pending payment operations.
 */
export function getPendingPayments(): number {
  return getPendingPaymentsCount();
}

/**
 * Get all failed payment operations.
 */
export function getFailedPaymentOperations(): OfflineOperation[] {
  return getFailedPayments();
}

/**
 * Initialize the offline sync system.
 * Call this once at app startup.
 */
export async function initializeOfflineSync(): Promise<void> {
  const store = useOrderStore.getState();

  // Initialize the ID registry first
  await initIdRegistry();

  await initOfflineSyncService({
    onStatusChange: async (isOnline) => {
      store.setOnlineStatus(isOnline);

      // When we come back online, reconcile orders with failed syncs
      if (isOnline) {
        console.log(
          "[OfflineSync] Network restored, checking for orders with failed syncs..."
        );

        // Get fresh state after status update
        const currentStore = useOrderStore.getState();
        const failedOrders = currentStore.getOrdersWithFailedSyncs();

        if (failedOrders.length > 0) {
          console.log(
            `[OfflineSync] Found ${failedOrders.length} orders with failed syncs, retrying...`
          );

          for (const order of failedOrders) {
            try {
              await currentStore.retryFailedSyncs(order.localId);
              console.log(
                `[OfflineSync] Retried syncs for order ${order.localId}`
              );
            } catch (err) {
              console.error(
                `[OfflineSync] Failed to retry syncs for order ${order.localId}:`,
                err
              );
            }
          }
        } else {
          console.log("[OfflineSync] No orders with failed syncs found");
        }
      }
    },
    onQueueChange: (count) => {
      store.setPendingSyncCount(count);
    },
    onOperationFailed: (op) => {
      console.log("[OfflineSync] Operation failed permanently:", op.type, op.id);

      // Special handling for failed payments
      if (
        op.type === "process_cash_payment" ||
        op.type === "process_card_payment"
      ) {
        console.error("[OfflineSync] Payment failed:", op, _supabaseClient);
        _onPaymentFailed?.(op);
      }
    },
    executeOperation: async (op: OfflineOperation): Promise<boolean> => {
      return executeQueuedOperation(op);
    },
  });
}

/**
 * Resolve a local order ID to backend UUID.
 * 
 * Strategy:
 * 1. If it's already a valid UUID, return it (it's a backend ID)
 * 2. If it's a local ID (order_xxx, local_order_xxx), resolve it
 * 3. Check the ID registry first (for mapped IDs)
 * 4. Fall back to store lookup (order.db_order_id)
 * 
 * @returns Backend UUID string, or null if order hasn't been synced yet
 */
function resolveOrderId(localOrderId: string): string | null {
  // First check if it's already a valid UUID (backend ID)
  if (isValidUUID(localOrderId)) {
    return localOrderId;
  }

  // It's a local ID - need to resolve to backend ID
  // Try registry first (contains mappings from previous syncs)
  const fromRegistry = resolveToBackendId(localOrderId);
  if (fromRegistry) {
    console.log(`[resolveOrderId] Resolved ${localOrderId} from registry: ${fromRegistry}`);
    return fromRegistry;
  }

  // Fall back to store lookup (order might have db_order_id set)
  const store = useOrderStore.getState();
  const order = store.ordersById[localOrderId];
  if (order?.db_order_id) {
    console.log(`[resolveOrderId] Resolved ${localOrderId} from store: ${order.db_order_id}`);
    return order.db_order_id;
  }

  // Order hasn't been synced yet
  console.log(`[resolveOrderId] Cannot resolve ${localOrderId} - order not synced yet`);
  return null;
}

/**
 * Resolve a local item ID to backend UUID.
 * 
 * @returns Backend UUID string, or null if item hasn't been synced yet
 */
function resolveItemId(
  localOrderId: string,
  localItemId: string
): string | null {
  // First check if it's already a valid UUID (backend ID)
  if (isValidUUID(localItemId)) {
    return localItemId;
  }

  // Try registry first
  const fromRegistry = resolveToBackendId(localItemId);
  if (fromRegistry) return fromRegistry;

  // Fall back to store lookup
  const store = useOrderStore.getState();
  const order = store.ordersById[localOrderId];
  const item = order?.items.find((i) => i.id === localItemId);
  return item?.db_order_item_id || null;
}

/**
 * Execute a queued operation against the backend.
 * Returns true on success, false on failure.
 * Handles ID resolution from local to backend IDs.
 */
async function executeQueuedOperation(op: OfflineOperation): Promise<boolean> {
  console.log("[OfflineSync] Executing queued operation:", op.type);
  if (!_supabaseClient) {
    console.error("[OfflineSync] No Supabase client available");
    return false;
  }

  try {
    switch (op.type) {
      case "update_item_quantity": {
        const { orderItemId, quantity, localOrderId, localItemId } = op.params;

        // Resolve item ID if it was a local ID
        const resolvedItemId =
          localItemId && localOrderId
            ? resolveItemId(localOrderId, localItemId)
            : orderItemId;

        if (!resolvedItemId) {
          console.log(
            "[OfflineSync] update_item_quantity: Item not synced yet, will retry"
          );
          return false;
        }

        const { error } = await OrderService.updateOrderItemQuantity(
          _supabaseClient,
          resolvedItemId,
          quantity
        );
        return !error;
      }

      case "update_item": {
        const { orderItemId, specialInstructions, localOrderId, localItemId } =
          op.params;

        const resolvedItemId =
          localItemId && localOrderId
            ? resolveItemId(localOrderId, localItemId)
            : orderItemId;

        if (!resolvedItemId) {
          console.log(
            "[OfflineSync] update_item: Item not synced yet, will retry"
          );
          return false;
        }

        const { error } = await OrderService.updateOrderItem(_supabaseClient, {
          p_order_item_id: resolvedItemId,
          p_special_instructions: specialInstructions,
        });
        return !error;
      }

      case "replace_modifiers": {
        const { orderItemId, modifiers, localOrderId, localItemId } = op.params;

        const resolvedItemId =
          localItemId && localOrderId
            ? resolveItemId(localOrderId, localItemId)
            : orderItemId;

        if (!resolvedItemId) {
          console.log(
            "[OfflineSync] replace_modifiers: Item not synced yet, will retry"
          );
          return false;
        }

        const { error } = await OrderService.replaceOrderItemModifiers(
          _supabaseClient,
          resolvedItemId,
          modifiers
        );
        return !error;
      }

      case "apply_discount": {
        const { localOrderId, discount } = op.params;
        const store = useOrderStore.getState();
        const order = store.ordersById[localOrderId];
        const resolvedOrderId = order?.db_order_id || resolveOrderId(localOrderId);

        if (!resolvedOrderId) {
          console.log("[OfflineSync] apply_discount: Order not synced yet, will retry");
          return false;
        }

        // Get staff ID - use from discount if available, otherwise get from employee store
        const staffId = discount.applied_by_staff_profiles_id
          ?? useEmployeeStore.getState().loggedInEmployee?.profileId
          ?? null;

        if (!staffId) {
          console.warn("[OfflineSync] apply_discount: No staff ID available, will retry");
          return false;
        }

        const result = await OrderDiscountService.applyDiscount(_supabaseClient, {
          order_id: resolvedOrderId,
          staff_id: staffId,
          discount_id: discount.discount_id ?? null,
          discount_name: discount.discount_name ?? "Discount",
          discount_type: discount.discount_type,
          discount_value: discount.discount_value,
          source: discount.source ?? "preset",
          reason: null,
          applied_to_item_ids: discount.applied_to_item_ids ?? null,
          approved_by_staff_id: discount.approved_by_staff_profiles_id ?? null,
        });

        if (result.success && result.order_discount_id) {
          // Mark local discount as synced with backend order_discount_id
          useOrderStore.setState((state) => {
            const existingOrder = state.ordersById[localOrderId];
            if (!existingOrder?.applied_discounts) return state;
            return {
              ordersById: {
                ...state.ordersById,
                [localOrderId]: {
                  ...existingOrder,
                  applied_discounts: existingOrder.applied_discounts.map((d: any) =>
                    d.local_id === discount.local_id
                      ? { ...d, order_discount_id: result.order_discount_id, sync_status: "synced", sync_error: null }
                      : d
                  ),
                },
              },
            };
          });
          return true;
        } else if (result.requires_approval) {
          console.warn("[OfflineSync] apply_discount: Requires manager approval");
          // Don't retry - needs user intervention
          return true; // Mark as "handled" to prevent infinite retries
        } else {
          console.error("[OfflineSync] apply_discount: RPC failed:", result.error);
          return false;
        }
      }

      case "void_discount": {
        const { localOrderId, order_discount_id, void_reason } = op.params;
        const store = useOrderStore.getState();
        const order = store.ordersById[localOrderId];
        const resolvedOrderId = order?.db_order_id || resolveOrderId(localOrderId);

        if (!resolvedOrderId) {
          console.log("[OfflineSync] void_discount: Order not synced yet, will retry");
          return false;
        }

        if (!order_discount_id) {
          console.log("[OfflineSync] void_discount: No order_discount_id, skipping");
          return true; // Nothing to void
        }

        const staffId = useEmployeeStore.getState().loggedInEmployee?.profileId ?? null;

        if (!staffId) {
          console.warn("[OfflineSync] void_discount: No staff ID available, will retry");
          return false;
        }

        const result = await OrderDiscountService.voidDiscount(_supabaseClient, {
          order_id: resolvedOrderId,
          staff_id: staffId,
          order_discount_id: order_discount_id,
          void_reason: void_reason ?? null,
        });

        if (result.success) {
          console.log("[OfflineSync] void_discount: Successfully voided", order_discount_id);
          return true;
        } else {
          console.error("[OfflineSync] void_discount: RPC failed:", result.error);
          return false;
        }
      }

      case "void_item": {
        const { orderItemId, reason, localOrderId, localItemId } = op.params;

        const resolvedItemId =
          localItemId && localOrderId
            ? resolveItemId(localOrderId, localItemId)
            : orderItemId;

        if (!resolvedItemId) {
          console.log(
            "[OfflineSync] void_item: Item not synced yet, will retry"
          );
          return false;
        }

        const { error } = await OrderService.voidOrderItem(
          _supabaseClient,
          resolvedItemId,
          reason
        );
        return !error;
      }

      case "update_order_status": {
        const { orderId, status, reason, localOrderId } = op.params;

        const resolvedOrderId = localOrderId
          ? resolveOrderId(localOrderId)
          : orderId;

        if (!resolvedOrderId) {
          console.log(
            "[OfflineSync] update_order_status: Order not synced yet, will retry"
          );
          return false;
        }

        const { error } = await OrderService.updateOrderStatus(
          _supabaseClient,
          resolvedOrderId,
          status,
          reason
        );
        return !error;
      }

      // ================================================================
      // UNIFIED PAYMENT HANDLER - Uses process_payment_v2
      // Handles: Full card, Full cash, Split, Per-item payments
      // ================================================================
      case "process_payment":
      case "process_cash_payment":   // Legacy support
      case "process_card_payment": { // Legacy support
        const {
          params: paymentParams,
          localOrderId,
          localPaymentId,
          paymentTimestamp,
          cardData,
          terminalResponse,
        } = op.params;

        // ============================================================
        // MIGRATE OLD PARAMETER NAMES FOR BACKWARDS COMPATIBILITY
        // ============================================================
        // Old queued payments may use p_item_ids instead of p_item_allocations
        if (paymentParams?.p_item_ids && !paymentParams?.p_item_allocations) {
          console.log(`[OfflineSync:payment] Migrating p_item_ids to p_item_allocations`);
          // Old format: p_item_ids was just an array of order_item_ids
          // New format: p_item_allocations is array of { order_item_id, quantity, amount? }
          paymentParams.p_item_allocations = paymentParams.p_item_ids.map((id: string) => ({
            order_item_id: id,
            quantity: 1, // Default to 1 for old format
          }));
          delete paymentParams.p_item_ids;
        }

        console.log(`[OfflineSync:payment] ====== PROCESSING PAYMENT ======`);
        console.log(`[OfflineSync:payment] Type: ${op.type}`);
        console.log(`[OfflineSync:payment] Local Order ID: ${localOrderId || 'N/A'}`);
        console.log(`[OfflineSync:payment] Order ID in params: ${paymentParams?.p_order_id || 'N/A'}`);
        console.log(`[OfflineSync:payment] Amount: ${paymentParams?.p_amount}, Method: ${paymentParams?.p_payment_method}`);

        // Resolve order ID if needed
        if (localOrderId && isLocalId(paymentParams.p_order_id)) {
          console.log(`[OfflineSync:payment] Order ID is local, resolving...`);
          const resolvedOrderId = resolveOrderId(localOrderId);
          if (!resolvedOrderId) {
            // ============================================================
            // CHECK FOR ORPHANED PAYMENTS
            // ============================================================
            // If there's no create_order pending AND order not in store,
            // this payment will never succeed - discard it
            const hasCreateOrderOp = hasPendingOrderCreation(localOrderId);
            const orderInStore = useOrderStore.getState().ordersById[localOrderId];

            if (!hasCreateOrderOp && !orderInStore) {
              console.log(`[OfflineSync:payment] ORPHANED - Order ${localOrderId} has no create_order and not in store`);
              console.log(`[OfflineSync:payment] Discarding orphaned payment operation`);
              // Return true to remove this operation from queue (it will never succeed)
              return true;
            }

            // Also check if order exists in store but has no db_order_id and no pending create_order
            if (orderInStore && !orderInStore.db_order_id && !hasCreateOrderOp) {
              console.log(`[OfflineSync:payment] ORPHANED - Order ${localOrderId} has no db_order_id and no create_order`);
              console.log(`[OfflineSync:payment] Discarding orphaned payment operation`);
              return true;
            }

            console.log(`[OfflineSync:payment] BLOCKED - Order ${localOrderId} not synced yet`);
            return false;
          }
          paymentParams.p_order_id = resolvedOrderId;
          console.log(`[OfflineSync:payment] Resolved to: ${resolvedOrderId}`);
        }

        // Resolve item allocations (support per-item/split-by-item payments queued with local IDs)
        if (paymentParams.p_item_allocations && Array.isArray(paymentParams.p_item_allocations)) {
          const resolvedAllocations: { order_item_id: string; quantity: number; amount?: number }[] = [];
          for (const alloc of paymentParams.p_item_allocations) {
            const rawId = alloc.order_item_id;
            // If already a UUID, keep it; otherwise resolve via registry/store
            if (isValidUUID(rawId)) {
              resolvedAllocations.push(alloc);
              continue;
            }

            if (localOrderId) {
              const resolved = resolveItemId(localOrderId, rawId);
              if (resolved) {
                resolvedAllocations.push({
                  ...alloc,
                  order_item_id: resolved,
                });
              } else {
                console.log(
                  `[OfflineSync:payment] Item ${rawId} not synced yet, will retry`
                );
                return false; // wait for item sync
              }
            } else {
              console.log(
                `[OfflineSync:payment] No localOrderId to resolve item ${rawId}, will retry`
              );
              return false;
            }
          }

          // Replace with resolved backend item IDs
          paymentParams.p_item_allocations = resolvedAllocations;
        }

        // Build terminal response for card payments if we have card data
        let finalTerminalResponse = terminalResponse;
        if (!finalTerminalResponse && cardData) {
          finalTerminalResponse = {
            card_last_four: cardData.lastFour,
            card_type: cardData.brand,
            transaction_id: cardData.transactionRef,
          };
        }

        // Merge terminal response into params if exists
        const finalParams = {
          ...paymentParams,
          ...(finalTerminalResponse && { p_terminal_response: finalTerminalResponse }),
        };

        console.log("[OfflineSync:payment] Calling process_payment_v5 with:", JSON.stringify({
          orderId: finalParams.p_order_id,
          method: finalParams.p_payment_method,
          amount: finalParams.p_amount,
          tip: finalParams.p_tip_amount || 0,
          hasTerminalResponse: !!finalParams.p_terminal_response,
        }));

        const { data, error } = await OrderService.processPayment(
          _supabaseClient,
          finalParams
        );

        if (error) {
          console.error(`[OfflineSync:payment] FAILED - Error:`, error);
          return false;
        }

        console.log(`[OfflineSync:payment] SUCCESS!`);
        console.log(`[OfflineSync:payment] Response:`, JSON.stringify(data, null, 2));

        // Sync order state from backend response if available
        if (localOrderId && data) {
          const store = useOrderStore.getState();
          const order = store.ordersById[localOrderId];
          const responseData = data as any;

          // Update local order with backend payment response data
          if (responseData.order_amount_due !== undefined || responseData.order_amount_paid !== undefined) {
            store.updateOrderFromSync(localOrderId, {
              total_amount: responseData.order_card_total || responseData.order_total,
              total_tax: responseData.order_card_tax || responseData.order_tax,
            });
          }

          // ================================================================
          // Update order status to "preparing" if it was in draft/pending
          // This ensures payments from offline queue trigger proper workflow
          // ================================================================
          if (order && (order.order_status === "draft" || order.order_status === "pending")) {
            console.log(`[OfflineSync:payment] Updating order status: ${order.order_status} -> preparing`);

            // Update order status and item statuses
            const updatedItems = order.items.map(item => ({
              ...item,
              kitchen_status: "sent" as const,
              item_status: "Preparing" as const,
            }));

            useOrderStore.setState(state => {
              const currentOrder = state.ordersById[localOrderId];
              if (!currentOrder) return state;

              return {
                ordersById: {
                  ...state.ordersById,
                  [localOrderId]: {
                    ...currentOrder,
                    order_status: "preparing",
                    items: updatedItems,
                    // Set opened_at if not already set
                    opened_at: currentOrder.opened_at || new Date().toISOString(),
                  },
                },
              };
            });

            console.log(`[OfflineSync:payment] Order status updated to "preparing", ${updatedItems.length} items marked as sent`);
          }

          // Mark the specific payment as synced with backend payment_id and items covered
          // Uses localPaymentId or paymentTimestamp to find the correct payment (fixes split payment collapse)
          if (order && responseData.payment_id) {
            useOrderStore.setState((state) => {
              const currentOrder = state.ordersById[localOrderId];
              if (!currentOrder?.payments || currentOrder.payments.length === 0) {
                return state;
              }

              const payments = [...currentOrder.payments];

              // Find payment by localPaymentId or timestamp instead of using array index
              const paymentIndex = payments.findIndex(
                (p: any) =>
                  (localPaymentId && p.localId === localPaymentId) ||
                  (paymentTimestamp && p.timestamp === paymentTimestamp)
              );

              // Fallback to last payment only if no match found (legacy operations)
              const targetIdx = paymentIndex !== -1 ? paymentIndex : payments.length - 1;

              console.log(`[OfflineSync:payment] Updating payment at index ${targetIdx} (found by ${paymentIndex !== -1 ? 'ID match' : 'fallback'})`);

              payments[targetIdx] = {
                ...payments[targetIdx],
                id: responseData.payment_id,
                itemsCovered: responseData.items_covered || payments[targetIdx].itemsCovered || [],
                timestamp: payments[targetIdx].timestamp || new Date().toISOString(),
                sync_status: "synced" as const,
                sync_error: undefined,
              };

              // Calculate paid_status from LOCAL payments, not backend
              // This prevents flicker caused by stale/racing backend values
              const localPaidStatus = calculatePaidStatusFromPayments(
                payments,
                currentOrder.total_amount || 0
              );
              const isPaid = localPaidStatus === "Paid";

              return {
                ordersById: {
                  ...state.ordersById,
                  [localOrderId]: {
                    ...currentOrder,
                    payments,
                    amount_paid: responseData.order_amount_paid ?? currentOrder.amount_paid,
                    amount_due: responseData.order_amount_due ?? currentOrder.amount_due,
                    cash_amount_due: responseData.order_cash_amount_due ?? currentOrder.cash_amount_due,
                    paid_status: localPaidStatus,
                    check_status: currentOrder.check_status ?? "Opened",
                  },
                },
              };
            });
          }

          // Also update payment amounts from backend
          if (responseData.order_amount_paid !== undefined || responseData.order_amount_due !== undefined) {
            useOrderStore.setState(state => {
              const currentOrder = state.ordersById[localOrderId];
              if (!currentOrder) return state;

              // Mark the specific payment as synced (find by localPaymentId or timestamp)
              const payments = [...(currentOrder.payments || [])];
              if (payments.length > 0) {
                // Find payment by localPaymentId or timestamp instead of using array index
                const paymentIndex = payments.findIndex(
                  (p: any) =>
                    (localPaymentId && p.localId === localPaymentId) ||
                    (paymentTimestamp && p.timestamp === paymentTimestamp)
                );

                // Fallback to last payment only if no match found (legacy operations)
                const targetIdx = paymentIndex !== -1 ? paymentIndex : payments.length - 1;

                payments[targetIdx] = {
                  ...payments[targetIdx],
                  sync_status: "synced" as const,
                  sync_error: undefined,
                };
              }

              // Calculate paid_status from LOCAL payments, not backend
              const localPaidStatus = calculatePaidStatusFromPayments(
                payments,
                currentOrder.total_amount || 0
              );
              const isPaid = localPaidStatus === "Paid";

              return {
                ordersById: {
                  ...state.ordersById,
                  [localOrderId]: {
                    ...currentOrder,
                    payments,
                    amount_paid: responseData.order_amount_paid ?? currentOrder.amount_paid,
                    amount_due: responseData.order_amount_due ?? currentOrder.amount_due,
                    paid_status: localPaidStatus,
                    check_status: currentOrder.check_status ?? "Opened",
                  },
                },
              };
            });
          }

          // Trigger payment status sync from backend for fresh data
          // This ensures UI shows confirmed status after offline payment syncs
          console.log(`[OfflineSync:payment] Triggering payment status sync for order ${localOrderId}`);
          setTimeout(() => {
            useOrderStore.getState().syncPaymentStatus(localOrderId);
          }, 300);
        }

        return true;
      }

      // === OFFLINE-FIRST OPERATION HANDLERS ===

      case "create_order": {
        const { localOrderId, createOrderParams } = op.params;
        const store = useOrderStore.getState();
        const selectedStore = useStoreSettingsStore.getState().selectedStore;

        console.log(`[OfflineSync:create_order] ====== CREATING ORDER ======`);
        console.log(`[OfflineSync:create_order] Local ID: ${localOrderId}`);
        console.log(`[OfflineSync:create_order] Params:`, JSON.stringify(createOrderParams, null, 2));

        if (!selectedStore) {
          console.error("[OfflineSync:create_order] FAILED - No store selected");
          return false;
        }

        const { data, error } = await OrderService.createOrder(
          _supabaseClient,
          createOrderParams
        );

        if (error) {
          console.error("[OfflineSync:create_order] FAILED - DB Error:", error);
          return false;
        }

        if (data) {
          const orderData = Array.isArray(data) ? data[0] : data;
          const backendId = orderData.order_id || orderData.id;

          if (backendId) {
            // Update local order with backend ID
            store.updateOrderDbId(localOrderId, backendId);

            // Register in ID registry for future lookups
            await mapLocalToBackend(localOrderId, backendId);

            // Update local order with backend-generated data (order_number, display_number, etc.)
            store.updateOrderFromSync(localOrderId, {
              order_number: orderData.order_number,
              display_number: orderData.display_number || `#${orderData.order_number}`,
              opened_at: orderData.created_at,
              // Sync totals if available
              total_amount: orderData.card_total || orderData.total_amount,
              total_tax: orderData.card_tax_amount || orderData.tax_amount,
              subtotal: orderData.card_subtotal || orderData.subtotal,
              cash_total: orderData.cash_total,
              cash_tax_amount: orderData.cash_tax_amount,
              cash_subtotal: orderData.cash_subtotal,
            });

            console.log(`[OfflineSync:create_order] SUCCESS!`);
            console.log(`[OfflineSync:create_order] ${localOrderId} → ${backendId}`);
            console.log(`[OfflineSync:create_order] Order number: ${orderData.order_number || orderData.display_number}`);
          } else {
            console.error("[OfflineSync:create_order] FAILED - No backend ID in response:", orderData);
            return false;
          }
        }

        return true;
      }

      case "add_item": {
        const {
          localOrderId,
          localItemId,
          dbOrderId,
          addItemParams,
          itemData,
        } = op.params;
        const store = useOrderStore.getState();

        console.log(`[OfflineSync:add_item] ====== ADDING ITEM ======`);
        console.log(`[OfflineSync:add_item] Local Order ID: ${localOrderId}`);
        console.log(`[OfflineSync:add_item] Local Item ID: ${localItemId}`);
        console.log(`[OfflineSync:add_item] Item: ${itemData?.name || addItemParams?.p_item_name || 'unknown'}`);

        // Check if order exists and get its db_order_id
        const order = store.ordersById[localOrderId];
        if (!order) {
          console.error(`[OfflineSync:add_item] FAILED - Order ${localOrderId} not found in store`);
          console.log(`[OfflineSync:add_item] Available orders:`, Object.keys(store.ordersById));
          return false;
        }

        console.log(`[OfflineSync:add_item] Order in store: db_order_id=${order.db_order_id || 'NONE'}`);

        // Resolve the order ID - check registry, then store
        let actualDbOrderId = dbOrderId || order.db_order_id;
        if (!actualDbOrderId) {
          actualDbOrderId = resolveOrderId(localOrderId);
          console.log(`[OfflineSync:add_item] Resolved from registry: ${actualDbOrderId || 'NOT_FOUND'}`);
        }

        if (!actualDbOrderId) {
          console.log(`[OfflineSync:add_item] BLOCKED - Waiting for order sync`);
          console.log(`[OfflineSync:add_item] Order ${localOrderId} has no db_order_id yet`);
          return false; // Will be retried after order sync
        }

        console.log(`[OfflineSync:add_item] Using db_order_id: ${actualDbOrderId}`);

        const isOpenItem = itemData?.is_open_item || addItemParams?.is_open_item;

        // Build params for open item vs regular item
        let params: AddOrderItemParams | AddOpenItemParams;
        if (isOpenItem) {
          params = {
            p_order_id: actualDbOrderId,
            p_item_name: itemData?.open_item_name || itemData?.name || addItemParams?.p_item_name,
            p_unit_price: itemData?.open_item_price ?? itemData?.unitPrice ?? addItemParams?.p_unit_price ?? 0,
            p_quantity: itemData?.quantity ?? addItemParams?.p_quantity ?? 1,
            p_special_instructions: itemData?.customizations?.notes ?? addItemParams?.p_special_instructions,
            p_is_tax_exempt: itemData?.is_tax_exempt ?? addItemParams?.p_is_tax_exempt ?? false,
          } as AddOpenItemParams;
        } else {
          // Build the item params if we only have itemData (queued from initial failure)
          if (addItemParams) {
            params = addItemParams;
            // Update the order ID in case it changed
            (params as AddOrderItemParams).p_order_id = actualDbOrderId;
          } else if (itemData) {
            // Build modifiers array, but set to undefined if empty
            const modifiersArray = itemData.customizations?.modifiers?.flatMap(
              (mod: any) =>
                mod.options.map((opt: any) => ({
                  modifier_group_id: mod.categoryId,
                  modifier_item_id: opt.id,
                  modifier_group_name: mod.categoryName,
                  modifier_name: opt.name,
                  price_modifier: opt.price,
                  quantity: 1,
                }))
            );

            params = {
              p_order_id: actualDbOrderId,
              p_menu_item_id: itemData.menuItemId || undefined,
              p_location_exclusive_item_id: itemData.locationExclusiveItemId || undefined,
              p_quantity: itemData.quantity,
              p_item_name: itemData.name,
              p_category_name: itemData.category_name || "Uncategorized",
              // Use card price for p_unit_price and cash price for p_cash_unit_price
              // Fall back to originalPrice if specific prices not available
              p_unit_price: itemData.price ?? itemData.originalPrice ?? 0,
              p_cash_unit_price: itemData.cashPrice ?? itemData.price ?? itemData.originalPrice,
              p_selected_size_id: itemData.customizations?.size?.id || undefined,
              p_selected_size_name:
                itemData.customizations?.size?.name || undefined,
              p_size_price_modifier:
                itemData.customizations?.size?.priceModifier || undefined,
              p_special_instructions:
                itemData.customizations?.notes || undefined,
              // Set to undefined if empty array to avoid function signature mismatch
              p_modifiers: modifiersArray && modifiersArray.length > 0 ? modifiersArray : undefined,
              p_course_number:
                useCoursingStore.getState().getWorkingCourse(localOrderId) || 1,
            } as AddOrderItemParams;
          } else {
            console.error("[OfflineSync] No item params available for add_item");
            return false;
          }
        }

        let data: any;
        let error: any;
        if (isOpenItem) {
          ({ data, error } = await OrderService.addOpenItem(
            _supabaseClient,
            params as AddOpenItemParams
          ));
        } else {
          ({ data, error } = await OrderService.addOrderItem(
            _supabaseClient,
            params as AddOrderItemParams
          ));
        }

        if (error) {
          console.error(`[OfflineSync:add_item] FAILED - DB Error:`, error);
          console.error(`[OfflineSync:add_item] Order: ${localOrderId}, Item: ${localItemId}`);
          return false;
        }

        if (data?.order_item_id && localItemId) {
          // Update local item with backend ID
          store.updateItemDbId(localOrderId, localItemId, data.order_item_id);

          // Register in ID registry
          await mapLocalToBackend(localItemId, data.order_item_id);

          console.log(`[OfflineSync:add_item] SUCCESS!`);
          console.log(`[OfflineSync:add_item] ${localItemId} → ${data.order_item_id}`);

          // Sync order totals from response if available
          const responseData = data as any;
          if (responseData.order_card_total || responseData.order_cash_total || responseData.order_total) {
            store.updateOrderFromSync(localOrderId, {
              total_amount: responseData.order_card_total || responseData.order_total,
              total_tax: responseData.order_card_tax || responseData.order_tax,
              subtotal: responseData.order_card_subtotal || responseData.order_subtotal,
              cash_total: responseData.order_cash_total,
              cash_tax_amount: responseData.order_cash_tax,
              cash_subtotal: responseData.order_cash_subtotal,
            });
            console.log(`[OfflineSync:add_item] Synced order totals: card=${responseData.order_card_total}, cash=${responseData.order_cash_total}`);
          }
        } else {
          console.log(`[OfflineSync:add_item] Completed but no order_item_id returned`);
          console.log(`[OfflineSync:add_item] Response:`, data);
        }

        return true;
      }

      case "seat_guests": {
        const { tableIds, guestCount, serverId, localSessionId } = op.params;
        // FloorPlanService would be called here - for now just log
        console.log("[OfflineSync] seat_guests operation:", {
          tableIds,
          guestCount,
          serverId,
          localSessionId,
        });
        // This will be implemented when FloorPlanService is available
        // For now, return true to clear from queue as local state is already updated
        return true;
      }

      case "update_session_status": {
        const { sessionId, status } = op.params;
        console.log("[OfflineSync] update_session_status operation:", {
          sessionId,
          status,
        });
        // This will be implemented when FloorPlanService is available
        return true;
      }

      // ================================================================
      // SEND TO KITCHEN - Updates order status + item statuses
      // ================================================================
      case "send_to_kitchen": {
        const { localOrderId, localItemIds } = op.params;

        console.log(`[OfflineSync:send_to_kitchen] ====== SENDING TO KITCHEN ======`);
        console.log(`[OfflineSync:send_to_kitchen] Local Order ID: ${localOrderId}`);
        console.log(`[OfflineSync:send_to_kitchen] Items to send: ${localItemIds?.length || 0}`);

        // Resolve order ID
        const resolvedOrderId = resolveOrderId(localOrderId);
        if (!resolvedOrderId) {
          console.log(`[OfflineSync:send_to_kitchen] BLOCKED - Order ${localOrderId} not synced yet`);
          return false;
        }

        console.log(`[OfflineSync:send_to_kitchen] Resolved order: ${resolvedOrderId}`);

        try {
          // 1. Update order status to "preparing"
          const { error: statusError } = await OrderService.updateOrderStatus(
            _supabaseClient,
            resolvedOrderId,
            "preparing"
          );

          if (statusError) {
            console.error("[OfflineSync:send_to_kitchen] Failed to update order status:", statusError);
            return false;
          }

          console.log(`[OfflineSync:send_to_kitchen] Order status updated to "preparing"`);

          // 2. Resolve and update item statuses
          if (localItemIds && localItemIds.length > 0) {
            const resolvedItemIds = localItemIds
              .map((localItemId: string) => resolveItemId(localOrderId, localItemId))
              .filter((id: string | null): id is string => !!id);

            if (resolvedItemIds.length > 0) {
              const { error: itemError } = await OrderService.bulkUpdateOrderItemStatus(
                _supabaseClient,
                resolvedItemIds,
                "sent"
              );

              if (itemError) {
                console.error("[OfflineSync:send_to_kitchen] Failed to update item statuses:", itemError);
                // Non-fatal - order status already updated
              } else {
                console.log(`[OfflineSync:send_to_kitchen] ${resolvedItemIds.length} items marked as "sent"`);
              }
            } else {
              console.log(`[OfflineSync:send_to_kitchen] No items could be resolved (may not be synced yet)`);
            }
          }

          console.log(`[OfflineSync:send_to_kitchen] SUCCESS!`);
          return true;
        } catch (err) {
          console.error("[OfflineSync:send_to_kitchen] Error:", err);
          return false;
        }
      }

      case "fire_course": {
        const { dbOrderId, courseNumber, localOrderId } = op.params;

        // Resolve order ID if needed
        let resolvedOrderId = dbOrderId;
        if (!resolvedOrderId && localOrderId) {
          resolvedOrderId = resolveOrderId(localOrderId);
        }

        if (!resolvedOrderId) {
          console.log(
            "[OfflineSync] fire_course: No dbOrderId, will retry later"
          );
          return false;
        }

        try {
          const { error } = await _supabaseClient.rpc("fire_course", {
            p_order_id: resolvedOrderId,
            p_course_number: courseNumber,
          });

          if (error) {
            console.error("[OfflineSync] Failed to fire course:", error);
            return false;
          }

          console.log(
            `[OfflineSync] Course ${courseNumber} fired for order ${resolvedOrderId}`
          );
          return true;
        } catch (err) {
          console.error("[OfflineSync] Error firing course:", err);
          return false;
        }
      }

      case "remove_item": {
        const { orderItemId, localOrderId, localItemId } = op.params;

        const resolvedItemId =
          localItemId && localOrderId
            ? resolveItemId(localOrderId, localItemId)
            : orderItemId;

        if (!resolvedItemId) {
          // If item was never synced, we can just discard the operation
          console.log(
            "[OfflineSync] remove_item: Item never synced, discarding"
          );
          return true;
        }

        const { error } = await OrderService.voidOrderItem(
          _supabaseClient,
          resolvedItemId,
          "Removed"
        );
        return !error;
      }

      default:
        console.warn("[OfflineSync] Unknown operation type:", op.type);
        return false;
    }
  } catch (error) {
    console.error("[OfflineSync] Error executing operation:", op.type, error);
    return false;
  }
}

/**
 * Helper to queue an operation when sync fails.
 * Use this in store actions when backend calls fail.
 */
export async function queueFailedOperation(
  type: OfflineOperation["type"],
  params: Record<string, any>,
  localOrderId: string,
  localItemId?: string,
  contextSnapshot?: Record<string, any>
): Promise<string> {
  return queueOperation({
    type,
    params,
    localOrderId,
    localItemId,
    contextSnapshot,
  });
}

/**
 * Queue an operation with a dependency on another operation.
 * The dependent operation will only execute after the dependency completes.
 */
export async function queueDependentFailedOperation(
  type: OfflineOperation["type"],
  params: Record<string, any>,
  localOrderId: string,
  dependsOnOperationId: string,
  localItemId?: string,
  contextSnapshot?: Record<string, any>
): Promise<string> {
  return queueDependentOperation(
    {
      type,
      params,
      localOrderId,
      localItemId,
      contextSnapshot,
    },
    dependsOnOperationId
  );
}

/**
 * Queue a payment operation with special handling.
 */
export async function queuePaymentOperation(
  type: "process_cash_payment" | "process_card_payment",
  paymentParams: Record<string, any>,
  localOrderId: string,
  cardData?: { lastFour?: string; brand?: string; transactionRef?: string }
): Promise<string> {
  return queueOperation({
    type,
    params: {
      params: paymentParams,
      localOrderId,
      cardData,
      transactionRef: cardData?.transactionRef,
    },
    localOrderId,
  });
}

/**
 * Check if we're currently online.
 */
export function isOnline(): boolean {
  return getIsOnline();
}

/**
 * Get the priority for an operation type.
 */
export function getOperationPriority(type: OfflineOperation["type"]): number {
  return OPERATION_PRIORITY[type] ?? 99;
}

/**
 * Offline Sync Service
 *
 * Manages operation queueing when offline and auto-sync when back online.
 * Uses MMKV for blazing-fast synchronous persistence and NetInfo for network monitoring.
 *
 * Enhanced with:
 * - Priority-based processing (orders before items before payments)
 * - Dependency tracking between operations
 * - Operation collapsing for same-entity updates
 * - Full context capture for reliable replay
 */

import { getSyncJSON, setSyncJSON } from "@/lib/storage";
import { isLocalOrder } from "@/utils/orderIdHelpers";
// @ts-ignore - NetInfo types not recognized but package is installed
import NetInfo from "@react-native-community/netinfo";
// @ts-ignore
import type { NetInfoState } from "@react-native-community/netinfo";

// ============================================================================
// TYPES
// ============================================================================

export type OperationType =
  | "create_order"
  | "add_item"
  | "update_item_quantity"
  | "update_item"
  | "replace_modifiers"
  | "remove_item"
  | "void_item"
  | "update_order_status"
  | "apply_discount"
  | "void_discount"         // Void/remove a discount via RPC
  // Kitchen operations
  | "send_to_kitchen"       // Updates order status + item statuses
  // Payment operations (unified + legacy)
  | "process_payment"       // Unified payment via process_payment_v2
  | "process_cash_payment"  // Legacy - routes to process_payment handler
  | "process_card_payment"  // Legacy - routes to process_payment handler
  // Floor plan operations
  | "seat_guests"
  | "update_session_status"
  // Coursing operations
  | "fire_course";

/**
 * Priority levels for operation processing.
 * Lower number = higher priority (processed first).
 */
export const OPERATION_PRIORITY: Record<OperationType, number> = {
  // Order creation must happen first
  create_order: 1,
  seat_guests: 1,
  update_session_status: 1,

  // Item operations after order exists
  add_item: 2,
  apply_discount: 2,
  void_discount: 2,         // Same priority as apply_discount
  update_item: 3,
  update_item_quantity: 3,
  replace_modifiers: 3,
  remove_item: 3,
  void_item: 3,

  // Coursing and kitchen after items
  fire_course: 4,
  update_order_status: 4,
  send_to_kitchen: 4,       // Kitchen send after items synced

  // Payments last (after everything else synced)
  process_payment: 5,       // Unified payment via process_payment_v2
  process_cash_payment: 5,  // Legacy support
  process_card_payment: 5,  // Legacy support
};

export interface OfflineOperation {
  id: string;
  type: OperationType;
  params: Record<string, any>;
  localOrderId: string;
  localItemId?: string;
  timestamp: string;
  retryCount: number;
  status: "pending" | "processing" | "failed" | "discarded" | "blocked";
  // Enhanced fields for dependency tracking
  priority: number;
  dependsOn?: string; // ID of operation this depends on (must complete first)
  entityKey?: string; // Unique key for collapsing (e.g., "item:localItemId")
  contextSnapshot?: Record<string, any>; // Full context at time of queueing
  // Phase 6: Operation bundling for atomic execution
  bundleId?: string;           // Groups related operations for atomic execution
  bundleSequence?: number;     // Order within bundle (0-indexed)
  rollbackOnBundleFailure?: boolean; // Whether to rollback if bundle fails
  expectedVersion?: number;    // For optimistic locking checks
}

export interface SyncResult {
  success: boolean;
  operationId: string;
  error?: string;
  backendId?: string; // Backend ID returned from successful operation
}

// ============================================================================
// CONSTANTS
// ============================================================================

const STORAGE_KEY = "offline_operations_queue";
const MAX_RETRY_ATTEMPTS = 5;
const DEBOUNCE_MS = 3000;

// ============================================================================
// AUTO-RETRY CONFIGURATION (Exponential Backoff)
// ============================================================================
const RETRY_CONFIG = {
  baseDelayMs: 2000,      // Initial retry delay: 2 seconds
  maxDelayMs: 60000,      // Maximum delay: 1 minute
  multiplier: 2,          // Double the delay each retry
  jitterMs: 1000,         // Random jitter up to 1 second
};

/**
 * Calculate exponential backoff delay with jitter
 * Formula: min(maxDelay, baseDelay * multiplier^retryCount) + random(0, jitter)
 */
function calculateBackoffDelay(retryCount: number): number {
  const delay = Math.min(
    RETRY_CONFIG.maxDelayMs,
    RETRY_CONFIG.baseDelayMs * Math.pow(RETRY_CONFIG.multiplier, retryCount)
  );
  const jitter = Math.random() * RETRY_CONFIG.jitterMs;
  return Math.round(delay + jitter);
}

// Track scheduled retry timers for cleanup
let autoRetryTimers: Map<string, ReturnType<typeof setTimeout>> = new Map();

// ============================================================================
// STATE
// ============================================================================

let isOnline = true;
let pendingOperations: OfflineOperation[] = [];
let syncInProgress = false;
let debounceTimer: ReturnType<typeof setTimeout> | null = null;
let unsubscribeNetInfo: (() => void) | null = null;

// Callbacks for store integration
let onStatusChange: ((isOnline: boolean) => void) | null = null;
let onQueueChange: ((count: number) => void) | null = null;
let onOperationFailed: ((op: OfflineOperation) => void) | null = null;
let executeOperation: ((op: OfflineOperation) => Promise<boolean>) | null =
  null;

// ============================================================================
// INITIALIZATION
// ============================================================================

/**
 * Initialize the offline sync service.
 * Call this once at app startup.
 */
export async function initOfflineSyncService(config: {
  onStatusChange: (isOnline: boolean) => void;
  onQueueChange: (count: number) => void;
  onOperationFailed?: (op: OfflineOperation) => void;
  executeOperation: (op: OfflineOperation) => Promise<boolean>;
}): Promise<void> {
  onStatusChange = config.onStatusChange;
  onQueueChange = config.onQueueChange;
  onOperationFailed = config.onOperationFailed ?? null;
  executeOperation = config.executeOperation;

  // Load persisted queue
  await loadQueueFromStorage();

  // Start network listener
  startNetworkListener();

  // Check initial state
  const state = await NetInfo.fetch();
  handleNetworkChange(state);

  console.log(
    "[OfflineSync] Initialized with",
    pendingOperations.length,
    "pending operations"
  );
}

/**
 * Cleanup when service is no longer needed.
 */
export function destroyOfflineSyncService(): void {
  if (unsubscribeNetInfo) {
    unsubscribeNetInfo();
    unsubscribeNetInfo = null;
  }
  if (debounceTimer) {
    clearTimeout(debounceTimer);
    debounceTimer = null;
  }
  // Clear all auto-retry timers
  for (const timer of autoRetryTimers.values()) {
    clearTimeout(timer);
  }
  autoRetryTimers.clear();
}

/**
 * Schedule an automatic retry for a specific operation with exponential backoff.
 */
function scheduleAutoRetry(operation: OfflineOperation): void {
  // Clear any existing timer for this operation
  const existingTimer = autoRetryTimers.get(operation.id);
  if (existingTimer) {
    clearTimeout(existingTimer);
  }

  const delay = calculateBackoffDelay(operation.retryCount);
  console.log(`[OfflineSync] Scheduling auto-retry for ${operation.type} (${operation.id}) in ${delay}ms (attempt ${operation.retryCount + 1}/${MAX_RETRY_ATTEMPTS})`);

  const timer = setTimeout(async () => {
    autoRetryTimers.delete(operation.id);

    // Check if still online and operation still exists
    if (!isOnline) {
      console.log(`[OfflineSync] Auto-retry cancelled: offline`);
      return;
    }

    const op = pendingOperations.find(o => o.id === operation.id);
    if (!op || op.status === "discarded" || op.status === "failed") {
      console.log(`[OfflineSync] Auto-retry cancelled: operation no longer pending`);
      return;
    }

    console.log(`[OfflineSync] Auto-retrying: ${operation.type} (${operation.id})`);

    // Trigger queue processing
    processQueue();
  }, delay);

  autoRetryTimers.set(operation.id, timer);
}

/**
 * Schedule auto-retry for all pending operations after coming back online.
 */
function scheduleAllAutoRetries(): void {
  const pendingOps = pendingOperations.filter(
    op => op.status === "pending" && op.retryCount > 0
  );

  for (const op of pendingOps) {
    scheduleAutoRetry(op);
  }

  if (pendingOps.length > 0) {
    console.log(`[OfflineSync] Scheduled auto-retry for ${pendingOps.length} operations`);
  }
}

// ============================================================================
// NETWORK MONITORING
// ============================================================================

function startNetworkListener(): void {
  unsubscribeNetInfo = NetInfo.addEventListener(handleNetworkChange);
}

function handleNetworkChange(state: NetInfoState): void {
  const wasOnline = isOnline;
  isOnline = state.isConnected === true && state.isInternetReachable !== false;
  if (wasOnline !== isOnline) {
    console.log(
      "[OfflineSync] Network status changed:",
      isOnline ? "ONLINE" : "OFFLINE"
    );
    onStatusChange?.(isOnline);

    // If came back online, debounce and sync
    if (isOnline && pendingOperations.length > 0) {
      // Schedule immediate sync for operations that haven't failed yet
      scheduleSync();

      // Also schedule auto-retries for operations that have failed before
      // This uses exponential backoff based on their retry count
      scheduleAllAutoRetries();
    }
  }
}

function scheduleSync(): void {
  // Clear existing timer
  if (debounceTimer) {
    clearTimeout(debounceTimer);
  }

  // Debounce 3 seconds before syncing
  debounceTimer = setTimeout(() => {
    processQueue();
  }, DEBOUNCE_MS);

  console.log("[OfflineSync] Sync scheduled in", DEBOUNCE_MS, "ms");
}

// ============================================================================
// QUEUE MANAGEMENT
// ============================================================================

/**
 * Generate an entity key for operation collapsing.
 */
function generateEntityKey(op: Partial<OfflineOperation>): string | undefined {
  switch (op.type) {
    case "create_order":
      return `order:${op.localOrderId}`;
    case "add_item":
    case "update_item":
    case "update_item_quantity":
    case "replace_modifiers":
    case "void_item":
    case "remove_item":
      return op.localItemId ? `item:${op.localItemId}` : undefined;
    case "update_order_status":
      return `order_status:${op.localOrderId}`;
    case "process_cash_payment":
    case "process_card_payment":
      // Each payment is unique, don't collapse
      return undefined;
    default:
      return undefined;
  }
}

/**
 * Check if an operation can be collapsed into an existing one.
 * Returns the operation to collapse into, or null if no collapsing possible.
 */
function findCollapseTarget(
  entityKey: string,
  newType: OperationType
): OfflineOperation | null {
  // Only collapse updates, not creates or deletes
  const collapsibleTypes: OperationType[] = [
    "update_item",
    "update_item_quantity",
    "replace_modifiers",
    "update_order_status",
  ];

  if (!collapsibleTypes.includes(newType)) {
    return null;
  }

  // Find the most recent pending operation with the same entity key
  const candidates = pendingOperations
    .filter(
      (op) =>
        op.entityKey === entityKey &&
        op.status === "pending" &&
        collapsibleTypes.includes(op.type)
    )
    .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

  return candidates[0] || null;
}

/**
 * Add an operation to the offline queue.
 * Supports priority ordering, dependency tracking, and operation collapsing.
 */
export async function queueOperation(
  op: Omit<OfflineOperation, "id" | "timestamp" | "retryCount" | "status" | "priority">
): Promise<string> {
  // Phase 5: All visible orders can have operations queued
  // Local orders (order_xxx) need CREATE_ORDER first
  // Backend orders (UUIDs) already exist and can accept item operations directly

  const priority = OPERATION_PRIORITY[op.type] ?? 99;
  const entityKey = generateEntityKey(op);

  // Check for operation collapsing
  if (entityKey) {
    const collapseTarget = findCollapseTarget(entityKey, op.type);
    if (collapseTarget) {
      // Merge params into existing operation
      collapseTarget.params = { ...collapseTarget.params, ...op.params };
      collapseTarget.timestamp = new Date().toISOString();
      if (op.contextSnapshot) {
        collapseTarget.contextSnapshot = {
          ...collapseTarget.contextSnapshot,
          ...op.contextSnapshot,
        };
      }
      await saveQueueToStorage();
      console.log(
        "[OfflineSync] Collapsed operation into:",
        collapseTarget.id,
        collapseTarget.type
      );
      return collapseTarget.id;
    }
  }

  const operation: OfflineOperation = {
    ...op,
    id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    timestamp: new Date().toISOString(),
    retryCount: 0,
    status: "pending",
    priority,
    entityKey,
  };

  pendingOperations.push(operation);
  await saveQueueToStorage();
  onQueueChange?.(getActivePendingCount());

  console.log(
    "[OfflineSync] Queued operation:",
    operation.type,
    operation.id,
    `(priority: ${priority})`
  );

  // If online, schedule immediate sync
  if (isOnline) {
    scheduleSync();
  }

  return operation.id;
}

/**
 * Queue an operation with explicit dependency on another operation.
 */
export async function queueDependentOperation(
  op: Omit<OfflineOperation, "id" | "timestamp" | "retryCount" | "status" | "priority">,
  dependsOnOperationId: string
): Promise<string> {
  const opWithDep = { ...op, dependsOn: dependsOnOperationId };
  return queueOperation(opWithDep);
}

// ============================================================================
// Phase 6: OPERATION BUNDLING
// ============================================================================

/**
 * Bundle options for atomic operation execution.
 */
export interface BundleOptions {
  rollbackOnFailure?: boolean;  // If true, mark all ops as failed if any fail
  expectedVersion?: number;     // Version check before executing bundle
}

/**
 * Queue multiple operations as an atomic bundle.
 * All operations in the bundle will be executed in sequence.
 * If any operation fails and rollbackOnFailure is true, remaining ops are marked failed.
 *
 * @param operations Array of operations to bundle (executed in order)
 * @param options Bundle execution options
 * @returns Array of operation IDs in bundle order
 */
export async function queueOperationBundle(
  operations: Array<Omit<OfflineOperation, "id" | "timestamp" | "retryCount" | "status" | "priority">>,
  options: BundleOptions = {}
): Promise<string[]> {
  if (operations.length === 0) {
    return [];
  }

  const bundleId = `bundle_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  const operationIds: string[] = [];

  for (let i = 0; i < operations.length; i++) {
    const op = operations[i];
    const priority = OPERATION_PRIORITY[op.type] ?? 99;
    const entityKey = generateEntityKey(op);

    const operation: OfflineOperation = {
      ...op,
      id: `op_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      timestamp: new Date().toISOString(),
      retryCount: 0,
      status: "pending",
      priority,
      entityKey,
      // Bundle-specific fields
      bundleId,
      bundleSequence: i,
      rollbackOnBundleFailure: options.rollbackOnFailure ?? true,
      expectedVersion: i === 0 ? options.expectedVersion : undefined, // Only first op checks version
      // Chain dependency within bundle
      dependsOn: i > 0 ? operationIds[i - 1] : op.dependsOn,
    };

    pendingOperations.push(operation);
    operationIds.push(operation.id);

    console.log(
      "[OfflineSync] Bundled operation:",
      operation.type,
      operation.id,
      `(bundle: ${bundleId}, seq: ${i})`
    );
  }

  await saveQueueToStorage();
  onQueueChange?.(getActivePendingCount());

  // If online, schedule immediate sync
  if (isOnline) {
    scheduleSync();
  }

  return operationIds;
}

/**
 * Get all operations in a bundle.
 */
export function getBundleOperations(bundleId: string): OfflineOperation[] {
  return pendingOperations
    .filter((op) => op.bundleId === bundleId)
    .sort((a, b) => (a.bundleSequence ?? 0) - (b.bundleSequence ?? 0));
}

/**
 * Mark all remaining operations in a bundle as failed.
 * Called when a bundle operation fails and rollbackOnBundleFailure is true.
 */
export async function failBundle(bundleId: string, failedOpId: string): Promise<void> {
  pendingOperations = pendingOperations.map((op) => {
    if (op.bundleId === bundleId && op.id !== failedOpId && op.status === "pending") {
      return { ...op, status: "discarded" as const };
    }
    return op;
  });

  await saveQueueToStorage();
  console.log("[OfflineSync] Bundle failed, discarded remaining ops:", bundleId);
}

/**
 * Check if all operations in a bundle have completed successfully.
 */
export function isBundleComplete(bundleId: string): boolean {
  const bundleOps = getBundleOperations(bundleId);
  if (bundleOps.length === 0) return true;

  return bundleOps.every((op) => op.status !== "pending" && op.status !== "processing");
}

/**
 * Get count of active pending operations (excluding blocked).
 */
function getActivePendingCount(): number {
  return pendingOperations.filter(
    (op) => op.status === "pending" || op.status === "blocked"
  ).length;
}

/**
 * Remove an operation from the queue (after success or permanent failure).
 */
export async function removeOperation(operationId: string): Promise<void> {
  pendingOperations = pendingOperations.filter((op) => op.id !== operationId);
  await saveQueueToStorage();
  onQueueChange?.(getActivePendingCount());
}

/**
 * Mark an operation as discarded (conflict resolution).
 */
export async function discardOperation(operationId: string): Promise<void> {
  pendingOperations = pendingOperations.map((op) =>
    op.id === operationId ? { ...op, status: "discarded" as const } : op
  );
  await saveQueueToStorage();
  onQueueChange?.(getActivePendingCount());
}

/**
 * Retry a failed operation.
 */
export async function retryFailedOperation(operationId: string): Promise<void> {
  const op = pendingOperations.find((o) => o.id === operationId);
  if (op && op.status === "failed") {
    op.status = "pending";
    op.retryCount = 0;
    await saveQueueToStorage();
    onQueueChange?.(getActivePendingCount());

    if (isOnline) {
      scheduleSync();
    }
  }
}

/**
 * Get count of pending operations.
 */
export function getPendingCount(): number {
  return pendingOperations.filter((op) => op.status === "pending").length;
}

/**
 * Get count of failed operations.
 */
export function getFailedCount(): number {
  return pendingOperations.filter((op) => op.status === "failed").length;
}

/**
 * Get all failed operations (for UI display).
 */
export function getFailedOperations(): OfflineOperation[] {
  return pendingOperations.filter((op) => op.status === "failed");
}

/**
 * Get pending payment operations count.
 */
export function getPendingPaymentsCount(): number {
  return pendingOperations.filter(
    (op) =>
      (op.type === "process_payment" || op.type === "process_cash_payment" || op.type === "process_card_payment") &&
      (op.status === "pending" || op.status === "blocked" || op.status === "processing")
  ).length;
}

/**
 * Get failed payment operations.
 */
export function getFailedPayments(): OfflineOperation[] {
  return pendingOperations.filter(
    (op) =>
      (op.type === "process_payment" || op.type === "process_cash_payment" || op.type === "process_card_payment") &&
      op.status === "failed"
  );
}

/**
 * Get all operations for a specific order.
 */
export function getOperationsForOrder(localOrderId: string): OfflineOperation[] {
  return pendingOperations.filter((op) => op.localOrderId === localOrderId);
}

/**
 * Check if there's a pending create_order operation for a given order.
 * Used to block items/payments until order is created.
 */
export function hasPendingOrderCreation(localOrderId: string): boolean {
  return pendingOperations.some(
    (op) =>
      op.localOrderId === localOrderId &&
      op.type === "create_order" &&
      (op.status === "pending" || op.status === "processing" || op.status === "blocked")
  );
}

/**
 * Get the create_order operation ID for a given order, if it exists.
 */
export function getOrderCreationOperationId(localOrderId: string): string | null {
  const op = pendingOperations.find(
    (op) =>
      op.localOrderId === localOrderId &&
      op.type === "create_order" &&
      (op.status === "pending" || op.status === "processing" || op.status === "blocked")
  );
  return op?.id || null;
}

/**
 * Cancel all operations for an order (e.g., when order is voided).
 */
export async function cancelOrderOperations(localOrderId: string): Promise<void> {
  const opsToCancel = pendingOperations.filter(
    (op) => op.localOrderId === localOrderId && op.status !== "discarded"
  );

  for (const op of opsToCancel) {
    op.status = "discarded";
  }

  await saveQueueToStorage();
  onQueueChange?.(getActivePendingCount());
  console.log(
    `[OfflineSync] Cancelled ${opsToCancel.length} operations for order:`,
    localOrderId
  );
}

/**
 * Update operation params (e.g., after ID resolution).
 */
export async function updateOperationParams(
  operationId: string,
  params: Record<string, any>
): Promise<void> {
  const op = pendingOperations.find((o) => o.id === operationId);
  if (op) {
    op.params = { ...op.params, ...params };
    await saveQueueToStorage();
  }
}

/**
 * Get current online status.
 */
export function getIsOnline(): boolean {
  return isOnline;
}

/**
 * Check if auto-retry is in progress (for UI indicator).
 */
export function isAutoRetryInProgress(): boolean {
  return autoRetryTimers.size > 0;
}

/**
 * Get count of operations scheduled for auto-retry.
 */
export function getAutoRetryCount(): number {
  return autoRetryTimers.size;
}

/**
 * Force sync now (for manual retry button).
 */
export async function syncNow(): Promise<void> {
  if (isOnline) {
    await processQueue();
  }
}

/**
 * Get a detailed status of the queue for debugging.
 */
export function getQueueStatus(): {
  total: number;
  pending: number;
  blocked: number;
  processing: number;
  failed: number;
  byType: Record<string, number>;
  byOrder: Record<string, { types: string[]; hasCreateOrder: boolean }>;
} {
  const allOps = pendingOperations.filter((op) => op.status !== "discarded");
  const byType: Record<string, number> = {};
  const byOrder: Record<string, { types: string[]; hasCreateOrder: boolean }> = {};

  for (const op of allOps) {
    byType[op.type] = (byType[op.type] || 0) + 1;

    if (op.localOrderId) {
      if (!byOrder[op.localOrderId]) {
        byOrder[op.localOrderId] = { types: [], hasCreateOrder: false };
      }
      byOrder[op.localOrderId].types.push(`${op.type}(${op.status})`);
      if (op.type === "create_order") {
        byOrder[op.localOrderId].hasCreateOrder = true;
      }
    }
  }

  return {
    total: allOps.length,
    pending: allOps.filter((op) => op.status === "pending").length,
    blocked: allOps.filter((op) => op.status === "blocked").length,
    processing: allOps.filter((op) => op.status === "processing").length,
    failed: allOps.filter((op) => op.status === "failed").length,
    byType,
    byOrder,
  };
}

/**
 * Log the current queue status to console (for debugging).
 */
export function logQueueStatus(): void {
  const status = getQueueStatus();
  console.log("[OfflineSync] ====== QUEUE STATUS ======");
  console.log(`[OfflineSync] Total: ${status.total}`);
  console.log(`[OfflineSync]   Pending: ${status.pending}`);
  console.log(`[OfflineSync]   Blocked: ${status.blocked}`);
  console.log(`[OfflineSync]   Processing: ${status.processing}`);
  console.log(`[OfflineSync]   Failed: ${status.failed}`);
  console.log("[OfflineSync] By type:", JSON.stringify(status.byType));
  console.log("[OfflineSync] By order:");
  for (const [orderId, info] of Object.entries(status.byOrder)) {
    console.log(`[OfflineSync]   ${orderId}:`);
    console.log(`[OfflineSync]     hasCreateOrder: ${info.hasCreateOrder}`);
    console.log(`[OfflineSync]     operations: ${info.types.join(", ")}`);
  }
}

// ============================================================================
// QUEUE PROCESSING
// ============================================================================

/**
 * Sort operations by priority and timestamp for processing order.
 */
function sortOperationsByPriority(ops: OfflineOperation[]): OfflineOperation[] {
  return [...ops].sort((a, b) => {
    // First by priority (lower = higher priority)
    const priorityDiff = (a.priority ?? 99) - (b.priority ?? 99);
    if (priorityDiff !== 0) return priorityDiff;

    // Then by timestamp (older first)
    return new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime();
  });
}

/**
 * Check if an operation's dependencies are satisfied.
 * 
 * IMPLICIT DEPENDENCIES:
 * - add_item, process_payment, process_cash_payment, process_card_payment
 *   all implicitly depend on create_order for the same localOrderId.
 * - These operations will be blocked until create_order completes.
 */
function areDependenciesSatisfied(op: OfflineOperation): boolean {
  // EXPLICIT dependency check
  if (op.dependsOn) {
    const dependency = pendingOperations.find((o) => o.id === op.dependsOn);

    // If dependency doesn't exist in queue, it's either completed or never existed
    if (!dependency) {
      // Check if it was removed (completed) - continue
    } else if (
      dependency.status === "pending" ||
      dependency.status === "processing" ||
      dependency.status === "blocked"
    ) {
      return false;
    }
  }

  // IMPLICIT dependency: items and payments must wait for order creation
  const typesRequiringOrder = [
    "add_item",
    "apply_discount",
    "process_payment",
    "process_cash_payment",
    "process_card_payment",
    "update_order_status",
    "fire_course",
  ];

  if (typesRequiringOrder.includes(op.type) && op.localOrderId) {
    // Check if there's a pending create_order for this order
    const orderCreationPending = pendingOperations.some(
      (o) =>
        o.localOrderId === op.localOrderId &&
        o.type === "create_order" &&
        (o.status === "pending" || o.status === "processing" || o.status === "blocked")
    );

    if (orderCreationPending) {
      console.log(
        `[OfflineSync] ${op.type} blocked - waiting for create_order of ${op.localOrderId}`
      );
      return false;
    }
  }

  return true;
}

/**
 * Get all operations that are ready to process (pending + dependencies satisfied).
 */
function getReadyOperations(): OfflineOperation[] {
  const pending = pendingOperations.filter((op) => op.status === "pending");
  const ready = pending.filter((op) => areDependenciesSatisfied(op));
  return sortOperationsByPriority(ready);
}

/**
 * Mark operations as blocked if their dependencies aren't satisfied.
 */
async function updateBlockedOperations(): Promise<void> {
  let changed = false;

  for (const op of pendingOperations) {
    if (op.status === "pending" && !areDependenciesSatisfied(op)) {
      op.status = "blocked";
      changed = true;
    } else if (op.status === "blocked" && areDependenciesSatisfied(op)) {
      op.status = "pending";
      changed = true;
    }
  }

  if (changed) {
    await saveQueueToStorage();
  }
}

/**
 * Process all pending operations in priority order with dependency tracking.
 */
async function processQueue(): Promise<void> {
  if (syncInProgress) {
    console.log("[OfflineSync] Sync already in progress, skipping");
    return;
  }

  if (!isOnline) {
    console.log("[OfflineSync] Offline, skipping sync");
    return;
  }

  if (!executeOperation) {
    console.error("[OfflineSync] No executeOperation handler registered");
    return;
  }

  // ========================================================================
  // COMPREHENSIVE QUEUE STATUS LOGGING
  // ========================================================================
  const allOps = pendingOperations.filter(
    (op) => op.status !== "discarded" && op.status !== "failed"
  );
  const byType: Record<string, number> = {};
  const byOrder: Record<string, string[]> = {};

  for (const op of allOps) {
    byType[op.type] = (byType[op.type] || 0) + 1;
    if (!byOrder[op.localOrderId]) {
      byOrder[op.localOrderId] = [];
    }
    byOrder[op.localOrderId].push(`${op.type}(${op.status})`);
  }

  console.log("[OfflineSync] ====== QUEUE STATUS ======");
  console.log("[OfflineSync] Total operations:", allOps.length);
  console.log("[OfflineSync] By type:", JSON.stringify(byType));
  console.log("[OfflineSync] By order:", JSON.stringify(byOrder));

  // Update blocked status before processing
  await updateBlockedOperations();

  const readyOps = getReadyOperations();
  const blocked = pendingOperations.filter((op) => op.status === "blocked");
  const pending = pendingOperations.filter((op) => op.status === "pending");

  console.log("[OfflineSync] Ready:", readyOps.length, "| Blocked:", blocked.length, "| Pending:", pending.length);

  if (readyOps.length === 0) {
    if (blocked.length > 0) {
      console.log("[OfflineSync] Blocked operations:");
      for (const op of blocked.slice(0, 5)) {
        console.log(`  - ${op.type} (${op.id}) for order ${op.localOrderId}`);
      }
    } else {
      console.log("[OfflineSync] No pending operations");
    }
    return;
  }

  syncInProgress = true;
  console.log("[OfflineSync] ====== PROCESSING ======");
  console.log("[OfflineSync] Processing", readyOps.length, "operations (by priority)");

  let successCount = 0;
  let failCount = 0;

  for (const operation of readyOps) {
    // Check if still online before each operation
    if (!isOnline) {
      console.log("[OfflineSync] Went offline during sync, stopping");
      break;
    }

    // Mark as processing
    operation.status = "processing";
    await saveQueueToStorage();

    try {
      console.log(`[OfflineSync] Executing: ${operation.type} (${operation.id})`);
      console.log(`[OfflineSync]   Order: ${operation.localOrderId || 'N/A'}`);
      console.log(`[OfflineSync]   Item: ${operation.localItemId || 'N/A'}`);

      const success = await executeOperation(operation);

      if (success) {
        console.log(`[OfflineSync] ✓ SUCCESS: ${operation.type} (${operation.id})`);
        await removeOperation(operation.id);
        successCount++;

        // After completing an operation, unblock dependent operations
        await updateBlockedOperations();
      } else {
        // Increment retry count
        operation.retryCount++;
        failCount++;

        if (operation.retryCount >= MAX_RETRY_ATTEMPTS) {
          // Max retries reached - mark as failed for manual intervention
          console.log(`[OfflineSync] ✗ FAILED (max retries): ${operation.type} (${operation.id})`);
          console.log(`[OfflineSync]   Order: ${operation.localOrderId || 'N/A'}`);
          operation.status = "failed";
          await saveQueueToStorage();

          // Notify about failed operation (especially for payments)
          onOperationFailed?.(operation);
        } else {
          // Reset to pending for next retry with exponential backoff
          operation.status = "pending";
          await saveQueueToStorage();
          console.log(`[OfflineSync] ⟳ RETRY: ${operation.type} (${operation.id}) - attempt ${operation.retryCount}/${MAX_RETRY_ATTEMPTS}`);

          // Schedule automatic retry with exponential backoff
          scheduleAutoRetry(operation);
        }
      }
    } catch (error) {
      console.error(
        "[OfflineSync] Error executing operation:",
        operation.id,
        error
      );
      operation.retryCount++;
      failCount++;

      if (operation.retryCount >= MAX_RETRY_ATTEMPTS) {
        operation.status = "failed";
        await saveQueueToStorage();
        onOperationFailed?.(operation);
      } else {
        operation.status = "pending";
        await saveQueueToStorage();
        // Schedule automatic retry with exponential backoff
        scheduleAutoRetry(operation);
      }
    }
  }

  syncInProgress = false;
  onQueueChange?.(getActivePendingCount());
  console.log(
    `[OfflineSync] Sync complete: ${successCount} succeeded, ${failCount} failed`
  );

  // If we had failures but there are still ready operations, try again
  const stillReady = getReadyOperations();
  if (stillReady.length > 0 && isOnline) {
    console.log(
      "[OfflineSync] Still have ready operations, scheduling retry..."
    );
    scheduleSync();
  }
}

// ============================================================================
// PERSISTENCE
// ============================================================================

async function loadQueueFromStorage(): Promise<void> {
  try {
    // Synchronous read from MMKV
    const stored = getSyncJSON<OfflineOperation[]>(STORAGE_KEY);
    if (stored) {
      pendingOperations = stored;
      // Reset any "processing" status to "pending" (in case app crashed during sync)
      pendingOperations = pendingOperations.map((op) =>
        op.status === "processing" ? { ...op, status: "pending" as const } : op
      );
      console.log(
        "[OfflineSync] Loaded",
        pendingOperations.length,
        "operations from storage"
      );
    }
  } catch (error) {
    console.error("[OfflineSync] Failed to load queue from storage:", error);
    pendingOperations = [];
  }
}

async function saveQueueToStorage(): Promise<void> {
  try {
    // Only persist non-discarded operations
    // Synchronous write to MMKV
    const toSave = pendingOperations.filter((op) => op.status !== "discarded");
    setSyncJSON(STORAGE_KEY, toSave);
  } catch (error) {
    console.error("[OfflineSync] Failed to save queue to storage:", error);
  }
}

// ============================================================================
// ORDER RECONCILIATION
// ============================================================================

export interface ReconciliationResult {
  success: boolean;
  itemsAdded: number;
  itemsRemoved: number;
  itemsUpdated: number;
  errors: string[];
}

/**
 * Reconcile local order state with backend after network recovery.
 * Backend is source of truth - local state is updated to match backend.
 *
 * @param supabase - Supabase client instance
 * @param localOrderId - Local order ID from useOrderStore
 * @param dbOrderId - Backend order UUID
 * @param getLocalOrder - Function to get local order state
 * @param updateLocalOrder - Function to update local order with backend state
 */
export async function reconcileOrderWithBackend(
  supabase: any,
  localOrderId: string,
  dbOrderId: string,
  getLocalOrder: () => any,
  updateLocalOrder: (updates: any) => void
): Promise<ReconciliationResult> {
  const result: ReconciliationResult = {
    success: false,
    itemsAdded: 0,
    itemsRemoved: 0,
    itemsUpdated: 0,
    errors: [],
  };

  if (!supabase || !dbOrderId) {
    result.errors.push("Missing Supabase client or order ID");
    return result;
  }

  try {
    console.log("[Reconciliation] Starting reconciliation for order:", dbOrderId);

    // Fetch backend order state
    const { data, error } = await supabase.rpc("get_order_details", {
      p_order_id: dbOrderId,
    });

    if (error) {
      result.errors.push(`Failed to fetch backend order: ${error.message}`);
      return result;
    }

    if (!data) {
      result.errors.push("No order data returned from backend");
      return result;
    }

    const localOrder = getLocalOrder();
    if (!localOrder) {
      result.errors.push("Local order not found");
      return result;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Phase 6: Version-based reconciliation
    // ═══════════════════════════════════════════════════════════════════════
    const localVersion = (localOrder as any).sync_version ?? 0;
    const serverVersion = data.sync_version ?? 0;

    // Check for pending local changes
    const hasPendingLocalChanges =
      localOrder.sync_status === "pending" ||
      localOrder.items?.some((item: any) => item.sync_status === "pending");

    // Track version mismatch for reporting
    if (serverVersion > localVersion) {
      console.log(
        "[Reconciliation] Version mismatch - local:",
        localVersion,
        "server:",
        serverVersion
      );

      if (hasPendingLocalChanges) {
        // Check if we can merge (non-overlapping changes)
        const localPendingItems = localOrder.items?.filter(
          (item: any) => item.sync_status === "pending" || !item.db_order_item_id
        ) || [];

        const serverItemIds = new Set(
          (data.items || []).map((item: any) => item.id)
        );

        // Local pending items that don't exist on server can be pushed
        const nonConflictingLocalItems = localPendingItems.filter(
          (item: any) => !item.db_order_item_id || !serverItemIds.has(item.db_order_item_id)
        );

        if (nonConflictingLocalItems.length > 0) {
          console.log(
            "[Reconciliation] Merge possible - pushing",
            nonConflictingLocalItems.length,
            "non-conflicting local items"
          );
          // These will be synced in the next queue processing
        }
      }
    } else if (serverVersion < localVersion && !hasPendingLocalChanges) {
      console.log(
        "[Reconciliation] Local version newer - skipping server merge"
      );
      // Local is newer and synced - no need to pull from server
      result.success = true;
      return result;
    }

    // Build a map of backend items by their ID
    const backendItemsMap = new Map<string, any>();
    (data.items || []).forEach((item: any) => {
      backendItemsMap.set(item.id, item);
    });

    // Build a map of local items by their db_order_item_id
    const localItemsMap = new Map<string, any>();
    (localOrder.items || []).forEach((item: any) => {
      if (item.db_order_item_id) {
        localItemsMap.set(item.db_order_item_id, item);
      }
    });

    // Detect differences
    const itemsToAdd: any[] = [];
    const itemsToUpdate: any[] = [];
    const itemIdsToRemove = new Set<string>();

    // Check backend items against local
    backendItemsMap.forEach((backendItem, backendItemId) => {
      const localItem = localItemsMap.get(backendItemId);
      if (!localItem) {
        // Item in backend but not local - add it
        itemsToAdd.push(backendItem);
        result.itemsAdded++;
      } else {
        // Item exists in both - check for updates
        if (
          backendItem.quantity !== localItem.quantity ||
          backendItem.kitchen_status !== localItem.kitchen_status
        ) {
          itemsToUpdate.push({
            localId: localItem.id,
            updates: {
              quantity: backendItem.quantity,
              kitchen_status: backendItem.kitchen_status,
              item_status: backendItem.item_status,
            },
          });
          result.itemsUpdated++;
        }
      }
    });

    // Check local items that are not in backend (should be removed)
    localItemsMap.forEach((localItem, dbItemId) => {
      if (!backendItemsMap.has(dbItemId)) {
        // Item in local but not backend - mark for removal
        itemIdsToRemove.add(localItem.id);
        result.itemsRemoved++;
      }
    });

    // Apply reconciliation updates
    const reconciledItems = localOrder.items
      .filter((item: any) => !itemIdsToRemove.has(item.id))
      .map((item: any) => {
        const update = itemsToUpdate.find((u) => u.localId === item.id);
        if (update) {
          return { ...item, ...update.updates, sync_status: "synced" as const };
        }
        // Mark existing items as synced
        return item.db_order_item_id
          ? { ...item, sync_status: "synced" as const }
          : item;
      });

    // Add new items from backend
    itemsToAdd.forEach((backendItem) => {
      reconciledItems.push({
        id: `sync_${backendItem.id}`,
        db_order_item_id: backendItem.id,
        menuItemId: backendItem.menu_item_id || "",
        // For open items, use open_item_name; otherwise use item_name
        name: backendItem.is_open_item ? (backendItem.open_item_name || "Open Item") : (backendItem.item_name || "Unknown Item"),
        quantity: backendItem.quantity || 1,
        // For open items, use open_item_price; otherwise use unit_price
        price: backendItem.is_open_item ? (backendItem.open_item_price || 0) : (backendItem.unit_price || 0),
        unitPrice: backendItem.is_open_item ? (backendItem.open_item_price || 0) : (backendItem.unit_price || 0),
        cashPrice: backendItem.cash_price || backendItem.cash_unit_price || (backendItem.is_open_item ? backendItem.open_item_price : backendItem.unit_price) || 0,
        originalPrice: backendItem.cash_price || (backendItem.is_open_item ? backendItem.open_item_price : backendItem.unit_price) || 0,
        paidQuantity: backendItem.paid_quantity || 0,
        // Open item support
        is_open_item: backendItem.is_open_item || false,
        open_item_name: backendItem.open_item_name || undefined,
        open_item_price: backendItem.open_item_price || undefined,
        kitchen_status: backendItem.kitchen_status,
        item_status: backendItem.item_status,
        courseNumber: backendItem.course_number || 1,
        category_name: backendItem.category_name || "Uncategorized",
        is_voided: backendItem.is_voided || false,
        sync_status: "synced" as const,
        customizations: {
          notes: backendItem.special_instructions || undefined,
          modifiers: [], // Would need more data to populate
        },
        // Financial fields
        subtotal: backendItem.subtotal || ((backendItem.is_open_item ? backendItem.open_item_price : backendItem.unit_price) * backendItem.quantity) || 0,
        cashSubtotal: backendItem.cash_subtotal || (backendItem.cash_price * backendItem.quantity) || 0,
        taxRate: backendItem.tax_rate || 0,
        taxAmount: backendItem.tax_amount || 0,
        cashTaxAmount: backendItem.cash_tax_amount || 0,
        // Discount distribution fields
        discount_amount: backendItem.discount_amount ?? 0,
        discount_cash_amount: backendItem.discount_cash_amount ?? backendItem.discount_amount ?? 0,
      });
    });

    // Update local order with reconciled state
    // Phase 6: Include sync_version in reconciled state
    updateLocalOrder({
      items: reconciledItems,
      total_amount: data.total_amount,
      total_tax: data.tax_amount,
      order_status: data.status,
      sync_version: serverVersion, // Phase 6: Update local version to match server
      amount_paid: data.amount_paid,
      amount_due: data.amount_due,
      cash_amount_due: data.cash_amount_due,
    });

    result.success = true;
    console.log("[Reconciliation] Complete:", result, "- sync_version updated to:", serverVersion);

    return result;
  } catch (err: any) {
    result.errors.push(`Reconciliation error: ${err?.message || "Unknown"}`);
    console.error("[Reconciliation] Error:", err);
    return result;
  }
}

/**
 * Trigger reconciliation for all orders with failed sync status.
 */
export async function reconcileFailedOrders(
  supabase: any,
  getOrdersWithFailedSyncs: () => Array<{ localId: string; dbId: string }>,
  getLocalOrder: (id: string) => any,
  updateLocalOrder: (id: string, updates: any) => void
): Promise<void> {
  const failedOrders = getOrdersWithFailedSyncs();

  if (failedOrders.length === 0) {
    console.log("[Reconciliation] No orders with failed syncs");
    return;
  }

  console.log(
    `[Reconciliation] Reconciling ${failedOrders.length} orders with failed syncs`
  );

  for (const order of failedOrders) {
    await reconcileOrderWithBackend(
      supabase,
      order.localId,
      order.dbId,
      () => getLocalOrder(order.localId),
      (updates) => updateLocalOrder(order.localId, updates)
    );
  }
}

