function mapBackendOrderStatus(status: string): OrderProfile['order_status'] {
  const map: Record<string, OrderProfile['order_status']> = {
    'draft': 'draft',
    'pending': 'pending',
    'preparing': 'preparing',
    'ready': 'ready',
    'completed': 'completed',
    'cancelled': 'cancelled',
    'refunded': 'refunded',
    'void': 'void',
  };
  return map[status] || 'pending';
}

