            const createdSchedule: WeeklySchedule = {
              ...newSchedule,
              id,
              shifts: [],
              createdAt: new Date().toISOString(),
              updatedAt: new Date().toISOString(),
              type: "weekly",
            };
            set((state) => {
              state.weeklySchedules.push(createdSchedule);
