          },

          addSchedulePeriod: (newPeriod) => {
            const id = generateId();
            const newSchedulePeriod: SchedulePeriod = {
              ...newPeriod,
              id,
              shifts: [],
              createdAt: new Date().toISOString(),
              updatedAt: new Date().toISOString(),
